function returnToStudioHome(){
    try {
        const app = window.parent?.__XXPD_APP__;
        if(window.parent && window.parent !== window && typeof app?.showHome === 'function'){
            app.showHome(app.workspaceName);
            return;
        }
    } catch(e) {}
    window.location.assign('/');
}
function toggleCanvasTheme(buttonOrEvent){
    if (buttonOrEvent && typeof buttonOrEvent.preventDefault === 'function') buttonOrEvent.preventDefault();
    if (buttonOrEvent && typeof buttonOrEvent.stopPropagation === 'function') buttonOrEvent.stopPropagation();
    try {
        if (window.parent && window.parent !== window && typeof window.parent.toggleGlobalAppTheme === 'function') {
            window.parent.toggleGlobalAppTheme();
            return;
        }
        if (window.parent && window.parent !== window && window.parent.__XXPD_APP__?.toggleThemeWithAnimation) {
            window.parent.__XXPD_APP__.toggleThemeWithAnimation();
            return;
        }
    } catch (_) {}
    const isDark = document.documentElement.classList.contains('theme-dark') ||
                   document.documentElement.classList.contains('studio-theme-dark') ||
                   document.documentElement.getAttribute('data-theme') === 'dark';
    const nextTheme = isDark ? 'light' : 'dark';
    applyTheme(nextTheme);
}
window.toggleCanvasTheme = toggleCanvasTheme;

canvasSideNavButtons.forEach(button => {
    button.addEventListener('pointerdown', event => {
        event.stopPropagation();
        // 侧栏按钮在画布拖拽状态下可能丢失首个 click，按下时主动派发一次并屏蔽后续原生 click。
        if(event.button !== 0 || button.dataset.navPointerHandled === '1') return;
        event.preventDefault();
        button.dataset.navPointerHandled = '1';
        window.__navLastClickTime = Date.now();
        button.dispatchEvent(new MouseEvent('click', {bubbles:true, cancelable:true, view:window}));
    });
    button.addEventListener('click', event => {
        event.preventDefault();
        event.stopPropagation();
        if(button.dataset.navPointerHandled === '1') button.dataset.navPointerHandled = '2';
        else if(button.dataset.navPointerHandled === '2') { delete button.dataset.navPointerHandled; return; }
        button.blur();
        if(button.dataset.navAction === 'home'){
            returnToStudioHome();
            return;
        }
        if(button.dataset.navAction === 'assets'){
            toggleAssetLibrary();
            return;
        }
        if(button.dataset.navAction === 'log'){
            SmartPanelManager.toggle('log');
            return;
        }
        if(button.dataset.navAction === 'theme'){
            toggleCanvasTheme(button);
            return;
        }
        if(button.dataset.navAction === 'workflow' || button.dataset.navAction === 'settings'){
            SmartPanelManager.toggle('workflow');
            return;
        }
        button.classList.remove('is-activating');
        button.classList.add('is-activating');
    });
    button.addEventListener('animationend', () => button.classList.remove('is-activating'));
});
