function volcengineSeedanceFamily(modelId){
    if(!modelId) return '2.5';
    const v = String(modelId || '').toLowerCase().replace(/[\s_.]/g, '-');
    if(v.includes('seedance-2-5') || v.includes('seedance-25') || v.includes('seedance2-5') || v.includes('doubao-seedance-2-5') || v.includes('2-5')) return '2.5';
    if(v.includes('seedance-2-0') || v.includes('seedance-20') || v.includes('seedance2-0') || v.includes('doubao-seedance-2-0') || v.includes('2-0')) return '2.0';
    return '2.5';
}
function videoParamProvider(target){
    const id = String(target?.videoProvider || target?.provider_id || '');
    if(!id) return null;
    return (typeof apiProviders !== 'undefined' ? apiProviders : []).find(p => p && p.id === id) || null;
}
function isMiniMaxH3MaxModel(modelId){
    const v = String(modelId || '').toLowerCase().replace(/[_.]/g, '-');
    return v.includes('h3-max') || (v.includes('minimax-h3') && v.endsWith('-max'));
}
function isMiniMaxVideoModel(modelId, provider){
    const proto = String(provider?.protocol || '').toLowerCase();
    const v = String(modelId || '').toLowerCase();
    if(proto === 'minimax') return true;
    return v.includes('minimax-h3') || v.includes('minimax_h3') || v.includes('minimax-hailuo') || v.includes('hailuo-02') || v.includes('hailuo2');
}
function isSoraVideoModel(modelId){
    const v = String(modelId || '').toLowerCase().replace(/[_.]/g, '-');
    return v.includes('sora-2') || v === 'sora2' || v.startsWith('sora2-');
}
function isSoraProVideoModel(modelId){
    return isSoraVideoModel(modelId) && String(modelId || '').toLowerCase().includes('pro');
}
function videoCompositeResolutions(modelId, provider){
    const family = volcengineSeedanceFamily(modelId);
    if(isSoraVideoModel(modelId)) return isSoraProVideoModel(modelId) ? ['720p', '1080p'] : ['720p'];
    if(isMiniMaxVideoModel(modelId, provider)) return isMiniMaxH3MaxModel(modelId) ? ['480p', '768p'] : ['768p', '2k'];
    if(family === '2.5') return ['480p', '720p', '1080p'];
    if(family === '2.0') return ['480p', '720p', '1080p', '4k'];
    return ['480p', '720p', '1080p'];
}
function videoCompositeRatios(modelId, provider){
    if(isSoraVideoModel(modelId)) return ['16:9', '9:16'];
    return ['21:9', '16:9', '4:3', '1:1', '3:4', '9:16'];
}
function videoCompositeDurations(modelId, provider){
    if(isSoraVideoModel(modelId)) return [4, 8, 12];
    if(isMiniMaxVideoModel(modelId, provider)){
        if(isMiniMaxH3MaxModel(modelId)) return Array.from({length: 11}, (_, i) => i + 5);
        return Array.from({length: 12}, (_, i) => i + 4);
    }
    const family = volcengineSeedanceFamily(modelId);
    if(family === '2.5') return Array.from({length: 27}, (_, i) => 4 + i);
    if(family === '2.0') return Array.from({length: 12}, (_, i) => i + 4);
    return Array.from({length: 27}, (_, i) => i + 4);
}
function videoSeedanceRefCaps(modelId){
    return volcengineSeedanceFamily(modelId) === '2.5' ? {images:30, videos:10, audios:10} : {images:9, videos:3, audios:3};
}
function normalizeVideoDurationValue(raw, modelId, provider){
    const n = Number(raw);
    const allowed = videoCompositeDurations(modelId, provider);
    if(Number.isFinite(n) && allowed.includes(n)) return n;
    return allowed.includes(5) ? 5 : (allowed.find(d => d > 0) || 5);
}
function snapVideoParamsToModel(target){
    if(!target || typeof target !== 'object') return target;
    const modelId = target.videoModel || target.model || '';
    const provider = videoParamProvider(target);
    target.videoDuration = normalizeVideoDurationValue(target.videoDuration, modelId, provider);
    const ress = videoCompositeResolutions(modelId, provider);
    const res = String(target.videoResolution || '').trim().toLowerCase();
    if(!ress.includes(res)) target.videoResolution = ress.includes('720p') ? '720p' : ress[0];
    const ratios = videoCompositeRatios(modelId, provider);
    const aspect = String(target.videoAspect || '').trim();
    if(aspect === 'adaptive' || !ratios.includes(aspect)) target.videoAspect = ratios.includes('16:9') ? '16:9' : ratios[0];
    return target;
}
