function scheduleSmartCanvasImportFinalize(){
    if(smartCanvasImportFinalizeRaf) cancelAnimationFrame(smartCanvasImportFinalizeRaf);
    smartCanvasImportFinalizeRaf = requestAnimationFrame(() => {
        smartCanvasImportFinalizeRaf = 0;
        smartCanvasImportBusy = false;
        renderMinimap();
        bindSmartPreviewImageFallbacks(world);
        bindCanvasImageProxyFallbacks();
        wakeVisibleCanvasMedia();
        syncSmartSelectedImageResolution(world);
        measureSmartNodeImages();
        refreshRunTimerPills();
        restoreActiveCanvasToolSessions();
    });
}

function startCanvasNodeDrag(e, nodeId, origin={}){
    const id = String(nodeId || '');
    if(!id || !e) return false;
    if(document.body.classList.contains('in-video-crop') && String(window.__activeVideoCropNodeId || '') === id) return false;
    if((document.body.classList.contains('in-image-crop') && String(window.__activeImageCropNodeId || '') === id) || (typeof activeImageCrop !== 'undefined' && activeImageCrop && String(activeImageCrop.nodeId) === id)) return false;
    if(activeGridCut && String(activeGridCut.nodeId) === id) return false;
    let node = nodes.find(n => String(n.id) === id);
    if(!node) return false;
    if(node.groupId){
        const parent = nodes.find(n => n.id === node.groupId);
        if(parent && parent.gridSplitGroup) node = parent;
    }
    if(e.altKey) node = duplicateForAltDrag(node, e.shiftKey);
    let dragIds = selectedIds.includes(node.id) ? selectedIds.slice() : [node.id];
    if(isSmartGroupNode(node)){
        const memberIds = smartGroupMembers(node).map(member => member.id);
        dragIds = Array.from(new Set([...dragIds, ...memberIds]));
    }
    const group = dragIds.map(dragId => {
        const n = nodes.find(x => x.id === dragId);
        return n ? {id:n.id, ox:Number(n.x) || 0, oy:Number(n.y) || 0} : null;
    }).filter(Boolean);
    const startX = Number.isFinite(origin.startX) ? origin.startX : e.clientX;
    const startY = Number.isFinite(origin.startY) ? origin.startY : e.clientY;
    const startWorld = origin.startWorld || screenToWorld({clientX:startX, clientY:startY});
    dragState = {
        id: node.id,
        startX,
        startY,
        ox: Number(node.x) || 0,
        oy: Number(node.y) || 0,
        startWorld,
        startVx: viewport.x,
        startVy: viewport.y,
        group,
        groupIds: group.map(item => item.id),
        ctrlGroup: Boolean(e.ctrlKey)
    };
    document.body.classList.add('smart-node-drag');
    shell?.classList?.add('smart-node-drag');
    if(window.CanvasTrash?.closeMorePopover) window.CanvasTrash.closeMorePopover();
    capturePendingUndo();
    return true;
}

function getSmartGhostDimensions(aspectRatio){ return window.SmartCanvasUtils.getSmartGhostDimensions(aspectRatio); }

function parseSmartAspectRatio(val){ return window.SmartCanvasUtils.parseSmartAspectRatio(val); }

function resolveSmartDragGhostTarget(node){
    if(!node) return null;
    const nodeImgs = isSmartGroupNode(node) ? smartGroupImageRefs(node).map(ref => ref.item) : (node.images || []);
    const targetImg = (selectedImage?.nodeId === node.id && nodeImgs[selectedImage.index]) ? nodeImgs[selectedImage.index] : nodeImgs[0];
    const url = targetImg?.url || (typeof targetImg === 'string' ? targetImg : '');
    if(!url) return null;
    let aspect = targetImg.aspectRatio || targetImg.aspect || node.aspectRatio || node.aspect;
    if(!aspect){
        const nodeEl = world?.querySelector?.(`.image-node[data-id="${CSS.escape(node.id)}"]`);
        const domImg = nodeEl?.querySelector?.('img');
        if(domImg?.naturalWidth && domImg?.naturalHeight){
            aspect = domImg.naturalWidth / domImg.naturalHeight;
        } else if(domImg?.clientWidth && domImg?.clientHeight){
            aspect = domImg.clientWidth / domImg.clientHeight;
        } else if(node.w && node.h){
            aspect = node.w / node.h;
        }
    }
    return { url, aspectRatio: aspect };
}

function createSmartDragFloatingGhost(imageUrl, clientX, clientY, options = {}){
    removeSmartDragFloatingGhost();
    const url = typeof imageUrl === 'string' ? imageUrl : (imageUrl?.url || imageUrl?.src || '');
    if(!url) return null;
    const ghost = document.createElement('div');
    ghost.className = 'smart-drag-floating-ghost';
    ghost.style.position = 'fixed';
    ghost.style.zIndex = '100';
    ghost.style.pointerEvents = 'none';
    ghost.style.borderRadius = '12px';
    ghost.style.boxShadow = '0 16px 36px rgba(0,0,0,0.3)';
    ghost.style.opacity = '0.88';
    ghost.style.overflow = 'hidden';
    ghost.style.transform = 'translate(-50%, -50%)';

    let initialAspect = 1;
    if(options.aspectRatio !== undefined && options.aspectRatio !== null){
        initialAspect = parseSmartAspectRatio(options.aspectRatio);
    } else if(options.width && options.height){
        initialAspect = options.width / options.height;
    }
    const dims = (options.width && options.height && !options.aspectRatio)
        ? { width: options.width, height: options.height }
        : getSmartGhostDimensions(initialAspect);

    ghost.style.width = `${dims.width}px`;
    ghost.style.height = `${dims.height}px`;
    ghost.style.left = `${clientX}px`;
    ghost.style.top = `${clientY}px`;
    ghost.style.display = 'flex';
    ghost.style.alignItems = 'center';
    ghost.style.justifyContent = 'center';

    const img = document.createElement('img');
    img.src = url;
    img.style.width = '100%';
    img.style.height = '100%';
    img.style.objectFit = 'cover';
    img.style.borderRadius = '12px';
    img.style.display = 'block';
    img.style.pointerEvents = 'none';

    img.onload = () => {
        if(img.naturalWidth && img.naturalHeight && !options.width && !options.height){
            const naturalAspect = img.naturalWidth / img.naturalHeight;
            const updatedDims = getSmartGhostDimensions(naturalAspect);
            ghost.style.width = `${updatedDims.width}px`;
            ghost.style.height = `${updatedDims.height}px`;
        }
    };

    ghost.appendChild(img);

    document.body.appendChild(ghost);
    smartDragFloatingGhostEl = ghost;
    return ghost;
}

function updateSmartDragFloatingGhostPosition(clientX, clientY){
    if(!smartDragFloatingGhostEl) return;
    smartDragFloatingGhostEl.style.left = `${clientX}px`;
    smartDragFloatingGhostEl.style.top = `${clientY}px`;
}

function removeSmartDragFloatingGhost(){
    if(smartDragFloatingGhostEl){
        smartDragFloatingGhostEl.remove();
        smartDragFloatingGhostEl = null;
    }
    document.querySelectorAll('.smart-drag-floating-ghost').forEach(el => el.remove());
}
