function syncSmartCascadeLegacyState(preferredLoopId=''){
    const activeIds = [...smartCascadeRuns.keys()];
    smartCascadeRunning = activeIds.length > 0;
    smartCascadeActiveLoopId = preferredLoopId && smartCascadeRuns.has(preferredLoopId)
        ? preferredLoopId
        : (activeIds[0] || '');
    const activeRun = smartCascadeActiveLoopId ? smartCascadeRuns.get(smartCascadeActiveLoopId) : null;
    smartCascadeStopRequested = Boolean(activeRun?.stopRequested);
    smartCascadeRunPath = activeRun?.runPath || null;
}
function smartCascadeAnyRunning(){ return smartCascadeRunning || activeSmartCascadeCount() > 0; }
function smartCascadeEdgeState(edgeKey){
    for(const run of smartCascadeRuns.values()){
        const state = run?.runPath?.states?.[edgeKey];
        if(state) return state;
    }
    return smartCascadeRunPath?.states?.[edgeKey] || '';
}
function smartCascadePathForCtx(ctx=null){
    return ctx?.runState?.runPath || ctx?.runPath || smartCascadeRunPath;
}
function capturePendingUndo(){ pendingUndoSnapshot = snapshotForUndo(); }
function commitPendingUndo(){
    if(pendingUndoSnapshot){
        undoStack.push(pendingUndoSnapshot);
        if(undoStack.length > UNDO_LIMIT) undoStack.shift();
        pendingUndoSnapshot = null;
        redoStack.length = 0;
    }
}
function discardPendingUndo(){ pendingUndoSnapshot = null; }

function pruneMediaItemForSnapshot(item){ return window.SmartCanvasState.pruneMediaItemForSnapshot(item); }

function pruneNodeForSnapshot(node){ return window.SmartCanvasState.pruneNodeForSnapshot(node); }

function smartUndoClone(obj) {
    if (obj === null || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) {
        const arr = new Array(obj.length);
        for(let i = 0; i < obj.length; i++) arr[i] = smartUndoClone(obj[i]);
        return arr;
    }
    const cloned = {};
    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
            cloned[key] = smartUndoClone(obj[key]);
        }
    }
    return cloned;
}

function snapshotForUndo(){
    const cleanNodes = (nodes || [])
        .filter(node => node && node.id !== SMART_LOG_PREVIEW_NODE_ID)
        .map(pruneNodeForSnapshot);
    const cleanConnections = (canvas?.connections || []).map(conn => ({
        from: conn.from,
        to: conn.to,
        kind: conn.kind || 'flow',
        ...(conn.id ? {id: conn.id} : {})
    }));
    return {
        nodes: smartUndoClone(cleanNodes),
        connections: smartUndoClone(cleanConnections),
        selectedId: selectedId || '',
        selectedIds: selectedIds.slice(),
        selectedImage: {...selectedImage}
    };
}
function pushUndo(){
    if(undoSuppressed) return;
    if(!canvas) return;
    undoStack.push(snapshotForUndo());
    if(undoStack.length > UNDO_LIMIT) undoStack.shift();
    redoStack.length = 0;
}
function performUndo(){
    if(!undoStack.length){
        const msg = tr('smart.toastNoUndo');
        toast(msg === 'smart.toastNoUndo' ? '没有可撤销的操作' : msg);
        return;
    }
    const currentSnap = snapshotForUndo();
    const snap = undoStack.pop();
    redoStack.push(currentSnap);
    if(redoStack.length > REDO_LIMIT) redoStack.shift();
    undoSuppressed = true;
    nodes = snap.nodes;
    if(canvas) canvas.connections = snap.connections;
    selectedId = snap.selectedId;
    selectedIds = snap.selectedIds;
    selectedImage = snap.selectedImage;
    activeComposerSubject = null;
    lastComposerNodeId = '';
    render();
    scheduleSave();
    undoSuppressed = false;
    const msg = tr('smart.toastUndone');
    toast(msg === 'smart.toastUndone' ? '已撤销' : msg);
}
function performRedo(){
    if(!redoStack.length){
        const msg = tr('smart.toastNoRedo');
        toast(msg === 'smart.toastNoRedo' ? '没有可重做的操作' : msg);
        return;
    }
    const currentSnap = snapshotForUndo();
    const snap = redoStack.pop();
    undoStack.push(currentSnap);
    if(undoStack.length > UNDO_LIMIT) undoStack.shift();
    undoSuppressed = true;
    nodes = snap.nodes;
    if(canvas) canvas.connections = snap.connections;
    selectedId = snap.selectedId;
    selectedIds = snap.selectedIds;
    selectedImage = snap.selectedImage;
    activeComposerSubject = null;
    lastComposerNodeId = '';
    render();
    scheduleSave();
    undoSuppressed = false;
    const msg = tr('smart.toastRedone');
    toast(msg === 'smart.toastRedone' ? '已重做' : msg);
}
