function refreshIcons(root){
    if(!window.lucide) return;
    try {
        if(root){
            lucide.createIcons({root});
            return;
        }
        // 默认不扫 #world 节点，避免选中时整页重绘图标。打开的外壳菜单仍要单独补图标。
        // 这里必须用 getElementById，不能读后面才声明的 const createMenu，否则页面加载时会白屏。
        const targets = [];
        // 素材右键菜单固定挂在 shell 上，打开时需要补图标。
        const ctxMenuEl = document.getElementById('smartNodeContextMenu');
        if(ctxMenuEl?.classList.contains('open')) targets.push(ctxMenuEl);
        const composerEl = document.getElementById('composer');
        if(composerEl) targets.push(composerEl);
        const linkMenu = document.getElementById('linkCreateMenu');
        if(linkMenu?.classList.contains('open')) targets.push(linkMenu);
        const createMenuEl = document.getElementById('createMenu');
        if(createMenuEl?.classList.contains('open')) targets.push(createMenuEl);

        // 补全扫描已打开的侧边抽屉（个人资产、生成日志与工作流）
        const assetPanel = document.getElementById('assetPanel');
        if(assetPanel?.classList.contains('open')) targets.push(assetPanel);
        const logModal = document.getElementById('smartLogModal');
        if(logModal?.classList.contains('open')) targets.push(logModal);
        const wfModal = document.getElementById('smartWorkflowTransferModal');
        if(wfModal?.classList.contains('open')) targets.push(wfModal);

        if(!targets.length){
            lucide.createIcons({root: document.body});
            return;
        }
        targets.forEach(el => lucide.createIcons({root: el}));
    } catch(_) {}
}
function uid(prefix){ return `${prefix}_${Math.random().toString(36).slice(2, 10)}${Date.now().toString(36).slice(-4)}`; }
function escapeHtml(str){ return window.SmartCanvasUtils.escapeHtml(str); }
const escapeAttr = escapeHtml;
