function smartBindCustomVideoControls(wrap, video){
    if(!wrap || !video || wrap.dataset.customControlsBound === '1') return;
    wrap.dataset.customControlsBound = '1';

    const card = wrap.closest('.media-video-card') || wrap;
    const playBtn = wrap.querySelector('.smart-video-bar-play');
    const pauseIcon = playBtn?.querySelector('.icon-pause');
    const playIcon = playBtn?.querySelector('.icon-play');
    const centerPlay = wrap.querySelector('.smart-video-center-play') || card.querySelector('.smart-video-center-play');
    const pill = wrap.querySelector('.smart-video-duration-pill') || card.querySelector('.smart-video-duration-pill');
    const curTimeEl = wrap.querySelector('.smart-video-bar-cur');
    const totalTimeEl = wrap.querySelector('.smart-video-bar-total');
    const fillEl = wrap.querySelector('.smart-video-bar-fill');
    const thumbEl = wrap.querySelector('.smart-video-bar-thumb');
    const muteBtn = wrap.querySelector('.smart-video-bar-mute');
    const mutedIcon = muteBtn?.querySelector('.icon-muted');
    const unmutedIcon = muteBtn?.querySelector('.icon-unmuted');

    const updatePlayState = (playing) => {
        if(playing){
            wrap.classList.add('is-playing');
            wrap.classList.remove('is-paused');
            card.classList.add('is-playing');
            card.classList.remove('is-paused');
            if(pauseIcon) pauseIcon.style.display = 'block';
            if(playIcon) playIcon.style.display = 'none';
            if(centerPlay) centerPlay.style.display = 'none';
            if(pill) pill.style.display = 'none';
        } else {
            wrap.classList.remove('is-playing');
            wrap.classList.add('is-paused');
            card.classList.remove('is-playing');
            card.classList.add('is-paused');
            if(pauseIcon) pauseIcon.style.display = 'none';
            if(playIcon) playIcon.style.display = 'block';
            if(centerPlay) centerPlay.style.display = 'inline-flex';
            if(pill) pill.style.display = 'block';
        }
    };

    const updateMuteState = () => {
        if(video.muted){
            if(mutedIcon) mutedIcon.style.display = 'block';
            if(unmutedIcon) unmutedIcon.style.display = 'none';
        } else {
            if(mutedIcon) mutedIcon.style.display = 'none';
            if(unmutedIcon) unmutedIcon.style.display = 'block';
        }
    };

    video.addEventListener('play', () => updatePlayState(true));
    video.addEventListener('pause', () => updatePlayState(false));
    video.addEventListener('ended', () => updatePlayState(false));
    video.addEventListener('volumechange', updateMuteState);

    const applyMetadata = () => {
        const d = video.duration;
        if(Number.isFinite(d) && d > 0){
            const s = `${d.toFixed(1)}s`;
            if(totalTimeEl) totalTimeEl.innerText = s;
            if(pill) pill.innerText = s;
        }
        updateMuteState();
    };
    if(video.readyState >= 1) applyMetadata();
    else video.addEventListener('loadedmetadata', applyMetadata);

    video.addEventListener('timeupdate', () => {
        if(wrap._isSeeking) return;
        const c = video.currentTime || 0;
        const d = video.duration || 0;
        if(curTimeEl) curTimeEl.innerText = `${c.toFixed(1)}s`;
        if(d > 0){
            const pct = Math.max(0, Math.min(100, (c / d) * 100));
            if(fillEl) fillEl.style.width = `${pct}%`;
            if(thumbEl) thumbEl.style.left = `${pct}%`;
        }
    });

    video.addEventListener('click', (e) => {
        e.stopPropagation();
        card.dataset.userPinned = '1';
        delete card.dataset.hoverPreviewing;
        card.classList.remove('is-hover-previewing');
        if(video.paused) video.play()?.catch?.(() => {});
        else video.pause();
    });

    updatePlayState(!video.paused);
    updateMuteState();
}
function smartToggleCustomVideoPlay(btnOrEl){
    const wrap = btnOrEl?.closest('.smart-custom-video-wrap') || btnOrEl?.closest('.media-video-card');
    const card = wrap?.closest('.media-video-card') || wrap;
    if(card){
        card.dataset.userPinned = '1';
        delete card.dataset.hoverPreviewing;
        card.classList.remove('is-hover-previewing');
    }
    const video = wrap?.querySelector('video');
    if(!video) return;
    if(video.paused) video.play()?.catch?.(() => {});
    else video.pause();
}
function smartToggleCustomVideoMute(btnOrEl){
    const wrap = btnOrEl?.closest('.smart-custom-video-wrap') || btnOrEl?.closest('.media-video-card');
    const card = wrap?.closest('.media-video-card') || wrap;
    if(card){
        card.dataset.userPinned = '1';
        delete card.dataset.hoverPreviewing;
        card.classList.remove('is-hover-previewing');
    }
    const video = wrap?.querySelector('video');
    if(!video) return;
    video.muted = !video.muted;
}
function smartSeekCustomVideo(progEl, e){
    const track = progEl?.querySelector('.smart-video-bar-track') || progEl;
    const wrap = progEl?.closest('.smart-custom-video-wrap') || progEl?.closest('.media-video-card');
    const card = wrap?.closest('.media-video-card') || wrap;
    if(card){
        card.dataset.userPinned = '1';
        delete card.dataset.hoverPreviewing;
        card.classList.remove('is-hover-previewing');
    }
    const video = wrap?.querySelector('video');
    if(!video || !track) return;
    const rect = track.getBoundingClientRect();
    const pct = Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width));
    const d = video.duration;
    if(Number.isFinite(d) && d > 0){
        video.currentTime = pct * d;
        const fill = wrap.querySelector('.smart-video-bar-fill');
        const thumb = wrap.querySelector('.smart-video-bar-thumb');
        const curTimeEl = wrap.querySelector('.smart-video-bar-cur');
        if(fill) fill.style.width = `${pct * 100}%`;
        if(thumb) thumb.style.left = `${pct * 100}%`;
        if(curTimeEl) curTimeEl.innerText = `${(pct * d).toFixed(1)}s`;
    }
}
function smartStartCustomVideoSeek(progEl, e){
    const track = progEl?.querySelector('.smart-video-bar-track') || progEl;
    const wrap = progEl?.closest('.smart-custom-video-wrap') || progEl?.closest('.media-video-card');
    const card = wrap?.closest('.media-video-card') || wrap;
    if(card){
        card.dataset.userPinned = '1';
        delete card.dataset.hoverPreviewing;
        card.classList.remove('is-hover-previewing');
    }
    const video = wrap?.querySelector('video');
    if(!video || !track) return;
    wrap._isSeeking = true;

    const onPointerMove = (ev) => {
        const rect = track.getBoundingClientRect();
        const pct = Math.max(0, Math.min(1, (ev.clientX - rect.left) / rect.width));
        const d = video.duration;
        const fill = wrap.querySelector('.smart-video-bar-fill');
        const thumb = wrap.querySelector('.smart-video-bar-thumb');
        const curTimeEl = wrap.querySelector('.smart-video-bar-cur');
        if(fill) fill.style.width = `${pct * 100}%`;
        if(thumb) thumb.style.left = `${pct * 100}%`;
        if(curTimeEl && Number.isFinite(d) && d > 0) curTimeEl.innerText = `${(pct * d).toFixed(1)}s`;
        if(Number.isFinite(d) && d > 0) video.currentTime = pct * d;
    };

    const onPointerUp = () => {
        wrap._isSeeking = false;
        window.removeEventListener('pointermove', onPointerMove);
        window.removeEventListener('pointerup', onPointerUp);
        window.removeEventListener('pointercancel', onPointerUp);
    };

    window.addEventListener('pointermove', onPointerMove);
    window.addEventListener('pointerup', onPointerUp);
    window.addEventListener('pointercancel', onPointerUp);
    onPointerMove(e);
}
function bindSmartCustomVideoControls(root=document){
    root.querySelectorAll?.('.smart-custom-video-wrap:not([data-custom-controls-bound="1"])').forEach(wrap => {
        const video = wrap.querySelector('video');
        if(video) smartBindCustomVideoControls(wrap, video);
    });
}
function smartActivateVideoPreview(target){
    const root = target?.closest?.('.media-video-card,.video-thumb,.image-wrap,.thumb-item') || target?.parentElement || null;
    const card = target?.closest?.('.media-video-card') || root;
    if(card){
        card.dataset.userPinned = '1';
        delete card.dataset.hoverPreviewing;
        card.classList.remove('is-hover-previewing');
    }
    const itemEl = target?.closest?.('[data-image-index]') || root?.closest?.('[data-image-index]') || root;
    const nodeEl = target?.closest?.('.image-node') || root?.closest?.('.image-node');
    const node = Array.isArray(nodes) ? nodes.find(n => n.id === nodeEl?.dataset.id) : null;
    const imageIndex = Number(itemEl?.dataset?.imageIndex ?? 0);
    const image = node?.images?.[imageIndex];
    if(image) image._inlineVideoActive = true;

    const img = target?.matches?.('img[data-preview-kind="video"]') ? target : root?.querySelector?.('img[data-preview-kind="video"]');
    if(!img){
        const video = target?.matches?.('video[data-url]') ? target : root?.querySelector?.('video[data-url]');
        if(video){
            if(video.paused) video.play()?.catch?.(() => {});
            else video.pause();
            return true;
        }
        return false;
    }
    const original = smartOriginalMediaUrl(img.dataset.originalSrc || img.dataset.url || img.getAttribute('src') || '');
    if(!original) return false;
    
    const durTag = formatSmartVideoDurationTag(image || node?.duration);
    const tpl = document.createElement('template');
    tpl.innerHTML = smartVideoPlayerHtml(original, '', durTag);
    const wrap = tpl.content.firstElementChild;
    if(!wrap) return false;

    img.replaceWith(wrap);
    root?.querySelectorAll?.('.smart-video-duration-pill:not(.smart-custom-video-wrap .smart-video-duration-pill)')?.forEach(p => p.remove());
    root?.querySelectorAll?.('.smart-video-play:not(.smart-custom-video-wrap .smart-video-play)')?.forEach(p => p.remove());

    const video = wrap.querySelector('video') || wrap;
    smartBindCustomVideoControls(wrap, video);
    video.play?.().catch(() => {});
    return true;
}

/* 鼠标悬停静音自动播放预览引擎 (带250ms防误触延迟、单实例播放保护、移开平滑复位) */
let smartVideoHoverTimer = null;
let smartHoverPendingCard = null;
let smartActiveHoverCard = null;

function isCanvasBusyForHoverPreview(){
    try {
        if(typeof panState !== 'undefined' && panState) return true;
        if(typeof dragState !== 'undefined' && dragState) return true;
        if(typeof resizeState !== 'undefined' && resizeState) return true;
        if(typeof thumbDragState !== 'undefined' && thumbDragState) return true;
        if(typeof portDragState !== 'undefined' && portDragState) return true;
        if(typeof activeVideoCrop !== 'undefined' && activeVideoCrop) return true;
        const selBox = document.getElementById('selectionBox');
        if(selBox && selBox.style.display && selBox.style.display !== 'none') return true;
    } catch(_) {}
    return false;
}

function smartEnsureVideoElementForCard(card){
    if(!card) return null;
    let video = card.querySelector('video');
    if(video) return video;

    const img = card.querySelector('img[data-preview-kind="video"], img.node-video-preview, img');
    if(!img) return null;
    const original = smartOriginalMediaUrl(img.dataset.originalSrc || img.dataset.url || img.getAttribute('src') || '');
    if(!original) return null;

    const itemEl = card.closest('[data-image-index]') || card;
    const nodeEl = card.closest('.image-node');
    const node = Array.isArray(nodes) ? nodes.find(n => n.id === nodeEl?.dataset.id) : null;
    const imageIndex = Number(itemEl?.dataset?.imageIndex ?? 0);
    const image = node?.images?.[imageIndex];
    const durTag = formatSmartVideoDurationTag(image || node?.duration);

    const tpl = document.createElement('template');
    tpl.innerHTML = smartVideoPlayerHtml(original, '', durTag);
    const wrap = tpl.content.firstElementChild;
    if(!wrap) return null;

    img.replaceWith(wrap);
    card.querySelectorAll('.smart-video-duration-pill:not(.smart-custom-video-wrap .smart-video-duration-pill)').forEach(p => p.remove());
    card.querySelectorAll('.smart-video-play:not(.smart-custom-video-wrap .smart-video-play)').forEach(p => p.remove());

    video = wrap.querySelector('video');
    smartBindCustomVideoControls(wrap, video);
    return video;
}

function smartStopVideoHoverPreview(card){
    if(!card) return;
    if(smartActiveHoverCard === card){
        smartActiveHoverCard = null;
    }
    if(card.dataset.userPinned === '1') return;
    if(card.dataset.hoverPreviewing !== '1') return;

    delete card.dataset.hoverPreviewing;
    card.classList.remove('is-hover-previewing');

    const video = card.querySelector('video');
    if(video){
        try {
            video.pause();
            video.currentTime = 0;
        } catch(_) {}
    }

    card.classList.remove('is-playing');
    card.classList.add('is-paused');
    const wrap = card.querySelector('.smart-custom-video-wrap');
    if(wrap){
        wrap.classList.remove('is-playing');
        wrap.classList.add('is-paused');
    }
    const centerPlay = card.querySelector('.smart-video-center-play');
    if(centerPlay) centerPlay.style.display = 'inline-flex';
    const pill = card.querySelector('.smart-video-duration-pill');
    if(pill) pill.style.display = 'block';
}

function smartStartVideoHoverPreview(card){
    if(!card || isCanvasBusyForHoverPreview()) return;
    if(card.dataset.userPinned === '1') return;

    // 单例控制：如果当前有其他卡片在预览，立刻复位暂停
    if(smartActiveHoverCard && smartActiveHoverCard !== card){
        smartStopVideoHoverPreview(smartActiveHoverCard);
    }

    // 保护硬件解码器：暂停其他未锁定播放的卡片
    document.querySelectorAll('.media-video-card video, .video-thumb video').forEach(v => {
        if(v.closest('.media-video-card') !== card && !v.paused && v.closest('.media-video-card')?.dataset.userPinned !== '1'){
            v.pause();
        }
    });

    const video = smartEnsureVideoElementForCard(card);
    if(!video) return;

    card.dataset.hoverPreviewing = '1';
    card.classList.add('is-hover-previewing');
    smartActiveHoverCard = card;

    // 强制静音 + 循环微动预览
    video.muted = true;
    video.loop = true;
    const p = video.play();
    if(p && typeof p.catch === 'function') p.catch(() => {});
}

function initSmartVideoHoverPreview(){
    if(window.__smartVideoHoverPreviewInitialized) return;
    window.__smartVideoHoverPreviewInitialized = true;

    document.addEventListener('mouseover', (e) => {
        const targetCard = e.target.closest?.('.media-video-card');
        const relatedCard = e.relatedTarget?.closest?.('.media-video-card');

        // 同一卡片内部子元素移动，直接忽略
        if(targetCard && targetCard === relatedCard) return;

        // 离开之前的卡片
        if(relatedCard && relatedCard !== targetCard){
            if(smartVideoHoverTimer && smartHoverPendingCard === relatedCard){
                clearTimeout(smartVideoHoverTimer);
                smartVideoHoverTimer = null;
                smartHoverPendingCard = null;
            }
            smartStopVideoHoverPreview(relatedCard);
        }

        // 移入新的视频卡片
        if(targetCard && targetCard !== relatedCard){
            if(isCanvasBusyForHoverPreview()) return;
            if(targetCard.dataset.userPinned === '1') return;

            if(smartVideoHoverTimer){
                clearTimeout(smartVideoHoverTimer);
                smartVideoHoverTimer = null;
            }

            smartHoverPendingCard = targetCard;
            // 250ms 防误触延迟：快速掠过不触发，短暂停留才判定为想看
            smartVideoHoverTimer = setTimeout(() => {
                smartVideoHoverTimer = null;
                if(smartHoverPendingCard === targetCard && !isCanvasBusyForHoverPreview()){
                    smartStartVideoHoverPreview(targetCard);
                }
            }, 250);
        }
    });

    document.addEventListener('mouseout', (e) => {
        const targetCard = e.target.closest?.('.media-video-card');
        const relatedCard = e.relatedTarget?.closest?.('.media-video-card');

        if(targetCard && targetCard !== relatedCard){
            if(smartVideoHoverTimer && smartHoverPendingCard === targetCard){
                clearTimeout(smartVideoHoverTimer);
                smartVideoHoverTimer = null;
                smartHoverPendingCard = null;
            }
            smartStopVideoHoverPreview(targetCard);
        }
    });

    // 任何画布交互（平移视角、拖动节点、框选等）立即取消待定预览并停止当前播放
    window.addEventListener('pointerdown', (e) => {
        if(smartActiveHoverCard && smartActiveHoverCard.contains(e.target)){
            smartActiveHoverCard.dataset.userPinned = '1';
            delete smartActiveHoverCard.dataset.hoverPreviewing;
            smartActiveHoverCard.classList.remove('is-hover-previewing');
            return;
        }
        if(smartVideoHoverTimer){
            clearTimeout(smartVideoHoverTimer);
            smartVideoHoverTimer = null;
            smartHoverPendingCard = null;
        }
        if(smartActiveHoverCard){
            smartStopVideoHoverPreview(smartActiveHoverCard);
        }
    }, { capture: true, passive: true });

    // 滚轮缩放画布时取消待定预览
    window.addEventListener('wheel', () => {
        if(smartVideoHoverTimer){
            clearTimeout(smartVideoHoverTimer);
            smartVideoHoverTimer = null;
            smartHoverPendingCard = null;
        }
    }, { passive: true });

    // 窗口失去焦点时停止
    window.addEventListener('blur', () => {
        if(smartVideoHoverTimer){
            clearTimeout(smartVideoHoverTimer);
            smartVideoHoverTimer = null;
            smartHoverPendingCard = null;
        }
        if(smartActiveHoverCard){
            smartStopVideoHoverPreview(smartActiveHoverCard);
        }
    });
}
try { initSmartVideoHoverPreview(); } catch(e) {}
