const SMART_SELECTED_HIGH_RES_DELAY = 320;
const SMART_HIGH_RES_ZOOM_THRESHOLD = 0.86;
let smartSelectedHighResTimer = 0;
let smartSelectedHighResSeq = 0;
let smartSelectedHighResNodeIds = new Set();
let smartImageResolutionSyncTimer = 0;
const smartSelectedHighResLoaded = new Set();
const smartSelectedHighResLoading = new Map();
function smartImageEditorIsOpen(){
    return Boolean(imageEditModal?.classList?.contains('open'));
}
function preloadSmartSelectedHighRes(src){
    if(!src || smartSelectedHighResLoaded.has(src)) return Promise.resolve(true);
    if(smartSelectedHighResLoading.has(src)) return smartSelectedHighResLoading.get(src);
    const task = new Promise(resolve => {
        const img = new Image();
        img.decoding = 'async';
        img.onload = async () => {
            try { if(img.decode) await img.decode(); } catch(e) {}
            smartSelectedHighResLoaded.add(src);
            resolve(true);
        };
        img.onerror = () => resolve(false);
        img.src = src;
    }).finally(() => smartSelectedHighResLoading.delete(src));
    smartSelectedHighResLoading.set(src, task);
    return task;
}
function sameMediaSrc(a, b){ return window.SmartCanvasUtils.sameMediaSrc(a, b); }
function applyDecodedImageSrc(img, nextSrc){
    if(!img || !nextSrc) return;
    const current = img.getAttribute('src') || img.src || '';
    if(sameMediaSrc(current, nextSrc)) return;
    const parent = img.parentElement;
    if(!parent){
        img.src = nextSrc;
        return;
    }
    let cover = parent.querySelector(':scope > img[data-hires-cover="1"]');
    if(!cover){
        cover = img.cloneNode(false);
        cover.removeAttribute('id');
        cover.alt = '';
        cover.draggable = false;
        cover.dataset.hiresCover = '1';
        cover.setAttribute('aria-hidden', 'true');
        cover.style.position = 'absolute';
        cover.style.left = '0';
        cover.style.top = '0';
        cover.style.width = '100%';
        cover.style.height = '100%';
        cover.style.objectFit = getComputedStyle(img).objectFit || 'cover';
        cover.style.pointerEvents = 'none';
        cover.style.zIndex = '1';
        cover.style.opacity = '0';
        parent.appendChild(cover);
    }
    const reveal = () => {
        if(!img.isConnected || !cover.isConnected) return;
        cover.style.opacity = '1';
        if((img.getAttribute('src') || '') !== nextSrc) img.src = nextSrc;
        requestAnimationFrame(() => {
            if(cover.isConnected) cover.remove();
        });
    };
    if(cover.getAttribute('src') === nextSrc && cover.complete && cover.naturalWidth){
        reveal();
        return;
    }
    cover.onload = () => {
        const go = () => reveal();
        if(cover.decode) cover.decode().then(go).catch(go);
        else go();
    };
    cover.onerror = () => cover.remove();
    cover.src = nextSrc;
}
function smartNodeElementsByIds(ids){
    const wanted = ids instanceof Set ? ids : new Set(ids || []);
    const elements = [];
    if(!wanted.size) return elements;
    for(const id of wanted){
        const cached = smartNodeDomMap.get(id);
        if(cached && cached.isConnected){
            elements.push(cached);
        } else {
            const el = world.querySelector?.(`.image-node[data-id="${CSS.escape(id)}"]`);
            if(el){
                smartNodeDomMap.set(id, el);
                elements.push(el);
            }
        }
    }
    return elements;
}
function smartNodeElementsForHighResSync(root){
    if(root && root !== world) return [root];
    return [world];
}
function smartViewportWantsHighRes(){
    return Number(viewport?.scale || 1) >= 1.15;
}
function smartViewportInteractionActive(){
    return Boolean(world?.classList.contains('canvas-interacting') || shell?.classList.contains('panning') || document.body.classList.contains('smart-node-drag'));
}
function smartImageNearViewport(img){
    if(!img?.isConnected || !shell) return false;
    const shellRect = shell.getBoundingClientRect();
    const rect = img.getBoundingClientRect();
    const margin = 220;
    return rect.right >= shellRect.left - margin && rect.left <= shellRect.right + margin
        && rect.bottom >= shellRect.top - margin && rect.top <= shellRect.bottom + margin;
}
function wakeVisibleCanvasMedia(limit=24){
    if(!world || !shell) return;
    let activated = 0;
    for(const img of world.querySelectorAll('img[loading="lazy"]')){
        if(activated >= limit) break;
        if(!smartImageNearViewport(img)) continue;
        img.loading = 'eager';
        activated += 1;
    }
}
function scheduleVisibleCanvasMediaWake(delay=160){
    if(smartCanvasMediaWakeTimer) clearTimeout(smartCanvasMediaWakeTimer);
    smartCanvasMediaWakeTimer = setTimeout(() => {
        smartCanvasMediaWakeTimer = 0;
        wakeVisibleCanvasMedia();
    }, Math.max(0, Number(delay) || 0));
}
function scheduleSmartCanvasVirtualRender(delay=100){
    if(smartCanvasVirtualRenderTimer) clearTimeout(smartCanvasVirtualRenderTimer);
    smartCanvasVirtualRenderTimer = setTimeout(() => {
        smartCanvasVirtualRenderTimer = 0;
        if(!world || document.hidden) return;
        try { render(); } catch(err) { console.warn('[canvas virtualization] refresh skipped:', err); }
    }, Math.max(0, Number(delay) || 0));
}
function isSmartLanModeActive(){
    try {
        const currentParams = new URLSearchParams(window.location.search);
        return currentParams.get('mode') === 'lan' || (typeof canvasId === 'string' && (canvasId === 'lan_main' || canvasId.startsWith('lan_')));
    } catch(e) {
        return false;
    }
}
function syncSmartSelectedImageResolution(root=null){
    // 交互期间不要切换图片源；等待视口稳定后再做高清图预加载/切换，避免拖动或缩放中的一帧空白。
    if(smartViewportInteractionActive()){
        scheduleSmartImageResolutionSync(root, 220);
        return;
    }
    // 批量导入默认会选中整组节点；不要在放大时同时切换几十张高清图，
    // 否则会争抢解码资源并造成素材、工具栏和小地图闪烁。
    if(selectedNodeIds().length > 1) return;
    const selectedImages = [];
    const wantHighRes = smartViewportWantsHighRes();
    const isLanMode = isSmartLanModeActive();
    smartNodeElementsForHighResSync(root).forEach(scope => {
        scope.querySelectorAll?.('img[data-preview-src][data-original-src]').forEach(img => {
            if(img.dataset.previewKind === 'video') return;
            const curSrc = img.getAttribute('src') || img.src || '';
            const originalSrc = img.dataset.originalSrc || '';
            // 局域网模式或带有局域网素材特征的图片，跳过普通画布的高低清降级重置逻辑，保持已加载的高清素材稳定渲染，严禁在平移时重置 img.src = preview
            const isLanAsset = isLanMode || img.hasAttribute('data-sha256') || img.hasAttribute('data-asset-hash') || curSrc.includes('/api/lan/assets/') || originalSrc.includes('/api/lan/assets/');
            if(isLanAsset) return;

            const original = img.dataset.originalSrc || '';
            if(!wantHighRes || !smartImageNearViewport(img)){
                delete img.dataset.selectedHighResTarget;
                // 不在缩放/平移/拖动后把已显示的高清图强制切回缩略图。
                // 直接改 src 会让图片短暂清空并重新解码，表现为画布闪一下；缩略图只作为首次加载和失败兜底使用。
                return;
            }
            const target = displayMediaUrl({url:smartOriginalMediaUrl(original)});
            if(!target) return;
            if(sameMediaSrc(curSrc, target)) return;
            const ownerEl = img.closest('.image-node');
            if(ownerEl?.dataset.id && !isNodeSelected(ownerEl.dataset.id)) return;
            img.dataset.selectedHighResTarget = target;
            if(smartSelectedHighResLoaded.has(target)){
                applyDecodedImageSrc(img, target);
                return;
            }
            // 已经显示的图片保持当前源；高清图在后台预加载完成后再无缝替换，
            // 不要为了等待高清图而强制切回缩略图，否则点击空白处也会闪烁。
            selectedImages.push({img, target});
        });
    });
    if(smartSelectedHighResTimer) clearTimeout(smartSelectedHighResTimer);
    const seq = ++smartSelectedHighResSeq;
    smartSelectedHighResNodeIds = new Set(selectedNodeIds());
    if(!selectedImages.length || smartImageEditorIsOpen()) return;
    smartSelectedHighResTimer = setTimeout(async () => {
        smartSelectedHighResTimer = 0;
        if(seq !== smartSelectedHighResSeq || smartImageEditorIsOpen()) return;
        if(smartViewportInteractionActive()){
            scheduleSmartImageResolutionSync(world, 220);
            return;
        }
        await Promise.all(selectedImages.map(item => preloadSmartSelectedHighRes(item.target)));
        if(seq !== smartSelectedHighResSeq || smartImageEditorIsOpen()) return;
        selectedImages.forEach(({img, target}) => {
            if(!img.isConnected || img.dataset.selectedHighResTarget !== target) return;
            if(!smartViewportWantsHighRes() || !smartImageNearViewport(img)) return;
            if(smartSelectedHighResLoaded.has(target)) applyDecodedImageSrc(img, target);
        });
    }, SMART_SELECTED_HIGH_RES_DELAY);
}
function scheduleSmartImageResolutionSync(root=world, delay=120){
    if(smartImageResolutionSyncTimer) clearTimeout(smartImageResolutionSyncTimer);
    smartImageResolutionSyncTimer = setTimeout(() => {
        smartImageResolutionSyncTimer = 0;
        syncSmartSelectedImageResolution(root);
    }, Math.max(0, Number(delay) || 0));
}
