function apiErrorMessage(data, fallback='请求失败'){
    if(!data) return fallback;
    if(typeof data === 'string') return data || fallback;
    const detail = data.detail ?? data.error ?? data.message;
    if(typeof detail === 'string') return detail || fallback;
    if(Array.isArray(detail)){
        const messages = detail.map(item => {
            if(typeof item === 'string') return item;
            const loc = Array.isArray(item?.loc) ? item.loc.filter(x => x !== 'body').join('.') : '';
            const msg = item?.msg || item?.message || JSON.stringify(item);
            return loc ? `${loc}: ${msg}` : msg;
        }).filter(Boolean);
        return messages.join('\n') || fallback;
    }
    if(detail && typeof detail === 'object') return detail.message || detail.msg || JSON.stringify(detail);
    try {
        return JSON.stringify(data);
    } catch(e) {
        return fallback;
    }
}
async function responseErrorMessage(response, fallback='请求失败'){
    try {
        const data = await response.clone().json();
        return apiErrorMessage(data, fallback);
    } catch(e) {
        try {
            const text = await response.text();
            return text || fallback;
        } catch(_) {
            return fallback;
        }
    }
}
function downloadBlob(blob, filename){ return window.SmartCanvasUtils.downloadBlob(blob, filename); }
function smartWorkflowFilename(ext='json'){
    const title = (canvas?.title || document.getElementById('smartTitle')?.textContent || 'smart-canvas').trim();
    return window.SmartCanvasWorkflow.workflowFilename(title, ext);
}
function clearSmartNodeTransientRunState(node, options){ return window.SmartCanvasState.clearSmartNodeTransientRunState(node, options); }
function serializableSmartNode(node){ return window.SmartCanvasState.serializableSmartNode(node, smartNodeMigrationDeps()); }
function selectedSmartWorkflowPayload(){
    const ids = selectedNodeIds();
    const idSet = new Set(ids);
    let selectedNodes = nodes.filter(node => idSet.has(node.id)).map(serializableSmartNode);
    if(!selectedNodes.length){
        selectedNodes = (nodes || []).filter(Boolean).map(serializableSmartNode);
    }
    const resolved = resolveSmartWorkflowConnections(selectedNodes, canvas?.connections || []);
    const selectedSet = new Set(resolved.nodes.map(node => node.id));
    const selectedConnections = (resolved.connections || [])
        .filter(conn => selectedSet.has(conn.from) && selectedSet.has(conn.to))
        .map(conn => JSON.parse(JSON.stringify(conn)));
    return {
        format:'mini-office-canvas-workflow',
        version:1,
        canvas_type:'smart',
        exported_at:Date.now(),
        nodes:resolved.nodes,
        connections:selectedConnections
    };
}
window.selectedSmartWorkflowPayload = selectedSmartWorkflowPayload;
function normalizeImportedSmartWorkflow(data){ return window.SmartCanvasState.normalizeImportedSmartWorkflow(data); }
