function bindUiverseSelect(selectEl) {
    if (!selectEl || selectEl.dataset.uiverseBound === 'true' || selectEl.style.display === 'none' || selectEl.hidden) return null;
    selectEl.dataset.uiverseBound = 'true';
    selectEl.classList.add('uiverse-hidden-native-select');

    const wrapper = document.createElement('div');
    wrapper.className = 'uiverse-select-wrapper' + (selectEl.classList.contains('prompt-node-control') ? ' prompt-node-control' : '');
    if (selectEl.id) wrapper.dataset.targetId = selectEl.id;
    wrapper.addEventListener('mousedown', (e) => e.stopPropagation());
    wrapper.addEventListener('pointerdown', (e) => e.stopPropagation());

    const selectedBtn = document.createElement('div');
    selectedBtn.className = 'uiverse-selected';
    selectedBtn.innerHTML = `
      <span class="uiverse-selected-text"></span>
      <svg class="uiverse-arrow" viewBox="0 0 24 24">
        <path d="M7 10l5 5 5-5z"/>
      </svg>
    `;

    const optionsContainer = document.createElement('div');
    optionsContainer.className = 'uiverse-options';

    wrapper.appendChild(selectedBtn);
    wrapper.appendChild(optionsContainer);
    selectEl.parentNode.insertBefore(wrapper, selectEl.nextSibling);

    const syncOptions = () => {
      optionsContainer.innerHTML = '';
      const options = Array.from(selectEl.options);
      const selectedOpt = selectEl.options[selectEl.selectedIndex] || options[0];
      const textEl = selectedBtn.querySelector('.uiverse-selected-text');
      if (textEl) textEl.textContent = selectedOpt ? selectedOpt.textContent : '';

      options.forEach(opt => {
        const optDiv = document.createElement('div');
        optDiv.className = 'uiverse-option' + (opt.selected ? ' selected' : '');
        optDiv.textContent = opt.textContent;
        optDiv.dataset.value = opt.value;
        optDiv.addEventListener('click', (e) => {
          e.stopPropagation();
          selectEl.value = opt.value;
          if (textEl) textEl.textContent = opt.textContent;
          optionsContainer.querySelectorAll('.uiverse-option').forEach(el => el.classList.remove('selected'));
          optDiv.classList.add('selected');
          wrapper.classList.remove('open');
          selectEl.dispatchEvent(new Event('change', { bubbles: true }));
        });
        optionsContainer.appendChild(optDiv);
      });
    };

    syncOptions();

    selectedBtn.addEventListener('click', (e) => {
      e.stopPropagation();
      document.querySelectorAll('.uiverse-select-wrapper.open').forEach(w => {
        if (w !== wrapper) w.classList.remove('open');
      });
      wrapper.classList.toggle('open');
    });

    selectEl.addEventListener('change', () => {
      const selectedOpt = selectEl.options[selectEl.selectedIndex];
      const textEl = selectedBtn.querySelector('.uiverse-selected-text');
      if (selectedOpt && textEl) {
        textEl.textContent = selectedOpt.textContent;
        optionsContainer.querySelectorAll('.uiverse-option').forEach(el => {
          el.classList.toggle('selected', el.dataset.value === selectEl.value);
        });
      }
    });

    try {
      const originalValueSetter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').set;
      const originalValueGetter = Object.getOwnPropertyDescriptor(HTMLSelectElement.prototype, 'value').get;
      Object.defineProperty(selectEl, 'value', {
        get() {
          return originalValueGetter.call(this);
        },
        set(val) {
          originalValueSetter.call(this, val);
          const selectedOpt = selectEl.options[selectEl.selectedIndex];
          const textEl = selectedBtn.querySelector('.uiverse-selected-text');
          if (selectedOpt && textEl) {
            textEl.textContent = selectedOpt.textContent;
            optionsContainer.querySelectorAll('.uiverse-option').forEach(el => {
              el.classList.toggle('selected', el.dataset.value === selectEl.value);
            });
          }
        },
        configurable: true
      });
    } catch (e) {}

    const observer = new MutationObserver(() => {
      syncOptions();
    });
    observer.observe(selectEl, { childList: true, subtree: true, characterData: true });

    if (!window._uiverseDocClickBound) {
      window._uiverseDocClickBound = true;
      document.addEventListener('click', (e) => {
        if (!e.target.closest('.uiverse-select-wrapper')) {
          document.querySelectorAll('.uiverse-select-wrapper.open').forEach(w => w.classList.remove('open'));
        }
      });
    }

    return wrapper;
}
window.bindUiverseSelect = bindUiverseSelect;

// 画布加载期工作空间级默认绑定加载函数：读取 personal:default 或当前 LAN scope，将 default_bindings 同步至 smartApiDefaults.bindings
async function loadSmartApiDefaultBindings(){
    const sharedMode = isLanMode;
    const mode = sharedMode ? 'lan' : 'personal';
    const id = isLanMode ? (canvasId || 'lan_main') : 'default';
    try {
        const response = await fetch(`/api/canvas-api-settings?mode=${encodeURIComponent(mode)}&canvas_id=${encodeURIComponent(id)}`);
        if(!response.ok) return;
        const data = await response.json();
        const bindings = (typeof smartApiResolveBindings === 'function')
            ? smartApiResolveBindings(data)
            : (data?.default_bindings || {});
        let imgBinding = bindings?.image && bindings.image.provider_id && bindings.image.model
            ? { ...bindings.image }
            : null;
        let vidBinding = bindings?.video && bindings.video.provider_id && bindings.video.model
            ? { ...bindings.video }
            : null;
        let chatBinding = bindings?.chat && bindings.chat.provider_id && bindings.chat.model
            ? { ...bindings.chat }
            : null;

        const defProvider = data?.default_provider || '';
        if(!imgBinding && data?.default_models?.image){
            imgBinding = {
                provider_id: defProvider,
                model: data.default_models.image
            };
        }
        if(!vidBinding && data?.default_models?.video){
            vidBinding = {
                provider_id: defProvider,
                model: data.default_models.video
            };
        }
        if(!chatBinding && data?.default_models?.chat){
            chatBinding = {
                provider_id: defProvider,
                model: data.default_models.chat
            };
        }

        smartApiDefaults.bindings = {
            image: imgBinding,
            video: vidBinding,
            chat: chatBinding
        };
        if(defProvider) smartApiDefaults.provider_id = defProvider;
        if(data?.default_models && typeof data.default_models === 'object'){
            smartApiDefaults.models = { ...data.default_models };
        }
    } catch(e) { /* 静默失败 */ }
}
window.loadSmartApiDefaultBindings = loadSmartApiDefaultBindings;
