async function updateLanRoomInfo(){
    const addressInp = document.getElementById('lanPanelRoomAddress');
    const badge = document.getElementById('lanRoomPasscodeBadge');
    if(!addressInp && !badge) return;

    const defaultAddress = window.location.origin;
    if(addressInp && !addressInp.value) addressInp.value = defaultAddress;

    try {
        const res = await fetch(`/api/lan/host/room?_t=${Date.now()}`);
        if(res.ok){
            const data = await res.json();
            const room = data.room;
            if(room){
                const hostAddr = room.hostIp ? `http://${room.hostIp}:${room.port || 8900}` : defaultAddress;
                if(addressInp) addressInp.value = hostAddr;
                if(badge){
                    if(room.passcode && room.passcode.trim()){
                        badge.textContent = `PIN 码: ${room.passcode.trim()}`;
                        badge.style.background = 'var(--hover-bg, rgba(255, 255, 255, 0.08))';
                        badge.style.color = 'var(--text-primary, #f2f3f5)';
                    } else {
                        badge.textContent = '免密自由加入';
                        badge.style.background = 'rgba(16, 185, 129, 0.12)';
                        badge.style.color = '#10b981';
                    }
                }
            }
        }
    } catch(e) {}
}
window.updateLanRoomInfo = updateLanRoomInfo;

