function updateSmartWorkflowTransferMeta(){
    const payload = selectedSmartWorkflowPayload();
    const nodeCount = payload.nodes.length;
    const connCount = payload.connections.length;
    smartWorkflowExportMeta?.classList.remove('busy', 'success');
    if(smartWorkflowExportMeta) smartWorkflowExportMeta.textContent = nodeCount ? `已选择 ${nodeCount} 个节点，${connCount} 条连线` : '未选择节点，请先选中要导出的组件';
    if(smartWorkflowTransferSub) smartWorkflowTransferSub.textContent = nodeCount ? '导出当前选中内容，或把工作流导入到当前画布' : '请先选中节点再导出；导入会追加到当前画布';
}
async function exportSelectedSmartWorkflow(includeResources=false){
    if(!canvas) return;
    const payload = selectedSmartWorkflowPayload();
    if(!payload.nodes.length){
        updateSmartWorkflowTransferMeta();
        toast('未选择节点，请先选中要导出的组件');
        return;
    }
    try {
        if(!includeResources){
            downloadBlob(new Blob([JSON.stringify(payload, null, 2)], {type:'application/json'}), smartWorkflowFilename('json'));
            toast('已导出智能画布工作流 JSON');
            return;
        }
        if(smartWorkflowExportMeta){
            smartWorkflowExportMeta.classList.add('busy');
            smartWorkflowExportMeta.textContent = '正在打包资源...';
        }
        const filename = smartWorkflowFilename('zip');
        const res = await fetch('/api/canvas-workflows/export', {
            method:'POST',
            headers:{'Content-Type':'application/json'},
            body:JSON.stringify({...payload, include_resources:true, filename})
        });
        if(!res.ok) throw new Error(await responseErrorMessage(res, '导出工作流失败'));
        downloadBlob(await res.blob(), filename);
        if(smartWorkflowExportMeta){
            smartWorkflowExportMeta.classList.remove('busy');
            smartWorkflowExportMeta.classList.add('success');
            smartWorkflowExportMeta.textContent = `已导出 ${payload.nodes.length} 个节点，包含可找到的本地资源`;
        }
        toast('已导出包含资源的智能画布工作流包');
        setTimeout(() => {
            if(smartWorkflowTransferModal?.classList.contains('open')) updateSmartWorkflowTransferMeta();
        }, 1600);
    } catch(err) {
        smartWorkflowExportMeta?.classList.remove('busy', 'success');
        toast(err.message || '导出工作流失败');
    }
}
function resolveSmartWorkflowConnections(targetNodes, initialConns = []){
    const list = (targetNodes || []).filter(Boolean);
    const existingConns = Array.isArray(initialConns) ? initialConns.filter(c => c && c.from && c.to) : [];
    const connMap = new Set(existingConns.map(c => `${c.from}->${c.to}`));
    const newConns = [...existingConns];

    const addConn = (fromId, toId, kind = 'input') => {
        if(!fromId || !toId || fromId === toId) return;
        const key = `${fromId}->${toId}`;
        if(connMap.has(key)) return;
        connMap.add(key);
        newConns.push({ from: fromId, to: toId, kind: kind || 'input' });
    };

    const allKnownNodes = [...(Array.isArray(nodes) ? nodes : []), ...list];
    const nodeById = new Map();
    const nodeByName = new Map();
    const nodeByAsset = new Map();
    const nodeByUrl = new Map();

    const normalizeKey = str => String(str || '').trim().toLowerCase();
    const cleanUrl = url => {
        if(!url) return '';
        let u = String(url).split('?')[0].split('#')[0];
        const lastSlash = Math.max(u.lastIndexOf('/'), u.lastIndexOf('\\'));
        return lastSlash >= 0 ? u.slice(lastSlash + 1).toLowerCase() : u.toLowerCase();
    };

    allKnownNodes.forEach(node => {
        if(!node || !node.id) return;
        nodeById.set(node.id, node);
        const titles = [node.title, node.name, node.data?.title, node.data?.name].filter(Boolean);
        titles.forEach(t => {
            const k = normalizeKey(t);
            if(!nodeByName.has(k)) nodeByName.set(k, []);
            nodeByName.get(k).push(node);
            const base = k.replace(/\.[^.]+$/, '');
            if(base !== k){
                if(!nodeByName.has(base)) nodeByName.set(base, []);
                nodeByName.get(base).push(node);
            }
        });

        const imgs = Array.isArray(node.images) ? node.images : [];
        imgs.forEach(img => {
            if(!img) return;
            const names = [img.name, img.originalName, img.alias].filter(Boolean);
            names.forEach(n => {
                const k = normalizeKey(n);
                if(!nodeByAsset.has(k)) nodeByAsset.set(k, []);
                nodeByAsset.get(k).push(node);
                const base = k.replace(/\.[^.]+$/, '');
                if(base !== k){
                    if(!nodeByAsset.has(base)) nodeByAsset.set(base, []);
                    nodeByAsset.get(base).push(node);
                }
            });
            if(img.url){
                const uKey = cleanUrl(img.url);
                if(!nodeByUrl.has(uKey)) nodeByUrl.set(uKey, []);
                nodeByUrl.get(uKey).push(node);
            }
        });
    });

    list.forEach(node => {
        if(!node) return;
        const matchedSources = new Set();

        // 1. 已有 inputNodeIds 物理连线还原
        if(Array.isArray(node.inputNodeIds)){
            node.inputNodeIds.forEach(id => {
                if(id && nodeById.has(id)){
                    matchedSources.add(id);
                }
            });
        }

        // 2. 从 runInputRefs / manualInputRefs / promptRefs 中提取素材引用
        const refSources = [];
        if(node.runInputRefs){
            if(Array.isArray(node.runInputRefs)) refSources.push(...node.runInputRefs);
            else if(typeof node.runInputRefs === 'object') refSources.push(...Object.values(node.runInputRefs));
        }
        if(Array.isArray(node.manualInputRefs)) refSources.push(...node.manualInputRefs);
        if(Array.isArray(node.promptRefs)) refSources.push(...node.promptRefs);

        refSources.forEach(ref => {
            if(!ref) return;
            if(ref.nodeId && nodeById.has(ref.nodeId)){
                matchedSources.add(ref.nodeId);
                return;
            }
            if(ref.url){
                const uKey = cleanUrl(ref.url);
                const found = nodeByUrl.get(uKey);
                if(found && found.length){
                    matchedSources.add(found[0].id);
                    return;
                }
            }
            const name = ref.name || ref.originalName;
            if(name){
                const nKey = normalizeKey(name);
                const byAsset = nodeByAsset.get(nKey);
                if(byAsset && byAsset.length){
                    matchedSources.add(byAsset[0].id);
                    return;
                }
                const byName = nodeByName.get(nKey);
                if(byName && byName.length){
                    matchedSources.add(byName[0].id);
                    return;
                }
            }
        });

        // 3. 从 runModelPrompt 中提取别名/序号映射（例如 "图1: output-1.mp4", "图2: 绯璃立绘.png"）
        const runModelPrompt = String(node.runModelPrompt || '');
        const aliasMapping = new Map();
        if(runModelPrompt){
            const mapMatches = runModelPrompt.matchAll(/(?:图\d+|角色\d*|场景|尾帧|首帧|参考图\d*)[:：]\s*([^\r\n]+)/g);
            for(const m of mapMatches){
                const fullKey = m[0].split(/[:：]/)[0].trim();
                const fullVal = m[1].trim();
                const fnMatch = fullVal.match(/([^\s:：]+\.(?:png|jpg|jpeg|webp|mp4|webm|mov|gif))/i);
                aliasMapping.set(fullKey, fnMatch ? fnMatch[1].trim() : fullVal);
            }
        }

        // 4. 从 prompt 中提取 @ 提及，结合 aliasMapping 映射到对应素材
        const rawPrompt = String(node.promptDraftText || node.prompt || node.text || '');
        if(rawPrompt.includes('@')){
            const mentions = rawPrompt.matchAll(/@([^\s,，。!！?？:：;；\r\n]+)/g);
            for(const m of mentions){
                const tag = m[1].trim();
                const mappedName = aliasMapping.get(tag) || tag;
                const normTag = normalizeKey(mappedName);
                if(nodeByAsset.has(normTag)){
                    matchedSources.add(nodeByAsset.get(normTag)[0].id);
                    continue;
                }
                if(nodeByName.has(normTag)){
                    matchedSources.add(nodeByName.get(normTag)[0].id);
                    continue;
                }
                const uKey = cleanUrl(mappedName);
                if(nodeByUrl.has(uKey)){
                    matchedSources.add(nodeByUrl.get(uKey)[0].id);
                    continue;
                }
            }
        }

        // 5. 将匹配到的上游素材全量连接并写入 inputNodeIds
        const currentInputs = new Set(Array.isArray(node.inputNodeIds) ? node.inputNodeIds : []);
        matchedSources.forEach(srcId => {
            if(srcId && srcId !== node.id){
                currentInputs.add(srcId);
                addConn(srcId, node.id, 'input');
            }
        });
        node.inputNodeIds = Array.from(currentInputs);

        // 6. 智能提取分镜标记并丰富标题
        const fullPromptText = `${rawPrompt} ${String(node.runPrompt || '')} ${String(node.title || '')}`;
        const shotMatch = fullPromptText.match(/(?:【镜头\s*\d+[a-zA-Z]?】|\[镜头\s*\d+[a-zA-Z]?\]|第\s*\d+\s*镜)/);
        if(shotMatch){
            node.shotTag = shotMatch[0];
            const genericTitles = ['视频', '视频生成', '图片', '图片生成', 'smart', 'output-1.mp4'];
            if(!node.title || genericTitles.includes(node.title.trim())){
                node.title = `${shotMatch[0]} ${node.title || '视频'}`.trim();
            }
        }
    });

    return { nodes: list, connections: newConns };
}
window.resolveSmartWorkflowConnections = resolveSmartWorkflowConnections;

function reconnectCanvasWorkflowReferences(){
    if(!canvas || !Array.isArray(nodes) || !nodes.length) return false;
    const initialConns = canvas.connections || [];
    const resolved = resolveSmartWorkflowConnections(nodes, initialConns);
    let changed = false;
    if(resolved.connections.length !== initialConns.length){
        canvas.connections = resolved.connections;
        changed = true;
    }
    nodes.forEach(n => {
        const rawPrompt = String(n.promptDraftText || n.prompt || n.runPrompt || '').trim();
        if(rawPrompt && rawPrompt.includes('@') && !n.promptDraftHtml){
            try {
                const refs = visibleReferenceImagesFor(n);
                const rebuilt = promptHtmlWithMentionTokens(rawPrompt, refs, n);
                if(rebuilt){
                    n.promptDraftHtml = sanitizePromptDraftHtml(rebuilt);
                    changed = true;
                }
            } catch(_){}
        }
    });
    if(changed){
        render();
        scheduleSave();
    }
    return changed;
}
window.reconnectCanvasWorkflowReferences = reconnectCanvasWorkflowReferences;

function insertSmartWorkflowIntoCanvas(imported){
    const srcNodes = (imported.nodes || []).filter(Boolean);
    const srcConnections = (imported.connections || []).filter(Boolean);
    if(!canvas || !srcNodes.length) throw new Error('工作流中没有可导入的节点');
    pushUndo();
    const minX = Math.min(...srcNodes.map(n => Number(n.x || 0)));
    const minY = Math.min(...srcNodes.map(n => Number(n.y || 0)));
    const target = viewportCenter();
    const dx = target.x - minX;
    const dy = target.y - minY;
    const idMap = new Map();
    const newNodes = srcNodes.map(source => {
        const copy = serializableSmartNode(source);
        const oldId = copy.id || uid(copy.type || 'smart');
        copy.id = uid(copy.type || 'smart');
        copy.x = Number(copy.x || 0) + dx;
        copy.y = Number(copy.y || 0) + dy;
        copy.created_at = copy.created_at || Date.now();
        idMap.set(oldId, copy.id);
        return normalizeLegacySmartNode(copy);
    }).filter(Boolean);

    // 深度重写节点内部对旧 ID 的引用（包含连线输入 inputNodeIds、@引用 HTML token 与历史父级、runInputRefs 等）
    newNodes.forEach(node => {
        if(Array.isArray(node.inputNodeIds)){
            node.inputNodeIds = node.inputNodeIds.map(oldId => idMap.get(oldId) || oldId).filter(Boolean);
        }
        if(node.runInputRefs && typeof node.runInputRefs === 'object'){
            if(Array.isArray(node.runInputRefs)){
                node.runInputRefs.forEach(item => {
                    if(item?.nodeId && idMap.has(item.nodeId)) item.nodeId = idMap.get(item.nodeId);
                });
            } else {
                Object.values(node.runInputRefs).forEach(item => {
                    if(item?.nodeId && idMap.has(item.nodeId)) item.nodeId = idMap.get(item.nodeId);
                });
            }
        }
        if(Array.isArray(node.manualInputRefs)){
            node.manualInputRefs.forEach(item => {
                if(item?.nodeId && idMap.has(item.nodeId)) item.nodeId = idMap.get(item.nodeId);
            });
        }
        if(Array.isArray(node.promptRefs)){
            node.promptRefs.forEach(item => {
                if(item?.nodeId && idMap.has(item.nodeId)) item.nodeId = idMap.get(item.nodeId);
            });
        }
        if(node.promptDraftHtml && typeof node.promptDraftHtml === 'string'){
            const replacements = [...idMap.entries()]
                .filter(([oldId, newId]) => oldId && newId)
                .sort((a, b) => String(b[0]).length - String(a[0]).length);
            if(replacements.length){
                const escapeRegExp = value => String(value).replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
                const lookup = new Map(replacements.map(([oldId, newId]) => [String(oldId), String(newId)]));
                const pattern = new RegExp(replacements.map(([oldId]) => escapeRegExp(oldId)).join('|'), 'g');
                node.promptDraftHtml = node.promptDraftHtml.replace(pattern, match => lookup.get(match) || match);
            }
        }
        if(node.historyFor && idMap.has(node.historyFor)){
            node.historyFor = idMap.get(node.historyFor);
        }
        if(node.groupId && idMap.has(node.groupId)){
            node.groupId = idMap.get(node.groupId);
        }
    });

    const mappedConnections = srcConnections
        .map(conn => ({...JSON.parse(JSON.stringify(conn)), from:idMap.get(conn.from), to:idMap.get(conn.to)}))
        .filter(conn => conn.from && conn.to);

    // 智能自愈与全量解析所有输入连线（彻底解决素材节点悬空与连线丢失问题）
    const resolved = resolveSmartWorkflowConnections(newNodes, mappedConnections);
    const finalConnections = resolved.connections;

    // 为有 @ 引用的节点预建 promptDraftHtml，确保富文本药丸立即可见
    newNodes.forEach(node => {
        const rawPrompt = String(node.promptDraftText || node.prompt || node.runPrompt || '').trim();
        if(rawPrompt && rawPrompt.includes('@')){
            try {
                const refs = visibleReferenceImagesFor(node);
                const rebuilt = promptHtmlWithMentionTokens(rawPrompt, refs, node);
                if(rebuilt){
                    node.promptDraftHtml = sanitizePromptDraftHtml(rebuilt);
                }
            } catch(_){}
        }
    });

    nodes.push(...newNodes);
    canvas.connections = [...(canvas.connections || []), ...finalConnections];
    selectedIds = newNodes.length > 1 ? newNodes.map(node => node.id) : [];
    selectedId = newNodes.length === 1 ? newNodes[0].id : '';
    selectedImage = {nodeId:'', index:-1};
    activeComposerSubject = null;
    const isHeavyImport = newNodes.length >= 40 || nodes.length >= 120;
    smartCanvasImportBusy = isHeavyImport;
    render();

    // 视口自动居中聚焦到导入的这组节点，让用户清晰查阅全景
    if(newNodes.length){
        const allX = newNodes.map(n => Number(n.x || 0));
        const allY = newNodes.map(n => Number(n.y || 0));
        const bMinX = Math.min(...allX);
        const bMaxX = Math.max(...allX) + 380;
        const bMinY = Math.min(...allY);
        const bMaxY = Math.max(...allY) + 320;
        const spanW = Math.max(1, bMaxX - bMinX);
        const spanH = Math.max(1, bMaxY - bMinY);
        const screenW = shell?.clientWidth || window.innerWidth || 1920;
        const screenH = shell?.clientHeight || window.innerHeight || 1080;
        const fitScale = Math.min((screenW * 0.82) / spanW, (screenH * 0.82) / spanH);

        if (fitScale < 0.28) {
            // 超大工作流（跨度极大）：保持清晰可读比例 (~0.38)，优先聚焦起始输入节点群
            viewport.scale = 0.38;
            const startGroup = newNodes.filter(n => n.type === 'smart-upload' || (Array.isArray(n.inputNodeIds) && n.inputNodeIds.length === 0));
            const pool = startGroup.length > 0 ? startGroup : newNodes.slice(0, Math.min(6, newNodes.length));
            const pX = pool.map(n => Number(n.x || 0));
            const pY = pool.map(n => Number(n.y || 0));
            const pcX = (Math.min(...pX) + Math.max(...pX) + 260) / 2;
            const pcY = (Math.min(...pY) + Math.max(...pY) + 180) / 2;
            viewport.x = screenW / 2 - pcX * viewport.scale;
            viewport.y = screenH / 2 - pcY * viewport.scale;
        } else {
            viewport.scale = Math.max(0.28, Math.min(1.0, fitScale));
            const centerX = (bMinX + bMaxX) / 2;
            const centerY = (bMinY + bMaxY) / 2;
            viewport.x = (screenW / 2) - centerX * viewport.scale;
            viewport.y = (screenH / 2) - centerY * viewport.scale;
        }
        applyViewport();
    }

    if(isHeavyImport) scheduleSmartCanvasImportFinalize();

    // 自动确保连线显示处于开启状态，理清节点拓扑流动
    try {
        if(typeof setHideUnselectedConns === 'function') {
            setHideUnselectedConns(false, true);
        }
    } catch(_){}

    scheduleSave();
    toast(`已导入 ${newNodes.length} 个节点与完整连接线 (按住空格或滚轮可平移漫游)`);
}
window.insertSmartWorkflowIntoCanvas = insertSmartWorkflowIntoCanvas;
function renderPromptWithMentions(text){
    return window.SmartCanvasWorkflow.renderPromptWithMentions(text, escapeHtml);
}

function formatWorkflowTime(ts){
    return window.SmartCanvasWorkflow.formatWorkflowTime(ts);
}

function toggleWorkflowCard(wid){
    if(!window._wfExpandedIds) window._wfExpandedIds = new Set();
    if(window._wfExpandedIds.has(wid)){
        window._wfExpandedIds.delete(wid);
    } else {
        window._wfExpandedIds.add(wid);
    }
    loadSavedSmartWorkflows();
}
window.toggleWorkflowCard = toggleWorkflowCard;

async function archiveCurrentCanvasWorkflow(){
    if(!canvas) return;
    const payload = selectedSmartWorkflowPayload();
    let targetNodes = payload.nodes;
    let targetConns = payload.connections;
    if(!targetNodes.length){
        targetNodes = (nodes || []).filter(Boolean);
        targetConns = (canvas.connections || []).filter(Boolean);
        const resolved = resolveSmartWorkflowConnections(targetNodes, targetConns);
        targetNodes = resolved.nodes;
        targetConns = resolved.connections;
    }
    if(!targetNodes.length){
        toast('画布中没有节点可供归档');
        return;
    }

    const defaultName = `工程-${new Date().toISOString().slice(0, 10)}`;
    const name = prompt('请输入归档工程包名称：', defaultName);
    if(name === null) return;
    const cleanName = (name || '').trim() || defaultName;

    try {
        toast('正在归档工程...');
        const res = await fetch('/api/canvas-workflows', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                name: cleanName,
                nodes: targetNodes,
                connections: targetConns,
                resources: []
            })
        });
        if(!res.ok) throw new Error(await responseErrorMessage(res, '归档工程失败'));
        toast('当前画布已成功归档');
        loadSavedSmartWorkflows();
    } catch(err) {
        toast(err.message || '归档失败');
    }
}
window.archiveCurrentCanvasWorkflow = archiveCurrentCanvasWorkflow;

async function exportSingleWorkflowPackage(wid){
    if(!wid) return;
    try {
        toast('正在打包工程资源...');
        const getRes = await fetch('/api/canvas-workflows/' + encodeURIComponent(wid));
        if(!getRes.ok) throw new Error(await responseErrorMessage(getRes, '读取工程数据失败'));
        const getData = await getRes.json();
        const wf = getData.workflow;
        if(!wf) throw new Error('工程数据为空');
        
        const filename = `${(wf.name || wid).replace(/[\/\\?%*:|"<>]/g, '_')}-workflow.zip`;
        const exportRes = await fetch('/api/canvas-workflows/export', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                nodes: wf.nodes || [],
                connections: wf.connections || [],
                resources: wf.resources || [],
                include_resources: true,
                filename: filename
            })
        });
        if(!exportRes.ok) throw new Error(await responseErrorMessage(exportRes, '导出打包失败'));
        downloadBlob(await exportRes.blob(), filename);
        toast('工程包导出成功');
    } catch(err) {
        toast(err.message || '导出失败');
    }
}
window.exportSingleWorkflowPackage = exportSingleWorkflowPackage;

async function importSmartWorkflowFile(file){
    if(!canvas || !file) return;
    try {
        if(smartWorkflowTransferSub) smartWorkflowTransferSub.textContent = '正在解压并归档工作流...';
        toast('正在解压并解析工作流...');
        const form = new FormData();
        form.append('file', file);
        const res = await fetch('/api/canvas-workflows/import', {method:'POST', body:form});
        if(!res.ok) throw new Error(await responseErrorMessage(res, '导入工作流失败'));
        const data = await res.json();
        
        insertSmartWorkflowIntoCanvas(normalizeImportedSmartWorkflow(data));
        loadSavedSmartWorkflows();
        
        if(smartWorkflowTransferSub) smartWorkflowTransferSub.textContent = '已自动归档至工程库并加载到画布';
        toast(`工程“${data.archived_name || file.name}”已自动归档并载入画布`);
    } catch(err) {
        if(smartWorkflowTransferModal?.classList.contains('open')) updateSmartWorkflowTransferMeta();
        toast(err.message || '导入工作流失败');
    }
}

async function loadSavedSmartWorkflows(){
    const listEl = document.getElementById('smartWorkflowSavedList');
    if(!listEl) return;
    try {
        const res = await fetch('/api/canvas-workflows');
        if(!res.ok) throw new Error('读取工程归档列表失败');
        const data = await res.json();
        const items = data.workflows || [];
        const countBadge = document.getElementById('smartWorkflowCount');
        if(countBadge) countBadge.textContent = `${items.length} 个历史工程`;
        if(!items.length){
            listEl.innerHTML = `
                <div style="font-size:11px;color:var(--shop-text-muted);text-align:center;padding:36px 14px;border:1px dashed var(--shop-border-subtle);border-radius:8px;">
                    <i data-lucide="archive" style="width:24px;height:24px;display:block;margin:0 auto 8px auto;opacity:0.4;"></i>
                    <div>暂无已归档工程包</div>
                    <div style="font-size:10px;margin-top:4px;opacity:0.7;">点击右上角“+ 导入新包”或将 ZIP 拖入即可归档</div>
                </div>
            `;
            refreshIcons?.();
            return;
        }

        if(!window._wfExpandedIds){
            window._wfExpandedIds = new Set();
            if(items.length > 0) window._wfExpandedIds.add(items[0].id);
        }

        listEl.innerHTML = items.map((item) => {
            const summary = item.summary || {};
            const isExpanded = window._wfExpandedIds.has(item.id);
            const nodeCount = item.node_count || summary.node_count || 0;
            const connCount = item.connection_count || summary.connection_count || 0;
            const mediaCount = summary.media_count || item.resource_count || 0;
            
            const sender = item.sender || (item.name && item.name.includes('老铁') ? '老铁发来' : (item.name && item.name.includes('小张') ? '小张发来' : '同事发来'));
            const sizeStr = item.size ? `${item.size} · ` : '';
            const metaText = `${sender} · ${sizeStr}包含 ${mediaCount} 媒体`;
            
            const materialsText = summary.materials_text || `素材图片: ${mediaCount} 张`;
            const mentionsText = summary.mentions_text || '未包含@引用';
            const flowText = summary.flow_text || '角色立绘 ➔ 提示词合成 ➔ 图生视频';

            if(isExpanded){
                return `
                    <div class="workflow-archive-card expanded" id="wf_card_${escapeHtml(item.id)}">
                        <div class="wf-card-head" onclick="toggleWorkflowCard('${escapeHtml(item.id)}')">
                            <div class="wf-card-title-wrap">
                                <span class="wf-card-title">${escapeHtml(item.name || item.id)}</span>
                                <span class="wf-card-meta">${escapeHtml(metaText)}</span>
                            </div>
                            <div class="wf-card-actions" onclick="event.stopPropagation()">
                                <span class="wf-node-pill">${nodeCount} 节点</span>
                                <button type="button" class="wf-tool-btn danger" onclick="deleteSavedSmartWorkflow('${escapeHtml(item.id)}', '${escapeHtml(item.name || item.id)}')" title="删除工程" aria-label="删除工程">
                                    <i data-lucide="trash-2"></i>
                                </button>
                            </div>
                        </div>

                        <div class="wf-summary-box">
                            <div class="wf-summary-row">
                                <span>${escapeHtml(materialsText)}</span>
                                <span>连线: ${connCount} 条</span>
                            </div>
                            <div class="wf-summary-row truncate">
                                <span>@引用: ${escapeHtml(mentionsText)}</span>
                            </div>
                        </div>

                        <div class="wf-card-btn-grid">
                            <button type="button" class="wf-main-btn primary" onclick="insertSmartWorkflowFromLibrary('${escapeHtml(item.id)}')">
                                载入当前画布
                            </button>
                            <button type="button" class="wf-main-btn secondary" onclick="exportSingleWorkflowPackage('${escapeHtml(item.id)}')">
                                导出分享
                            </button>
                        </div>
                    </div>
                `;
            } else {
                return `
                    <div class="workflow-archive-card collapsed" id="wf_card_${escapeHtml(item.id)}" onclick="toggleWorkflowCard('${escapeHtml(item.id)}')">
                        <div class="wf-card-head">
                            <div class="wf-card-title-wrap">
                                <span class="wf-card-title">${escapeHtml(item.name || item.id)}</span>
                                <span class="wf-card-meta">${escapeHtml(metaText)} · ${nodeCount} 节点</span>
                            </div>
                            <span class="wf-status-pill">已归档</span>
                        </div>
                        <div class="wf-flow-desc">${escapeHtml(flowText)}</div>
                        <div class="wf-collapsed-footer" onclick="event.stopPropagation()">
                            <button type="button" class="wf-tool-btn danger" onclick="deleteSavedSmartWorkflow('${escapeHtml(item.id)}', '${escapeHtml(item.name || item.id)}')" title="删除工程" aria-label="删除工程">
                                <i data-lucide="trash-2"></i>
                            </button>
                            <button type="button" class="wf-small-btn" onclick="toggleWorkflowCard('${escapeHtml(item.id)}')">查看详情</button>
                        </div>
                    </div>
                `;
            }
        }).join('');
        refreshIcons?.();
    } catch(err) {
        listEl.innerHTML = `<div style="font-size:11px;color:var(--shop-text-muted);text-align:center;padding:16px;">${escapeHtml(err.message || '加载工程归档失败')}</div>`;
    }
}
window.loadSavedSmartWorkflows = loadSavedSmartWorkflows;

