function persistActiveSmartSettings(){
    if(!composer?.classList?.contains('open')) return;
    const subject = activeComposerNode();
    if(!subject) return;
    subject.runSettings = settingsForStorage(settings);
    if(!subject.params) subject.params = {};
    const isVideo = isApiLikeEngine(settings.engine) && settings.apiKind === 'video';
    if(isVideo){
        const vAspect = settings.videoAspect || '16:9';
        const vRes = settings.videoResolution || '720p';
        const vDims = getVideoDimensions(vAspect, vRes);
        subject.params.videoResolution = vRes;
        subject.params.videoAspect = vAspect;
        subject.params.videoDuration = settings.videoDuration;
        subject.params.videoFormat = settings.videoFormat || 'mp4';
        subject.params.videoGenerateAudio = Boolean(settings.videoGenerateAudio);
        subject.params.width = vDims.width;
        subject.params.height = vDims.height;
        settings.videoWidth = vDims.width;
        settings.videoHeight = vDims.height;
    } else {
        const ratio = normalizeImageRatio(settings.ratio || '1:1');
        const res = (settings.resolution || '2k').toLowerCase();
        const dims = getImageDimensions(ratio, res);
        subject.params.resolution = settings.resolution;
        subject.params.ratio = settings.ratio;
        subject.params.width = dims.width;
        subject.params.height = dims.height;
        settings.width = dims.width;
        settings.height = dims.height;
    }
    subject.params.count = Number(settings.count) || 1;
    subject.params.batch_size = Number(settings.count) || 1;
    subject.params.provider_id = settings.provider_id;
    subject.params.model = settings.model;
    subject.params.imageMode = settings.imageMode;
    rememberRecentSmartSettings(settings, subject);
}
