window.refreshSelectionAnchoredOverlays = refreshSelectionAnchoredOverlays;
window.getCanvasData = () => canvas;
window.setCanvasData = (newCanvas) => { canvas = newCanvas; smartMinimapGeometryDirty = true; };
window.saveCanvasInstance = (opts) => saveCanvas(opts);
window.scheduleSaveCanvas = (delay) => scheduleSave(delay);
window.renderCanvas = () => render();

let viewportAnimRaf = 0;
function smoothAnimateViewport(targetX, targetY, targetScale, duration = 380, onComplete = null){
    if(viewportAnimRaf){
        cancelAnimationFrame(viewportAnimRaf);
        viewportAnimRaf = 0;
    }
    const startX = viewport.x;
    const startY = viewport.y;
    const startScale = viewport.scale;
    const startTime = performance.now();
    const easeOutCubic = t => 1 - Math.pow(1 - t, 3);

    function step(now){
        const elapsed = now - startTime;
        const progress = Math.min(1, elapsed / duration);
        const ease = easeOutCubic(progress);
        viewport.x = startX + (targetX - startX) * ease;
        viewport.y = startY + (targetY - startY) * ease;
        viewport.scale = startScale + (targetScale - startScale) * ease;
        applyViewport();
        if(progress < 1){
            viewportAnimRaf = requestAnimationFrame(step);
        } else {
            viewportAnimRaf = 0;
            if(typeof onComplete === 'function') onComplete();
        }
    }
    viewportAnimRaf = requestAnimationFrame(step);
}

function recoverViewportToNodes(smooth = true){
    const validNodes = (nodes || []).filter(n => n && n.id !== SMART_LOG_PREVIEW_NODE_ID);
    if(!validNodes.length) return;
    const rects = validNodes.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const maxX = Math.max(...rects.map(r => r.x + (r.width || 260)));
    const maxY = Math.max(...rects.map(r => r.y + (r.height || 160)));
    const contentW = Math.max(1, maxX - minX);
    const contentH = Math.max(1, maxY - minY);
    const cx = (minX + maxX) / 2;
    const cy = (minY + maxY) / 2;

    const screenW = shell?.clientWidth || window.innerWidth || 1920;
    const screenH = shell?.clientHeight || window.innerHeight || 1080;

    // 12% margin: available screen area is 76% (1 - 2 * 0.12)
    const availW = Math.max(100, screenW * 0.76);
    const availH = Math.max(100, screenH * 0.76);

    const rawScale = Math.min(availW / contentW, availH / contentH);
    let targetScale, targetX, targetY;

    if (rawScale < 0.28) {
        // 超大工作流（跨度极大）：不强行缩放到 0.1 导致视觉挤压堆叠，保持舒适可读比例 (~0.38)，聚焦起始输入区
        targetScale = 0.38;
        const startNodes = validNodes.filter(n => n.type === 'smart-upload' || (Array.isArray(n.inputNodeIds) && n.inputNodeIds.length === 0));
        const focusPool = startNodes.length > 0 ? startNodes : validNodes.slice(0, Math.min(6, validNodes.length));
        const focusRects = focusPool.map(nodeRect);
        const fMinX = Math.min(...focusRects.map(r => r.x));
        const fMaxX = Math.max(...focusRects.map(r => r.x + (r.width || 260)));
        const fMinY = Math.min(...focusRects.map(r => r.y));
        const fMaxY = Math.max(...focusRects.map(r => r.y + (r.height || 160)));
        const focusCx = (fMinX + fMaxX) / 2;
        const focusCy = (fMinY + fMaxY) / 2;
        targetX = screenW / 2 - focusCx * targetScale;
        targetY = screenH / 2 - focusCy * targetScale;
    } else {
        targetScale = Math.max(0.28, Math.min(1.2, rawScale));
        targetX = screenW / 2 - cx * targetScale;
        targetY = screenH / 2 - cy * targetScale;
    }

    const banner = document.getElementById('viewportLostBanner');
    if(banner){
        banner.classList.remove('visible');
        setTimeout(() => { banner.style.display = 'none'; }, 280);
    }

    if(smooth){
        smoothAnimateViewport(targetX, targetY, targetScale, 380, () => {
            scheduleSave();
        });
    } else {
        viewport.x = targetX;
        viewport.y = targetY;
        viewport.scale = targetScale;
        applyViewport();
        scheduleSave();
    }
}

function checkViewportLostState(){
    const banner = document.getElementById('viewportLostBanner');
    if(!banner) return;
    const validNodes = (nodes || []).filter(n => n && n.id !== SMART_LOG_PREVIEW_NODE_ID);
    if(!validNodes.length){
        banner.classList.remove('visible');
        banner.style.display = 'none';
        return;
    }
    const screenW = shell?.clientWidth || window.innerWidth || 1920;
    const screenH = shell?.clientHeight || window.innerHeight || 1080;
    const s = safeScale(viewport.scale);

    let visibleCount = 0;
    for(const n of validNodes){
        const r = nodeRect(n);
        const sl = r.x * s + viewport.x;
        const st = r.y * s + viewport.y;
        const sr = (r.x + (r.width || 260)) * s + viewport.x;
        const sb = (r.y + (r.height || 160)) * s + viewport.y;
        if(sr > 0 && sl < screenW && sb > 0 && st < screenH){
            visibleCount++;
            break;
        }
    }
    const isLost = (validNodes.length > 0 && visibleCount === 0);
    if(isLost){
        banner.style.display = 'flex';
        if(window.lucide && banner.querySelector('i[data-lucide]')){
            lucide.createIcons({ root: banner });
        }
        void banner.offsetWidth;
        banner.classList.add('visible');
    } else {
        banner.classList.remove('visible');
        if(!banner._hideTimer){
            banner._hideTimer = setTimeout(() => {
                if(!banner.classList.contains('visible')){
                    banner.style.display = 'none';
                }
                banner._hideTimer = null;
            }, 300);
        }
    }
}

/* ==========================================================================
   Cinema Fullscreen Lightbox Controller (智能画布影院级画廊预览)
   ========================================================================== */
let cinemaZoom = 1.0;
let cinemaPanX = 0;
let cinemaPanY = 0;
let cinemaIsDragging = false;
let cinemaDragStartX = 0;
let cinemaDragStartY = 0;
let cinemaInitialPanX = 0;
let cinemaInitialPanY = 0;
let cinemaIsVideo = false;

function applyCinemaImageTransform(animate = false){
    const imgEl = document.getElementById('cinemaPreviewImg');
    if(!imgEl) return;
    if(animate){
        imgEl.style.transition = 'transform 0.22s cubic-bezier(0.16, 1, 0.3, 1)';
    } else {
        imgEl.style.transition = 'none';
    }
    imgEl.style.transform = `translate(${cinemaPanX}px, ${cinemaPanY}px) scale(${cinemaZoom})`;
    if(cinemaZoom > 1.001){
        imgEl.style.cursor = cinemaIsDragging ? 'grabbing' : 'grab';
    } else {
        imgEl.style.cursor = 'zoom-in';
    }
}

function resetCinemaZoom(animate = true){
    cinemaZoom = 1.0;
    cinemaPanX = 0;
    cinemaPanY = 0;
    cinemaIsDragging = false;
    applyCinemaImageTransform(animate);
}

let cinemaOpenedAt = 0;
let cinemaDidDrag = false;
let cinemaCurrentSourceVideo = null;

function pauseAllBackgroundMedia(excludeEl = null){
    try {
        const mediaElements = document.querySelectorAll('video, audio');
        mediaElements.forEach(m => {
            if(m !== excludeEl && !m.paused){
                try { m.pause(); } catch(_) {}
            }
        });
    } catch(_) {}
}

function openCinemaPreview(payload){
    if(!payload) return;
    const modal = document.getElementById('cinemaPreviewModal');
    const imgEl = document.getElementById('cinemaPreviewImg');
    const videoEl = document.getElementById('cinemaPreviewVideo');
    if(!modal || !imgEl || !videoEl) return;

    initCinemaPreviewEvents();

    let url = typeof payload === 'string' ? payload : (payload.url || payload.src || '');
    if(!url) return;
    if(typeof displayMediaUrl === 'function'){
        url = displayMediaUrl(url);
    }

    // 若当前弹窗已打开且显示相同 URL，不重复刷新
    if(modal.classList.contains('open') && (imgEl.src === url || videoEl.getAttribute('data-url') === url)){
        pauseAllBackgroundMedia(videoEl);
        return;
    }

    const isVideo = payload.type === 'video' || (typeof isVideoUrl === 'function' && isVideoUrl(url)) || /\.(mp4|webm|mov|mkv|avi)(\?.*)?$/i.test(url) || (payload.kind === 'video');
    cinemaIsVideo = isVideo;

    resetCinemaZoom(false);
    cinemaDidDrag = false;

    // 尝试定位源视频元素与读取当前播放进度
    let sourceVideo = (payload && typeof payload === 'object' && payload.sourceMedia) ? payload.sourceMedia : null;
    if(!sourceVideo && isVideo){
        const candidateVideos = Array.from(document.querySelectorAll('video:not(#cinemaPreviewVideo):not(#previewCurrentVideo)'));
        sourceVideo = candidateVideos.find(v => {
            const s = v.dataset?.originalSrc || v.dataset?.url || v.getAttribute('src') || v.currentSrc || '';
            return s && (s === url || (typeof playbackVideoUrl === 'function' && playbackVideoUrl(s) === playbackVideoUrl(url)));
        }) || null;
    }
    cinemaCurrentSourceVideo = sourceVideo || null;

    let startFrom = 0;
    if(payload && typeof payload === 'object' && Number.isFinite(payload.currentTime) && payload.currentTime > 0.05){
        startFrom = payload.currentTime;
    } else if(sourceVideo && Number.isFinite(sourceVideo.currentTime) && sourceVideo.currentTime > 0.05){
        startFrom = sourceVideo.currentTime;
    }

    // 关键：在放大视频播放前，立即暂停画布所有背景音视频，防止小图大图同时发声
    pauseAllBackgroundMedia(videoEl);
    if(sourceVideo && !sourceVideo.paused){
        try { sourceVideo.pause(); } catch(_) {}
    }

    if(isVideo){
        imgEl.style.display = 'none';
        imgEl.src = '';
        videoEl.style.display = 'block';
        videoEl.setAttribute('data-url', url);
        const targetSrc = typeof playbackVideoUrl === 'function' ? playbackVideoUrl(url) : url;
        const needsReload = videoEl.src !== targetSrc;
        if(needsReload){
            videoEl.src = targetSrc;
        }

        const applyPlayback = () => {
            if(startFrom > 0.05 && (!videoEl.duration || startFrom < videoEl.duration - 0.2)){
                try { videoEl.currentTime = startFrom; } catch(_) {}
            }
            videoEl.play().catch(() => {});
        };

        if(!needsReload && videoEl.readyState >= 1){
            applyPlayback();
        } else {
            videoEl.addEventListener('loadedmetadata', applyPlayback, { once: true });
            if(needsReload) videoEl.load();
        }
    } else {
        if(videoEl){
            videoEl.pause();
            videoEl.style.display = 'none';
            videoEl.removeAttribute('src');
            videoEl.load();
        }
        imgEl.style.display = 'block';
        imgEl.src = url;
    }

    cinemaOpenedAt = Date.now();
    modal.style.pointerEvents = 'auto';
    modal.style.display = 'flex';
    void modal.offsetWidth;
    modal.classList.add('open');
    modal.classList.add('active');
    modal.focus();
}

function closeCinemaPreview(force = false){
    const modal = document.getElementById('cinemaPreviewModal');
    const imgEl = document.getElementById('cinemaPreviewImg');
    const videoEl = document.getElementById('cinemaPreviewVideo');
    if(!modal) return;
    // 保护期：打开后 350ms 内拦截任何由用户双击手势残留的 click 触发的关闭
    if(!force && Date.now() - cinemaOpenedAt < 350) return;

    const finalTime = (videoEl && Number.isFinite(videoEl.currentTime)) ? videoEl.currentTime : 0;

    if(videoEl){
        videoEl.pause();
        videoEl.removeAttribute('src');
        videoEl.load();
    }

    // 关闭放大视窗后，同步播放时间回原视频节点，并保持原视频为暂停状态（避免突然爆音）
    if(cinemaCurrentSourceVideo){
        try {
            if(Number.isFinite(finalTime) && finalTime > 0){
                cinemaCurrentSourceVideo.currentTime = finalTime;
            }
            if(!cinemaCurrentSourceVideo.paused){
                cinemaCurrentSourceVideo.pause();
            }
        } catch(_) {}
        cinemaCurrentSourceVideo = null;
    }

    modal.classList.remove('open');
    modal.classList.remove('active');
    modal.style.display = 'none';
    modal.style.pointerEvents = 'none';
    if(imgEl) imgEl.src = '';
    resetCinemaZoom(false);
    cinemaDidDrag = false;
}

function initCinemaPreviewEvents(){
    const modal = document.getElementById('cinemaPreviewModal');
    const container = document.getElementById('cinemaPreviewContainer');
    const imgEl = document.getElementById('cinemaPreviewImg');
    const closeBtn = document.getElementById('cinemaPreviewCloseBtn');
    const backBtn = document.getElementById('viewportLostBackBtn');
    if(backBtn && !backBtn._bound){
        backBtn._bound = true;
        backBtn.addEventListener('click', () => recoverViewportToNodes(true));
    }
    const lostBanner = document.getElementById('viewportLostBanner');
    if(lostBanner && !lostBanner._boundClick){
        lostBanner._boundClick = true;
        lostBanner.addEventListener('click', (e) => {
            if(e.target === lostBanner) recoverViewportToNodes(true);
        });
    }

    // 全局捕获阶段：当大图预览模态框开启时，严格拦截并暂停任何画布背景视频的播放，防止异步回调或手势导致背景视频重新跑起来
    if(!window._cinemaPlayInterceptorInstalled){
        window._cinemaPlayInterceptorInstalled = true;
        document.addEventListener('play', e => {
            const previewModal = document.getElementById('cinemaPreviewModal');
            if(previewModal && (previewModal.classList.contains('open') || previewModal.style.display === 'flex')){
                const cinemaVid = document.getElementById('cinemaPreviewVideo');
                if(e.target && e.target !== cinemaVid && typeof e.target.pause === 'function'){
                    try { e.target.pause(); } catch(_) {}
                }
            }
        }, true);
    }

    if(!modal || modal._initialized) return;
    modal._initialized = true;

    if(closeBtn){
        closeBtn.addEventListener('click', e => {
            e.stopPropagation();
            closeCinemaPreview(true);
        });
    }

    modal.addEventListener('click', e => {
        // 如果刚打开不到 350ms，或者刚才发生了拖拽移动，不关闭
        if(Date.now() - cinemaOpenedAt < 350) return;
        if(cinemaDidDrag){
            cinemaDidDrag = false;
            return;
        }
        if(e.target === modal || e.target === container){
            closeCinemaPreview(true);
        }
    });

    modal.addEventListener('dblclick', e => {
        // 双击背景阻止默认行为，不关闭
        if(e.target === modal || e.target === container){
            e.preventDefault();
            e.stopPropagation();
        }
    });

    modal.addEventListener('wheel', e => {
        if(!modal.classList.contains('open') || cinemaIsVideo) return;
        e.preventDefault();
        e.stopPropagation();

        const zoomDelta = e.deltaY < 0 ? 0.2 : -0.2;
        const prevZoom = cinemaZoom;
        cinemaZoom = Math.max(1.0, Math.min(6.0, cinemaZoom + zoomDelta));

        if(cinemaZoom <= 1.001){
            cinemaZoom = 1.0;
            cinemaPanX = 0;
            cinemaPanY = 0;
        } else if(prevZoom !== cinemaZoom){
            const rect = imgEl.getBoundingClientRect();
            const mouseX = e.clientX - rect.left - rect.width / 2;
            const mouseY = e.clientY - rect.top - rect.height / 2;
            const factor = (cinemaZoom - prevZoom) / prevZoom;
            cinemaPanX -= mouseX * factor * 0.4;
            cinemaPanY -= mouseY * factor * 0.4;
        }
        applyCinemaImageTransform(false);
    }, {passive: false});

    if(imgEl){
        imgEl.addEventListener('mousedown', e => {
            if(cinemaIsVideo || e.button !== 0) return;
            if(cinemaZoom > 1.001){
                e.preventDefault();
                e.stopPropagation();
                cinemaIsDragging = true;
                cinemaDragStartX = e.clientX;
                cinemaDragStartY = e.clientY;
                cinemaInitialPanX = cinemaPanX;
                cinemaInitialPanY = cinemaPanY;
                applyCinemaImageTransform(false);
            }
        });

        imgEl.addEventListener('dblclick', e => {
            if(cinemaIsVideo) return;
            e.preventDefault();
            e.stopPropagation();
            if(cinemaZoom > 1.001){
                resetCinemaZoom(true);
            } else {
                cinemaZoom = 2.5;
                const rect = imgEl.getBoundingClientRect();
                const mouseX = e.clientX - (rect.left + rect.width / 2);
                const mouseY = e.clientY - (rect.top + rect.height / 2);
                cinemaPanX = -mouseX * 1.2;
                cinemaPanY = -mouseY * 1.2;
                applyCinemaImageTransform(true);
            }
        });
    }

    window.addEventListener('mousemove', e => {
        if(!cinemaIsDragging || cinemaIsVideo) return;
        e.preventDefault();
        const dx = e.clientX - cinemaDragStartX;
        const dy = e.clientY - cinemaDragStartY;
        if(Math.abs(dx) > 3 || Math.abs(dy) > 3){
            cinemaDidDrag = true;
        }
        cinemaPanX = cinemaInitialPanX + dx;
        cinemaPanY = cinemaInitialPanY + dy;
        applyCinemaImageTransform(false);
    });

    window.addEventListener('mouseup', e => {
        if(cinemaIsDragging){
            cinemaIsDragging = false;
            applyCinemaImageTransform(false);
            setTimeout(() => { cinemaDidDrag = false; }, 50);
        }
    });
}
window.openCinemaPreview = openCinemaPreview;
window.closeCinemaPreview = closeCinemaPreview;
window.recoverViewportToNodes = recoverViewportToNodes;

function triggerSmartMaterialZoom(el, e){
    if(e){
        try {
            e.preventDefault();
            e.stopPropagation();
        } catch(_) {}
    }
    if(!el) return false;

    // 定位目标素材项与外层节点
    const item = el.closest?.('.thumb-item, .image-wrap, .smart-group-single-thumb, .asset-item, .frame-slot-card, .minimax-material-card') || el;
    const nodeEl = item.closest?.('.image-node') || el.closest?.('.image-node');
    // 处于宫格切分、视频裁剪或图片裁剪模式时，不拦截双击放大
    if(typeof activeGridCut !== 'undefined' && activeGridCut) return false;
    if(typeof activeVideoCrop !== 'undefined' && activeVideoCrop) return false;
    if(typeof activeImageCrop !== 'undefined' && activeImageCrop) return false;

    const nodeId = item.dataset?.refNodeId || nodeEl?.dataset?.id || (item.classList?.contains('image-node') ? item.dataset?.id : '') || (el.dataset?.id || '');
    const node = nodeId ? (nodes.find(n => String(n.id) === String(nodeId)) || null) : null;

    const imageIndex = Number(item.dataset?.refImageIndex ?? item.dataset?.imageIndex ?? el.dataset?.imageIndex ?? 0);

    let mediaUrl = '';
    let mediaKind = 'image';
    let mediaName = '';

    // 1. 从节点数据读取
    if(node && Array.isArray(node.images) && node.images.length > 0){
        const rawImg = node.images[imageIndex] || node.images[0];
        const imgObj = imageForDisplay(rawImg);
        if(typeof imgObj === 'string'){
            mediaUrl = imgObj;
        } else if(imgObj && typeof imgObj === 'object'){
            mediaUrl = imgObj.originalLocalUrl || imgObj.url || imgObj.src || imgObj.path || '';
            mediaKind = mediaKindForItem(imgObj) || (typeof isVideoUrl === 'function' && isVideoUrl(mediaUrl) ? 'video' : 'image');
            mediaName = imgObj.name || node.title || node.name || '';
        }
    }

    // 2. 从元素 dataset 读取
    if(!mediaUrl && item.dataset){
        mediaUrl = item.dataset.originalUrl || item.dataset.url || item.dataset.mediaUrl || item.dataset.src || '';
        if(item.dataset.kind) mediaKind = item.dataset.kind;
        if(item.dataset.name) mediaName = item.dataset.name;
    }

    // 3. 从素材库查阅
    if(!mediaUrl && item.dataset?.assetId){
        const assetObj = (typeof findAssetItemById === 'function' ? findAssetItemById(item.dataset.assetId) : null)
            || (typeof activeAssetCategory === 'function' && activeAssetCategory()?.items || []).find(x => x.id === item.dataset.assetId);
        if(assetObj?.url){
            mediaUrl = assetObj.url;
            mediaKind = assetObj.kind || mediaKind;
            mediaName = assetObj.name || mediaName;
        }
    }

    // 提取关联的真实视频元素（用于提取播放时间及暂停源视频）
    const sourceVideoEl = item?.querySelector?.('video')
        || (item?.tagName === 'VIDEO' ? item : null)
        || (el?.tagName === 'VIDEO' ? el : null)
        || el?.closest?.('video')
        || el?.querySelector?.('video')
        || nodeEl?.querySelector?.('video.node-video-element, video');

    // 4. 从真实 DOM 媒体元素回退提取
    if(!mediaUrl){
        const mediaEl = sourceVideoEl || item?.querySelector?.('img, video, audio') || (item?.tagName === 'IMG' || item?.tagName === 'VIDEO' ? item : null) || (el?.tagName === 'IMG' || el?.tagName === 'VIDEO' ? el : null);
        if(mediaEl){
            mediaUrl = mediaEl.dataset?.originalSrc || mediaEl.dataset?.url || mediaEl.currentSrc || mediaEl.src || '';
            if(mediaEl.tagName === 'VIDEO') mediaKind = 'video';
            else if(mediaEl.tagName === 'AUDIO') mediaKind = 'audio';
            else mediaKind = 'image';
        }
    }

    // 清理媒体 URL 包装
    if(typeof smartOriginalMediaUrl === 'function' && mediaUrl){
        mediaUrl = smartOriginalMediaUrl(mediaUrl);
    }

    if(!mediaName && node){
        mediaName = node.title || node.name || '素材放大';
    }
    if(!mediaName){
        mediaName = '素材放大';
    }
    if(mediaKind !== 'video' && typeof isVideoUrl === 'function' && isVideoUrl(mediaUrl)){
        mediaKind = 'video';
    }

    if(sourceVideoEl && typeof sourceVideoEl.pause === 'function'){
        try { sourceVideoEl.pause(); } catch(_) {}
    }

    if(mediaUrl){
        if(typeof hideAssetHoverPreview === 'function') hideAssetHoverPreview();
        const currentPlaybackTime = (sourceVideoEl && Number.isFinite(sourceVideoEl.currentTime) && sourceVideoEl.currentTime > 0) ? sourceVideoEl.currentTime : 0;
        openCinemaPreview({
            url: mediaUrl,
            type: mediaKind,
            name: mediaName,
            sourceMedia: sourceVideoEl || undefined,
            currentTime: currentPlaybackTime
        });
        return true;
    }
    return false;
}
window.triggerSmartMaterialZoom = triggerSmartMaterialZoom;
function screenToWorld(event){ return window.SmartCanvasInteraction.screenToWorld(event, interactionDeps()); }
function worldToScreen(point){ return window.SmartCanvasInteraction.worldToScreen(point, interactionDeps()); }
function viewportCenter(){ return window.SmartCanvasInteraction.viewportCenter(interactionDeps()); }

const EDGE_AUTO_PAN_MARGIN = 60;
const EDGE_AUTO_PAN_MAX_SPEED = 10.0;
const EDGE_AUTO_PAN_MIN_SPEED = 1.0;

function isEdgeAutoPanActive(){
    return Boolean(dragState || portDragState || selectionState || isNativeDragging);
}

function computeEdgeAutoPanVelocity(clientX, clientY){
    if(!isEdgeAutoPanActive() || panState || zoomPreviewState) return {x: 0, y: 0};
    if(assetLibraryOpen && assetPanel){
        const hit = document.elementFromPoint(clientX, clientY);
        if(hit && assetPanel.contains(hit)) return {x: 0, y: 0};
    }
    const rect = shell ? shell.getBoundingClientRect() : {
        left: 0,
        top: 0,
        right: window.innerWidth,
        bottom: window.innerHeight,
        width: window.innerWidth,
        height: window.innerHeight
    };
    return window.SmartCanvasInteraction.edgeAutoPanVelocity(
        clientX, clientY, rect,
        EDGE_AUTO_PAN_MARGIN, EDGE_AUTO_PAN_MIN_SPEED, EDGE_AUTO_PAN_MAX_SPEED
    );
}

function checkEdgeAutoPan(clientX, clientY, isNative = false){
    if(isNative) isNativeDragging = true;
    lastPointerPos = {clientX, clientY};
    const v = computeEdgeAutoPanVelocity(clientX, clientY);
    edgeAutoPanVelocity = v;
    if(v.x === 0 && v.y === 0){
        if(edgeAutoPanRaf){
            cancelAnimationFrame(edgeAutoPanRaf);
            edgeAutoPanRaf = 0;
            lastEdgeAutoPanTime = 0;
        }
        return;
    }
    if(!edgeAutoPanRaf){
        lastEdgeAutoPanTime = performance.now();
        edgeAutoPanRaf = requestAnimationFrame(edgeAutoPanStep);
    }
}

function stopEdgeAutoPan(){
    if(edgeAutoPanRaf){
        cancelAnimationFrame(edgeAutoPanRaf);
        edgeAutoPanRaf = 0;
    }
    edgeAutoPanVelocity = {x: 0, y: 0};
    lastEdgeAutoPanTime = 0;
    isNativeDragging = false;
}

function edgeAutoPanStep(now){
    if(!isEdgeAutoPanActive()){
        stopEdgeAutoPan();
        return;
    }
    if(lastPointerPos){
        edgeAutoPanVelocity = computeEdgeAutoPanVelocity(lastPointerPos.clientX, lastPointerPos.clientY);
    }
    const vx = edgeAutoPanVelocity.x;
    const vy = edgeAutoPanVelocity.y;
    if(Math.abs(vx) < 0.01 && Math.abs(vy) < 0.01){
        stopEdgeAutoPan();
        return;
    }
    if(!lastEdgeAutoPanTime) lastEdgeAutoPanTime = now;
    const dt = Math.min(0.05, Math.max(0.001, (now - lastEdgeAutoPanTime) / 1000));
    lastEdgeAutoPanTime = now;
    const speedFactor = dt / (1 / 60);
    const stepVx = vx * speedFactor;
    const stepVy = vy * speedFactor;
    viewport.x += stepVx;
    viewport.y += stepVy;
    applyViewport();
    if(lastPointerPos){
        if(dragState){
            updateDragNodePositions(lastPointerPos);
        } else if(portDragState){
            updatePortDragStateForPointer(lastPointerPos);
        } else if(selectionState){
            updateSelectionBox(lastPointerPos);
        }
    }
    if(edgeAutoPanRaf){
        edgeAutoPanRaf = requestAnimationFrame(edgeAutoPanStep);
    }
}

window.worldToScreen = worldToScreen;
window.checkEdgeAutoPan = checkEdgeAutoPan;
window.stopEdgeAutoPan = stopEdgeAutoPan;
window.isEdgeAutoPanActive = isEdgeAutoPanActive;
window.computeEdgeAutoPanVelocity = computeEdgeAutoPanVelocity;
let smartMinimapRaf = 0;
function renderMinimap(immediate = false){
    if(immediate){
        if(smartMinimapRaf){
            cancelAnimationFrame(smartMinimapRaf);
            smartMinimapRaf = 0;
        }
        renderMinimapDirect();
    } else {
        if(smartMinimapRaf) return;
        smartMinimapRaf = requestAnimationFrame(() => {
            smartMinimapRaf = 0;
            renderMinimapDirect();
        });
    }
}
function renderMinimapDirect(){
    if(!minimapContent) return;
    const width = minimapContent.clientWidth || 170;
    const height = minimapContent.clientHeight || 108;
    const viewW = shell.clientWidth / viewport.scale;
    const viewH = shell.clientHeight / viewport.scale;
    const viewX = -viewport.x / viewport.scale;
    const viewY = -viewport.y / viewport.scale;
    const needsGeometry = smartMinimapGeometryDirty
        || !smartMinimapState
        || smartMinimapState.width !== width
        || smartMinimapState.height !== height;
    if(needsGeometry){
        smartMinimapNodeRects = nodes.filter(n => n && n.id !== SMART_LOG_PREVIEW_NODE_ID).map(node => ({id:String(node.id), rect:nodeRect(node)}));
        smartMinimapState = minimapGeometry(smartMinimapNodeRects.map(item => item.rect), width, height);
        smartMinimapNodeElements.forEach(el => el.remove());
        smartMinimapNodeElements = new Map();
    }
    const project = r => projectMinimapRect(r, smartMinimapState);

    let vpEl = minimapViewport || document.getElementById('minimapViewport');
    if(!vpEl){
        vpEl = document.createElement('div');
        vpEl.id = 'minimapViewport';
        vpEl.className = 'smart-minimap-viewport';
        minimapContent.appendChild(vpEl);
        minimapViewport = vpEl;
    }

    if(needsGeometry){
        const liveIds = new Set(smartMinimapNodeRects.map(item => item.id));
        smartMinimapNodeElements.forEach((nodeEl, id) => {
            if(!liveIds.has(id)) nodeEl.remove();
        });
        smartMinimapNodeRects.forEach(item => {
            let nodeEl = smartMinimapNodeElements.get(item.id);
            if(!nodeEl){
                nodeEl = document.createElement('div');
                nodeEl.className = 'minimap-node';
                nodeEl.dataset.id = item.id;
                minimapContent.insertBefore(nodeEl, vpEl);
                smartMinimapNodeElements.set(item.id, nodeEl);
            }
            const p = project(item.rect);
            nodeEl.style.left = `${p.left}px`;
            nodeEl.style.top = `${p.top}px`;
            nodeEl.style.width = `${p.width}px`;
            nodeEl.style.height = `${p.height}px`;
        });
        smartMinimapGeometryDirty = false;
    }
    const view = project({x:viewX, y:viewY, width:viewW, height:viewH});
    vpEl.style.left = `${view.left}px`;
    vpEl.style.top = `${view.top}px`;
    vpEl.style.width = `${view.width}px`;
    vpEl.style.height = `${view.height}px`;
}
window.renderMinimap = renderMinimap;
window.renderMinimapDirect = renderMinimapDirect;
function minimapEventToWorld(event){
    if(!smartMinimapState) renderMinimap(true);
    const state = smartMinimapState;
    if(!state) return viewportCenter();
    const rect = minimapContent.getBoundingClientRect();
    const mx = event.clientX - rect.left;
    const my = event.clientY - rect.top;
    return {
        x:state.minX + (mx - state.offsetX) / Math.max(0.0001, state.scale),
        y:state.minY + (my - state.offsetY) / Math.max(0.0001, state.scale)
    };
}
function centerViewportOnWorldPoint(point){
    viewport.x = shell.clientWidth / 2 - point.x * viewport.scale;
    viewport.y = shell.clientHeight / 2 - point.y * viewport.scale;
    applyViewport();
    scheduleSave();
}
function fitAllNodesViewport(){
    if(!nodes.length){
        viewport.scale = 0.45;
        viewport.x = shell.clientWidth / 2;
        viewport.y = shell.clientHeight / 2;
        applyViewport();
        scheduleSave();
        return;
    }
    const rects = nodes.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const maxX = Math.max(...rects.map(r => r.x + r.width));
    const maxY = Math.max(...rects.map(r => r.y + r.height));
    const pad = 160;
    const width = Math.max(1, maxX - minX + pad * 2);
    const height = Math.max(1, maxY - minY + pad * 2);
    const nextScale = Math.max(0.06, Math.min(0.82, (shell.clientWidth - 80) / width, (shell.clientHeight - 80) / height));
    const cx = (minX + maxX) / 2;
    const cy = (minY + maxY) / 2;
    viewport.scale = nextScale;
    viewport.x = shell.clientWidth / 2 - cx * viewport.scale;
    viewport.y = shell.clientHeight / 2 - cy * viewport.scale;
    applyViewport();
    scheduleSave();
}
function enterZoomPreview(){
    if(zoomPreviewState) return;
    zoomPreviewState = {...viewport};
    shell.classList.add('zoom-preview');
    closeCreateMenu();
    fitAllNodesViewport();
}
function exitZoomPreview(point=null){
    if(!zoomPreviewState) return false;
    const prev = zoomPreviewState;
    zoomPreviewState = null;
    shell.classList.remove('zoom-preview');
    viewport.scale = prev.scale;
    if(point){
        viewport.x = shell.clientWidth / 2 - point.x * viewport.scale;
        viewport.y = shell.clientHeight / 2 - point.y * viewport.scale;
    } else {
        viewport.x = prev.x;
        viewport.y = prev.y;
    }
    applyViewport();
    scheduleSave();
    return true;
}
function exitZoomPreviewToNode(nodeId){
    if(!zoomPreviewState) return false;
    const node = nodes.find(n => n.id === nodeId);
    if(!node) return exitZoomPreview();
    const prev = zoomPreviewState;
    const rect = nodeRect(node);
    const cx = rect.x + rect.width / 2;
    const cy = rect.y + rect.height / 2;
    const fitW = Math.max(1, shell.clientWidth - 160);
    const fitH = Math.max(1, shell.clientHeight - 160);
    const fitScale = Math.min(
        ZOOM_PREVIEW_NODE_MAX_SCALE,
        fitW / Math.max(1, rect.width),
        fitH / Math.max(1, rect.height)
    );
    const readableScale = Math.min(ZOOM_PREVIEW_NODE_MAX_SCALE, Math.max(ZOOM_PREVIEW_NODE_DEFAULT_SCALE, fitScale));
    zoomPreviewState = null;
    shell.classList.remove('zoom-preview');
    viewport.scale = Math.max(safeScale(prev.scale), readableScale);
    viewport.x = shell.clientWidth / 2 - cx * viewport.scale;
    viewport.y = shell.clientHeight / 2 - cy * viewport.scale;
    applyViewport();
    scheduleSave();
    return true;
}
function toggleZoomPreview(){
    if(zoomPreviewState) exitZoomPreview();
    else enterZoomPreview();
}

// 沉浸式工具会话视口记忆与聚焦过渡 (Focus to Fit Engine)
let toolSessionPreviousViewport = null;
let viewportAnimationRaf = null;

function cancelViewportAnimation(){
    if(viewportAnimationRaf){
        cancelAnimationFrame(viewportAnimationRaf);
        viewportAnimationRaf = null;
    }
}

function animateViewportTo(target, duration = 220, onComplete){
    cancelViewportAnimation();
    const start = {
        x: viewport.x,
        y: viewport.y,
        scale: safeScale(viewport.scale)
    };
    const targetScale = safeScale(target.scale);
    const targetX = target.x;
    const targetY = target.y;
    const startTime = performance.now();

    const step = (now) => {
        const elapsed = now - startTime;
        const progress = Math.min(1, elapsed / Math.max(1, duration));
        // 三次缓出 (Cubic Ease-Out): 阻尼柔和，贴合物理手感
        const ease = 1 - Math.pow(1 - progress, 3);

        viewport.scale = start.scale + (targetScale - start.scale) * ease;
        viewport.x = start.x + (targetX - start.x) * ease;
        viewport.y = start.y + (targetY - start.y) * ease;
        applyViewport({ isPanning: true });

        if(progress < 1){
            viewportAnimationRaf = requestAnimationFrame(step);
        } else {
            viewportAnimationRaf = null;
            viewport.scale = targetScale;
            viewport.x = targetX;
            viewport.y = targetY;
            applyViewport();
            scheduleSave();
            if(typeof onComplete === 'function') onComplete();
        }
    };
    viewportAnimationRaf = requestAnimationFrame(step);
}

function focusNodeForToolSession(nodeId, callback, duration = 220, toolType = null){
    const node = nodes.find(n => String(n.id) === String(nodeId));
    if(!node){
        if(typeof callback === 'function') callback();
        return;
    }

    // 记录进入工具前的初始视口（仅在未记录时记录，防止多次切换覆盖原始视角）
    if(!toolSessionPreviousViewport){
        toolSessionPreviousViewport = {
            x: viewport.x,
            y: viewport.y,
            scale: safeScale(viewport.scale)
        };
    }

    const rect = nodeRect(node);
    const nodeEl = world?.querySelector?.(`.image-node[data-id="${CSS.escape(node.id)}"]`);
    const nodeW = Math.max(1, (nodeEl && nodeEl.offsetWidth > 10 ? nodeEl.offsetWidth : 0) || rect.width || node.w || 380);
    const nodeH = Math.max(1, (nodeEl && nodeEl.offsetHeight > 10 ? nodeEl.offsetHeight : 0) || rect.height || node.h || 260);
    const cx = rect.x + nodeW / 2;
    const cy = rect.y + nodeH / 2;

    const shellW = shell.clientWidth || window.innerWidth;
    const shellH = shell.clientHeight || window.innerHeight;

    // 方案 A（极大化适应 / Max-Fit）：压缩无用空白，仅为必须的操作悬浮栏留出精确实时空间，整图贴边放大
    const resolvedType = toolType ||
        ((activeVideoCrop || document.body.classList.contains('in-video-crop')) ? 'video-crop' :
         (activeImageCrop || document.body.classList.contains('in-image-crop')) ? 'image-crop' :
         (activeGridCut || document.body.classList.contains('in-canvas-grid-cut')) ? 'grid-cut' : null);

    let padX = 16;
    let padTop = 18;
    let padBottom = 18;

    if(resolvedType === 'image-crop'){
        padTop = 68;    // 顶部预留 68px 供工坊外置横排栏舒适吸附
        padBottom = 16; // 底部贴边仅留 16px 呼吸空隙
    } else if(resolvedType === 'video-crop'){
        padTop = 18;    // 顶部贴边仅留 18px
        padBottom = 66; // 底部预留 66px 供视频微型剪辑条完整展示
    } else if(resolvedType === 'grid-cut'){
        padTop = 20;
        padBottom = 64; // 底部预留 64px 供切分导出栏
    } else {
        const index = smartNodeToolbarImageIndex(node);
        const item = imageForDisplay(node.images?.[index] || node.images?.[0]);
        if(mediaKindForItem(item) === 'video'){
            padTop = 18;
            padBottom = 66;
        } else {
            padTop = 68;
            padBottom = 16;
        }
    }

    const availW = Math.max(100, shellW - padX * 2);
    const availH = Math.max(100, shellH - padTop - padBottom);

    const fitScale = Math.min(availW / nodeW, availH / nodeH);
    const targetScale = Math.max(0.1, Math.min(safeScale(fitScale), 5.0));

    const visualCenterY = padTop + availH / 2;
    const targetX = shellW / 2 - cx * targetScale;
    const targetY = visualCenterY - cy * targetScale;

    animateViewportTo({ x: targetX, y: targetY, scale: targetScale }, duration, callback);
}

function restoreToolSessionViewport(duration = 220){
    if(!toolSessionPreviousViewport) return;
    // 如果当前仍然有活跃的裁剪或切分会话，暂不恢复
    if(activeImageCrop || activeGridCut || (typeof activeVideoCrop !== 'undefined' && activeVideoCrop)) return;
    const prev = toolSessionPreviousViewport;
    toolSessionPreviousViewport = null;
    animateViewportTo(prev, duration);
}

function positionGridTemplateMenu(){
    const menu = document.querySelector('.grid-template-menu');
    if(!menu) return;
    const nodeId = menu.dataset.nodeId || '';
    const gridBtn = smartNodeFloatingMenu?.querySelector('[data-smart-node-action="grid"]') || (nodeId ? document.querySelector(`.image-node[data-id="${CSS.escape(nodeId)}"]`) : null);
    if(!gridBtn) return;
    const anchorRect = gridBtn.getBoundingClientRect();
    const menuW = Math.max(240, menu.offsetWidth || 240);
    let left = Math.round(anchorRect.left + anchorRect.width / 2 - menuW / 2);
    let top = Math.round(anchorRect.bottom + 6);
    left = Math.max(12, Math.min(window.innerWidth - menuW - 12, left));
    if(top + 220 > window.innerHeight && anchorRect.top > 230){
        top = Math.round(anchorRect.top - 210);
    }
    menu.style.left = `${left}px`;
    menu.style.top = `${top}px`;
}

