function resolveChatModel(model='', providerId=''){
    const resolvedProvider = resolveChatProviderId(providerId);
    const models = providerChatModels(resolvedProvider);
    if(model && models.includes(model)) return model;
    const chatBinding = smartApiDefaults?.bindings?.chat;
    if(chatBinding && (!chatBinding.provider_id || chatBinding.provider_id === resolvedProvider) && models.includes(chatBinding.model)){
        return chatBinding.model;
    }
    if(smartApiDefaults?.models?.chat && models.includes(smartApiDefaults.models.chat)){
        return smartApiDefaults.models.chat;
    }
    return models[0] || '';
}
