function sanitizeSmartApiSelection(target=settings){
    if(!target || typeof target !== 'object') return target;
    if(target.engine === 'volcengine'){
        if(target.apiKind === 'video'){
            target.videoProvider = 'volcengine';
            const models = volcengineVideoModels();
            if(!models.includes(target.videoModel)) target.videoModel = models[0] || '';
        } else {
            target.provider_id = 'volcengine';
            const models = providerImageModels('volcengine');
            if(!models.includes(target.model)) target.model = models[0] || '';
        }
        return target;
    }
    clearVolcengineSelectionOutsideVolcengine(target);
    const defaultProvider = smartApiDefaults.provider_id || '';
    const imageBinding = smartApiDefaults.bindings?.image || null;
    const videoBinding = smartApiDefaults.bindings?.video || null;
    if((target.engine || 'api') === 'api' && (target.apiKind || 'image') !== 'video'){
        const imgProviders = imageProviders();
        if(!target.provider_id || !imgProviders.some(p => p.id === target.provider_id)){
            target.provider_id = (imageBinding && imageBinding.provider_id && imgProviders.some(p => p.id === imageBinding.provider_id))
                ? imageBinding.provider_id
                : (defaultProvider && imgProviders.some(p => p.id === defaultProvider) ? defaultProvider : (imgProviders[0]?.id || ''));
        }
        if(target.provider_id){
            const models = providerImageModels(target.provider_id);
            if(!target.model || !models.includes(target.model)){
                if(imageBinding && imageBinding.provider_id === target.provider_id && models.includes(imageBinding.model)){
                    target.model = imageBinding.model;
                } else if(smartApiDefaults.models?.image && models.includes(smartApiDefaults.models.image)){
                    target.model = smartApiDefaults.models.image;
                } else {
                    target.model = models[0] || '';
                }
            }
        }
        const allowAuto = isGptImageAutoSizeModel(target.model);
        if(!target.resolution) target.resolution = allowAuto ? defaultSmartApiResolution(target.model) : '1k';
        if(!allowAuto && target.resolution === 'auto') target.resolution = '1k';
    }
    if((target.engine || 'api') === 'api' && (target.apiKind || 'image') === 'video'){
        const vidProviders = videoApiProviders();
        if(!target.videoProvider || !vidProviders.some(p => p.id === target.videoProvider)){
            target.videoProvider = (videoBinding && videoBinding.provider_id && vidProviders.some(p => p.id === videoBinding.provider_id))
                ? videoBinding.provider_id
                : (defaultProvider && vidProviders.some(p => p.id === defaultProvider) ? defaultProvider : (vidProviders[0]?.id || ''));
        }
        if(target.videoProvider){
            const models = providerVideoModels(target.videoProvider);
            if(!target.videoModel || !models.includes(target.videoModel)){
                if(videoBinding && videoBinding.provider_id === target.videoProvider && models.includes(videoBinding.model)){
                    target.videoModel = videoBinding.model;
                } else if(smartApiDefaults.models?.video && models.includes(smartApiDefaults.models.video)){
                    target.videoModel = smartApiDefaults.models.video;
                } else {
                    target.videoModel = models[0] || '';
                }
            }
            target.provider_id = target.videoProvider;
            target.model = target.videoModel;
        }
    }
    return target;
}
