function positionVideoCompositePopover(ctrl){
    const pop = ctrl?.querySelector?.('.video-composite-popover, .image-composite-popover');
    if(!pop) return;
    pop.classList.add('open');
    ctrl.classList.add('popover-up');
    pop.style.removeProperty('position');
    pop.style.removeProperty('left');
    pop.style.removeProperty('right');
    pop.style.removeProperty('top');
    pop.style.removeProperty('bottom');
    pop.style.removeProperty('width');
    pop.style.removeProperty('min-width');
    pop.style.removeProperty('max-width');
    pop.style.removeProperty('z-index');
}
