function getActiveRealImageModels(){
    const list = [];
    const providers = (apiProviders || []).filter(p => p && p.enabled !== false);
    for(const p of providers){
        const models = (p.image_models || []).filter(Boolean);
        for(const m of models){
            list.push({
                providerId: p.id,
                providerName: p.name || p.id,
                modelId: m,
                displayName: formatRealImageModelName(p, m)
            });
        }
    }
    return list;
}
function formatRealImageModelName(provider, modelId){
    const id = String(modelId || '').trim();
    if(id.toLowerCase().includes('sdxl') || id.toLowerCase().includes('stable-diffusion-xl')) return 'SDXL';
    if(id.toLowerCase().includes('flux.1-schnell') || id === 'flux-schnell') return 'FLUX.1 Schnell';
    if(id.toLowerCase().includes('flux.1-dev') || id === 'flux-dev') return 'FLUX.1 Dev';
    if(id.toLowerCase().includes('flux.1-pro') || id === 'flux-pro') return 'FLUX.1 Pro';
    if(id.toLowerCase().includes('flux.2-klein') || id === 'flux2-klein') return 'FLUX.2 Klein';
    if(id.toLowerCase().includes('doubao-image')) return 'Doubao-Image';
    if(id.toLowerCase().includes('doubao-seededit')) return 'Doubao-SeedEdit';
    if(id.toLowerCase().includes('z-image-turbo') || id.toLowerCase().includes('zimage')) return 'Z-Image Turbo';
    if(id.toLowerCase().includes('qwen-image-edit')) return 'Qwen Image Edit';
    if(id.toLowerCase().includes('midjourney')) return 'Midjourney';
    if(id.toLowerCase().includes('dall-e-3')) return 'DALL-E 3';
    if(id.toLowerCase().includes('gpt-image-2.5-sunburst') || id.toLowerCase().includes('gpt-image-2-5-sunburst')) return 'GPT-Image 2.5 Sunburst';
    if(id.toLowerCase().includes('gpt-image-2.5-flare') || id.toLowerCase().includes('gpt-image-2-5-flare')) return 'GPT-Image 2.5 Flare';
    if(id.toLowerCase().includes('gpt-image-2.5') || id.toLowerCase().includes('gpt-image-2-5')) return 'GPT-Image 2.5';
    if(id.toLowerCase().includes('gpt-image')) return 'GPT-Image';
    if(id.toLowerCase().includes('imagen-3')) return 'Imagen 3';
    if(id.toLowerCase().includes('kling-image')) return 'Kling Image';
    return id;
}
