            const mode = btn.dataset.videoMode;
            if(mode === 'standard'){
                settings.videoMultimodal = false;
                settings.videoUseFrameRoles = false;
                settings._videoMultimodalUserSet = true;
            } else if(mode === 'multimodal'){
                settings.videoMultimodal = true;
                settings.videoUseFrameRoles = false;
                settings._videoMultimodalUserSet = true;
            } else if(mode === 'frames'){
                settings.videoMultimodal = false;
                settings.videoUseFrameRoles = true;
            }
            normalizeSmartVideoModeSettings(settings, mode === 'frames');
            persistActiveSmartSettings();
