async function loadConfig(){
    try {
        const cfg = await fetch(`/api/config?scope_id=${encodeURIComponent(smartApiScopeId())}`).then(r => r.json());
        apiProviders = Array.isArray(cfg.api_providers) ? cfg.api_providers : [];
        smartApiDefaults.provider_id = cfg.api_defaults?.provider_id || '';
        smartApiDefaults.models = cfg.api_defaults?.models && typeof cfg.api_defaults.models === 'object' ? cfg.api_defaults.models : {};
        if(cfg.api_defaults?.bindings && typeof cfg.api_defaults.bindings === 'object'){
            smartApiDefaults.bindings = {
                image: cfg.api_defaults.bindings.image ? { ...cfg.api_defaults.bindings.image } : null,
                video: cfg.api_defaults.bindings.video ? { ...cfg.api_defaults.bindings.video } : null,
                chat: cfg.api_defaults.bindings.chat ? { ...cfg.api_defaults.bindings.chat } : null
            };
        }
        if(cfg.api_defaults?.default_models && typeof cfg.api_defaults.default_models === 'object'){
            smartApiDefaults.models = { ...smartApiDefaults.models, ...cfg.api_defaults.default_models };
        }
        if(!smartApiDefaults.bindings?.chat && (smartApiDefaults.models?.chat || cfg.api_defaults?.default_models?.chat)){
            const chatModel = smartApiDefaults.models?.chat || cfg.api_defaults?.default_models?.chat;
            smartApiDefaults.bindings = {
                ...smartApiDefaults.bindings,
                chat: {
                    provider_id: smartApiDefaults.provider_id || '',
                    model: chatModel
                }
            };
        }
        comfyInstanceCount = Math.max(1, (Array.isArray(cfg.comfy_instances) ? cfg.comfy_instances : []).filter(Boolean).length || 1);
        // 预取新节点默认绑定（default_bindings），供视频/图片新节点默认消费；失败时静默回退旧逻辑
        await loadSmartApiDefaultBindings();
        applySmartApiDefaultsToRuntimeState();
        // 提供商配置已就绪即先渲染参数面板，避免等工作流/RunningHub 预取完成后参数才「突然刷新出来」。
        sanitizeSmartApiSelection(settings);
        updateProviderModels();
        const wf = await fetch('/api/workflows').then(r => r.json()).catch(() => ({workflows:[]}));
        comfyWorkflows = Array.isArray(wf.workflows) ? wf.workflows : [];
        runningHubWorkflowCache = {};
        const rhProvider = apiProviders.find(p => p.id === 'runninghub');
        const rhWorkflowIds = (rhProvider?.rh_workflows || []).map(item => String(item.workflowId || item.id || '').trim()).filter(Boolean);
        await Promise.all(rhWorkflowIds.map(async workflowId => {
            try { await ensureRunningHubWorkflow(workflowId); } catch(_) {}
        }));
        lastConfigRefreshAt = Date.now();
        sanitizeSmartApiSelection(settings);
        updateProviderModels();
    } catch(e) {
        toast(tr('smart.toastApiSettingsFail'));
    }
}
function applySmartApiDefaultsToRuntimeState(){
    const imageBinding = smartApiDefaults?.bindings?.image;
    const videoBinding = smartApiDefaults?.bindings?.video;
    const chatBinding = smartApiDefaults?.bindings?.chat;

    // 1. 同步画布级默认配置
    if(canvasDefaultSmartSettings){
        if(imageBinding?.provider_id && imageBinding?.model){
            canvasDefaultSmartSettings.provider_id = imageBinding.provider_id;
            canvasDefaultSmartSettings.model = imageBinding.model;
        }
        if(videoBinding?.provider_id && videoBinding?.model){
            canvasDefaultSmartSettings.videoProvider = videoBinding.provider_id;
            canvasDefaultSmartSettings.videoModel = videoBinding.model;
            canvasDefaultSmartSettings.provider_id = videoBinding.provider_id;
            canvasDefaultSmartSettings.model = videoBinding.model;
        }
        if(chatBinding?.provider_id && chatBinding?.model){
            canvasDefaultSmartSettings.chatProvider = chatBinding.provider_id;
            canvasDefaultSmartSettings.chatModel = chatBinding.model;
            canvasDefaultSmartSettings.llmProvider = chatBinding.provider_id;
            canvasDefaultSmartSettings.llmModel = chatBinding.model;
        }
    }
    if(typeof initialSmartSettings !== 'undefined' && initialSmartSettings){
        if(imageBinding?.provider_id && imageBinding?.model){
            initialSmartSettings.provider_id = imageBinding.provider_id;
            initialSmartSettings.model = imageBinding.model;
        }
        if(videoBinding?.provider_id && videoBinding?.model){
            initialSmartSettings.videoProvider = videoBinding.provider_id;
            initialSmartSettings.videoModel = videoBinding.model;
            initialSmartSettings.provider_id = videoBinding.provider_id;
            initialSmartSettings.model = videoBinding.model;
        }
        if(chatBinding?.provider_id && chatBinding?.model){
            initialSmartSettings.chatProvider = chatBinding.provider_id;
            initialSmartSettings.chatModel = chatBinding.model;
            initialSmartSettings.llmProvider = chatBinding.provider_id;
            initialSmartSettings.llmModel = chatBinding.model;
        }
    }

    // 2. 强行对齐 recent settings，避免被旧 localStorage 脏缓存锁定
    if(imageBinding?.provider_id && imageBinding?.model){
        if(!recentSmartSettingsByMode['api:image']) recentSmartSettingsByMode['api:image'] = {};
        recentSmartSettingsByMode['api:image'].provider_id = imageBinding.provider_id;
        recentSmartSettingsByMode['api:image'].model = imageBinding.model;
    }
    if(videoBinding?.provider_id && videoBinding?.model){
        if(!recentSmartSettingsByMode['api:video']) recentSmartSettingsByMode['api:video'] = {};
        recentSmartSettingsByMode['api:video'].videoProvider = videoBinding.provider_id;
        recentSmartSettingsByMode['api:video'].videoModel = videoBinding.model;
        recentSmartSettingsByMode['api:video'].provider_id = videoBinding.provider_id;
        recentSmartSettingsByMode['api:video'].model = videoBinding.model;
    }
    if(chatBinding?.provider_id && chatBinding?.model){
        if(!recentSmartSettingsByMode['api:chat']) recentSmartSettingsByMode['api:chat'] = {};
        recentSmartSettingsByMode['api:chat'].provider_id = chatBinding.provider_id;
        recentSmartSettingsByMode['api:chat'].model = chatBinding.model;
        recentSmartSettingsByMode['api:chat'].llmProvider = chatBinding.provider_id;
        recentSmartSettingsByMode['api:chat'].llmModel = chatBinding.model;
    }
    try { saveRecentSmartSettings(); } catch(e) {}

    // 3. 遍历更新画布上所有未执行卡片
    (nodes || []).forEach(n => {
        if(!n) return;
        const hasExecuted = (n.images && n.images.length > 0) || n.running || n.pending || n.queued || n.lastRunAt || n.runPrompt;
        if(hasExecuted || n._isDefaultBinding === false) return;
        const isVideo = isSmartVideoNode(n) || n.genKind === 'video' || n.type === 'smart-video';
        const isImage = isSmartImageGenNode(n) || n.genKind === 'image' || n.type === 'smart-image' || n.type === 'image-gen';
        const isPrompt = n.type === 'smart-prompt';
        if(isVideo && videoBinding?.provider_id && videoBinding?.model){
            if(!n.runSettings) n.runSettings = {};
            n.runSettings.videoProvider = videoBinding.provider_id;
            n.runSettings.videoModel = videoBinding.model;
            n.runSettings.provider_id = videoBinding.provider_id;
            n.runSettings.model = videoBinding.model;
            if(n.params) {
                delete n.params.videoProvider;
                delete n.params.videoModel;
                delete n.params.provider_id;
                delete n.params.model;
            }
            n._isDefaultBinding = true;
        } else if(isImage && imageBinding?.provider_id && imageBinding?.model){
            if(!n.runSettings) n.runSettings = {};
            n.runSettings.provider_id = imageBinding.provider_id;
            n.runSettings.model = imageBinding.model;
            if(n.params) {
                delete n.params.provider_id;
                delete n.params.model;
            }
            n._isDefaultBinding = true;
        } else if(isPrompt && chatBinding?.provider_id && chatBinding?.model){
            n.llmProvider = chatBinding.provider_id;
            n.llmModel = chatBinding.model;
            n._isDefaultBinding = true;
        }
    });

    // 4. 更新当前活动的 settings
    const node = selectedNode();
    const isExistingRealNode = Boolean(
        node && (
            (node.images && node.images.length > 0) ||
            node.running || node.pending || node.queued ||
            node.lastRunAt || node.runPrompt || node.runAt
        )
    );
    if(!isExistingRealNode && (!node || node._isDefaultBinding !== false)){
        const isVideo = isSmartVideoNode(node) || settings.apiKind === 'video';
        if(isVideo && videoBinding?.provider_id && videoBinding?.model){
            settings.videoProvider = videoBinding.provider_id;
            settings.videoModel = videoBinding.model;
            settings.provider_id = videoBinding.provider_id;
            settings.model = videoBinding.model;
        } else if(!isVideo && imageBinding?.provider_id && imageBinding?.model){
            settings.provider_id = imageBinding.provider_id;
            settings.model = imageBinding.model;
        }
        sanitizeSmartApiSelection(settings);
    }
}
async function refreshSmartConfigFromSettings(){
    await loadConfig();
    applySmartApiDefaultsToRuntimeState();
    const node = selectedNode();
    renderDynamicParams();
    if(node) syncComposerNodeBadge(node);
    if(node?.type === 'smart-prompt' && typeof applySettingsToNode === 'function') {
        applySettingsToNode(node);
    }
    render();
}
function assetCategories(type='image'){
    const library = activeAssetLibrary();
    return (library?.categories || assetLibrary.categories || []).filter(cat => (cat.type || 'image') === type);
}
function assetSmartClassKey(entry){
    return window.SmartCanvasAssets.assetSmartClassKey(entry);
}
function assetSmartClassOptionId(entry){
    return window.SmartCanvasAssets.assetSmartClassOptionId(entry, ASSET_SMART_CATEGORY_PREFIX);
}
function parseAssetSmartClassId(id=''){
    return window.SmartCanvasAssets.parseAssetSmartClassId(id, ASSET_SMART_CATEGORY_PREFIX);
}
function assetSmartClassEntries(){
    const groups = new Map();
    assetCategories('image').forEach(cat => {
        (cat.items || []).forEach(item => {
            const flat = Array.isArray(item?.classification?.flat) ? item.classification.flat : [];
            flat.forEach(entry => {
                const key = assetSmartClassKey(entry);
                if(!key) return;
                const prev = groups.get(key) || {
                    id:assetSmartClassOptionId(entry),
                    dimension:String(entry.dimension || ''),
                    label:String(entry.label || entry.dimension || '分类'),
                    tag:String(entry.tag || ''),
                    count:0
                };
                prev.count += 1;
                groups.set(key, prev);
            });
        });
    });
    return [...groups.values()].sort((a, b) => {
        if(a.label !== b.label) return a.label.localeCompare(b.label, 'zh-CN');
        return b.count - a.count || a.tag.localeCompare(b.tag, 'zh-CN');
    });
}
function itemsForAssetSmartClass(optionId=''){
    const parsed = parseAssetSmartClassId(optionId);
    if(!parsed) return [];
    return assetCategories('image').flatMap(cat => cat.items || []).filter(item => {
        const flat = Array.isArray(item?.classification?.flat) ? item.classification.flat : [];
        return flat.some(entry => String(entry.dimension || '') === parsed.dimension && String(entry.tag || '') === parsed.tag);
    });
}
