function releaseAssetPanelMediaUrls(){
    assetPanelMediaUrls.forEach(url => URL.revokeObjectURL(url));
    assetPanelMediaUrls = [];
}
async function hydrateAssetPanelMedia(){
    const targets = [...(assetGrid?.querySelectorAll('[data-asset-media-url]') || [])];
    await Promise.all(targets.map(async media => {
        const source = media.dataset.assetMediaUrl || '';
        if(!source.startsWith('/api/storage-files/local/')) return;
        try {
            if(media.tagName === 'VIDEO'){
                media.setAttribute('data-url', source);
                media.addEventListener('loadedmetadata', () => {
                    if(Number.isFinite(media.duration) && media.duration > 0) media.currentTime = Math.min(.05, media.duration / 10);
                }, {once:true});
                if(!browserCanPlayHevc()){
                    media.src = playbackVideoUrl(source);
                    return;
                }
            }
            const response = await fetch(source, {cache:'no-store'});
            if(!response.ok) throw new Error(String(response.status));
            const objectUrl = URL.createObjectURL(await response.blob());
            if(!media.isConnected){ URL.revokeObjectURL(objectUrl); return; }
            assetPanelMediaUrls.push(objectUrl);
            media.src = objectUrl;
        } catch(e) {
            media.closest('.asset-item')?.classList.add('media-error');
        }
    }));
}
