function nodePromptCaptionHtml(node){
    if(!node) return '';
    const rawPrompt = String(
        node.promptDraftText ||
        node.prompt ||
        node.runPrompt ||
        node.text ||
        node.images?.find(img => img?.prompt || img?.meta?.prompt)?.prompt ||
        node.images?.find(img => img?.prompt || img?.meta?.prompt)?.meta?.prompt ||
        ''
    ).trim();
    const shotTag = node.shotTag || (rawPrompt.match(/(?:【镜头\s*\d+[a-zA-Z]?】|\[镜头\s*\d+[a-zA-Z]?\]|第\s*\d+\s*镜)/) || [])[0] || '';
    
    const settings = node.runSettings || {};
    const hasPrompt = Boolean(rawPrompt);
    const hasShot = Boolean(shotTag);
    const hasParams = Boolean(settings.ratio || settings.aspect_ratio || settings.duration || settings.resolution || settings.size || settings.model);
    
    if(!hasPrompt && !hasShot && !hasParams) return '';

    let promptSummary = rawPrompt;
    if(shotTag && promptSummary.startsWith(shotTag)){
        promptSummary = promptSummary.slice(shotTag.length).trim();
    }
    promptSummary = promptSummary.replace(/[\r\n\t]+/g, ' ').trim();

    const paramParts = [];
    if(shotTag) paramParts.push(shotTag);
    const ratio = settings.ratio || settings.aspect_ratio;
    if(ratio) paramParts.push(String(ratio).toUpperCase());
    if(settings.duration) paramParts.push(`${settings.duration}s`);
    const res = settings.resolution || settings.size;
    if(res) paramParts.push(String(res).toUpperCase());
    if(settings.model){
        let modelLabel = String(settings.model);
        if(modelLabel.includes('doubao') || modelLabel.includes('seedance')){
            if(modelLabel.includes('2-5') || modelLabel.includes('2.5')) modelLabel = 'Seedance 2.5';
            else if(modelLabel.includes('2-0') || modelLabel.includes('2.0')) modelLabel = 'Seedance 2.0';
            else modelLabel = 'Seedance';
        } else if(modelLabel.includes('gpt-image')){
            modelLabel = 'GPT-Image';
        }
        paramParts.push(modelLabel);
    }
    const paramsText = paramParts.join(' · ');

    return `<div class="node-caption-bar" title="${escapeHtml(rawPrompt || paramsText)}">
        ${promptSummary ? `<div class="node-caption-prompt"><svg class="node-caption-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"></path></svg><span>${escapeHtml(promptSummary)}</span></div>` : ''}
        ${paramsText ? `<div class="node-caption-params">${escapeHtml(paramsText)}</div>` : ''}
    </div>`;
}
function thumbDisplaySize(img, maxSize){
    const limit = Math.max(28, Math.round(Number(maxSize) || 96));
    const size = mediaLayoutSize(img);
    const w = size.width;
    const h = size.height;
    if(!(w > 0 && h > 0)) return {width:limit, height:limit};
    const fit = Math.min(limit / w, limit / h);
    return {
        width:Math.max(28, Math.round(w * fit)),
        height:Math.max(28, Math.round(h * fit))
    };
}
function applyThumbDisplaySizeToElement(itemEl, img, maxSize=0){
    if(!itemEl?.classList?.contains('thumb-item')) return;
    const limit = Math.max(
        28,
        Math.round(
            Number(maxSize || 0)
            || Number(itemEl.style.getPropertyValue('--thumb-size').replace('px', ''))
            || Math.max(itemEl.clientWidth || 0, itemEl.clientHeight || 0)
            || 96
        )
    );
    const size = thumbDisplaySize(img, limit);
    itemEl.style.setProperty('--thumb-w', `${size.width}px`);
    itemEl.style.setProperty('--thumb-h', `${size.height}px`);
}
