function bindVideoPlaybackFallback(root){
    const target = root || document;
    if(target === document){
        if(bindVideoPlaybackFallback._doc) return;
        bindVideoPlaybackFallback._doc = true;
    } else if(target.dataset){
        if(target.dataset.hevcFallbackBound === '1') return;
        target.dataset.hevcFallbackBound = '1';
    }
    target.addEventListener('error', event => {
        const video = event.target;
        if(!video || video.tagName !== 'VIDEO') return;
        if(video.dataset.hevcFallbackTried === '1') return;
        const original = video.getAttribute('data-url') || video.currentSrc || video.getAttribute('src') || '';
        const base = String(original || '').split('#')[0].split('?')[0];
        if(!isLocalCanvasMediaUrl(base)) return;
        if(String(video.getAttribute('src') || '').includes('/api/video-playback')) return;
        const hashIdx = String(original || '').indexOf('#');
        const hash = hashIdx >= 0 ? String(original).slice(hashIdx) : '';
        video.dataset.hevcFallbackTried = '1';
        video.src = `/api/video-playback?url=${encodeURIComponent(base)}${hash}`;
    }, true);
}
function bindImageProxyFallback(imgEl, itemOrUrl){
    if(!imgEl || imgEl.dataset.proxyFallbackBound === '1') return;
    imgEl.dataset.proxyFallbackBound = '1';
    imgEl.addEventListener('error', () => {
        if(imgEl.dataset.proxyFallbackTried === '1') return;
        const fallback = proxiedMediaUrl(itemOrUrl);
        if(!fallback || fallback === imgEl.getAttribute('src')) return;
        imgEl.dataset.proxyFallbackTried = '1';
        imgEl.src = fallback;
    });
}
