    const fallbackBase = cleanMediaBaseName(node?.title || 'image', 'image');
    const name = downloadNameForMediaItem(image, fallbackBase);
    const link = document.createElement('a');
    link.href = `/api/download-output?url=${encodeURIComponent(image.url)}&name=${encodeURIComponent(name)}`;
