function locateNodeOnCanvas(nodeId){
    if(!nodeId || !Array.isArray(nodes)) return false;
    const target = nodes.find(n => n.id === nodeId);
    if(!target) return false;
    selectedId = target.id;
    selectedIds = [target.id];
    const shellRect = shell?.getBoundingClientRect?.() || { width: window.innerWidth, height: window.innerHeight };
    const nodeW = target.w || 300;
    const nodeH = target.h || 200;
    const centerX = (target.x || 0) + nodeW / 2;
    const centerY = (target.y || 0) + nodeH / 2;
    const drawerOpen = document.getElementById('smartLogModal')?.classList.contains('open');
    const availableLeft = drawerOpen ? 458 : 0;
    const targetScreenX = availableLeft + (shellRect.width - availableLeft) / 2;
    const targetScreenY = shellRect.height / 2;
    viewport.x = targetScreenX - centerX * viewport.scale;
    viewport.y = targetScreenY - centerY * viewport.scale;
    applyViewport();
    render();
    return true;
}
window.locateNodeOnCanvas = locateNodeOnCanvas;

async function clearSmartCanvasLogs(){
    if(!confirm('确定要清空全部生成日志吗？此操作将同时清除历史记录。')) return;
    if(canvas){
        canvas.logs = [];
        canvas.deletedLogTaskIds = [];
        canvas.deletedLogTimestamps = [];
        scheduleSave?.();
    }
    try {
        await fetch('/api/history/clear', { method: 'POST' });
    } catch(e) {
        console.warn('[Log] Failed to clear backend history:', e);
    }
    renderSmartCanvasLog();
}
window.clearSmartCanvasLogs = clearSmartCanvasLogs;

async function deleteSmartCanvasLog(logId, taskId, rawTimestamp){
    if(!canvas) return;
    canvas.logs = canvas.logs || [];
    const target = canvas.logs.find(l => (logId && l.id === logId) || (taskId && l.request?.taskId === taskId) || (rawTimestamp && l.createdAt === rawTimestamp));
    canvas.logs = canvas.logs.filter(l => l !== target && (!logId || l.id !== logId));

    canvas.deletedLogTaskIds = canvas.deletedLogTaskIds || [];
    canvas.deletedLogTimestamps = canvas.deletedLogTimestamps || [];

    const tId = taskId || target?.request?.taskId || '';
    if(tId && !canvas.deletedLogTaskIds.includes(tId)){
        canvas.deletedLogTaskIds.push(tId);
        if(canvas.deletedLogTaskIds.length > 1000) canvas.deletedLogTaskIds.shift();
    }

    const ts = rawTimestamp || target?.createdAt || 0;
    if(ts && !canvas.deletedLogTimestamps.includes(ts)){
        canvas.deletedLogTimestamps.push(ts);
        if(canvas.deletedLogTimestamps.length > 1000) canvas.deletedLogTimestamps.shift();
    }

    scheduleSave?.();
    renderSmartCanvasLog();

    // 同步删除后端历史记录
    try {
        if(ts){
            const sec = ts > 1e11 ? ts / 1000 : ts;
            await fetch('/api/history/delete', {
                method: 'POST',
                headers: {'Content-Type': 'application/json'},
                body: JSON.stringify({ timestamp: sec })
            });
        }
    } catch(e) {
        console.warn('[Log] Failed to delete backend history record:', e);
    }
}
window.deleteSmartCanvasLog = deleteSmartCanvasLog;

let isSyncingBackendLogs = false;
async function syncBackendGenerationLogs(){
    if(isSyncingBackendLogs) return;
    isSyncingBackendLogs = true;
    const syncBtn = document.getElementById('smartLogSyncBtn');
    if(syncBtn) syncBtn.classList.add('syncing');
    try {
        const res = await fetch('/api/history');
        if(!res.ok) return;
        const backendRecords = await res.json();
        if(!Array.isArray(backendRecords) || !backendRecords.length) return;

        if(!canvas) return;
        canvas.logs = canvas.logs || [];

        const backendEntries = backendRecords.map(item => {
            const rawTs = Number(item.timestamp || 0);
            const createdAt = rawTs ? (rawTs > 1e11 ? rawTs : Math.round(rawTs * 1000)) : Date.now();

            const outputs = (item.image_items || item.images || []).map(img => {
                if(typeof img === 'string') return { url: img, kind: outputUrlLooksVideo(img) ? 'video' : 'image' };
                return {
                    url: img.url || img.path || img.src || '',
                    kind: img.kind || (outputUrlLooksVideo(img.url || '') ? 'video' : 'image'),
                    name: img.name || img.filename || '',
                    width: img.width || img.natural_w,
                    height: img.height || img.natural_h
                };
            }).filter(it => it && it.url);

            const platform = item.provider_name || item.provider_id || (item.type === 'comfy' ? 'ComfyUI' : (item.type || '生成任务'));
            const taskId = item.task_id || item.request_id || '';
            const size = item.params?.size || item.params?.requested_size || '';

            return {
                id: item.id || (taskId ? `task_${taskId}` : `hist_${createdAt}_${Math.random().toString(36).slice(2, 6)}`),
                createdAt: createdAt,
                status: (item.status === 'failed' || item.error) ? 'failed' : 'success',
                platform: platform,
                nodeId: '',
                nodeType: 'smart-image',
                model: item.model || item.params?.model || '',
                request: {
                    size: size,
                    taskId: taskId,
                    backend: platform
                },
                prompt: item.prompt || '',
                outputs: outputs,
                refs: (item.params?.reference_images || []).map(r => typeof r === 'string' ? {url: r} : r),
                runMs: Number(item.runMs || item.params?.runMs || 0),
                error: item.error ? String(item.error) : ''
            };
        });

        const deletedTaskIds = new Set(canvas.deletedLogTaskIds || []);
        const deletedTimestamps = new Set(canvas.deletedLogTimestamps || []);

        const existingTaskIds = new Set(canvas.logs.map(l => l.request?.taskId || l.id).filter(Boolean));
        const existingSignatures = new Set(canvas.logs.map(l => `${(l.prompt || '').trim()}_${Math.floor((l.createdAt || 0)/5000)}`));

        const newEntries = backendEntries.filter(entry => {
            const taskId = entry.request?.taskId;
            if(taskId && (existingTaskIds.has(taskId) || deletedTaskIds.has(taskId))) return false;
            const rawTs = entry.createdAt;
            if(rawTs && (deletedTimestamps.has(rawTs) || deletedTimestamps.has(Math.round(rawTs / 1000)))) return false;
            const sig = `${(entry.prompt || '').trim()}_${Math.floor(entry.createdAt/5000)}`;
            if(existingSignatures.has(sig)) return false;
            return true;
        });

        if(newEntries.length){
            canvas.logs = [...canvas.logs, ...newEntries]
                .sort((a, b) => (b.createdAt || 0) - (a.createdAt || 0))
                .slice(0, 500);
            renderSmartCanvasLog();
        }
    } catch(e) {
        console.warn('[Log] Failed to sync backend generation logs:', e);
    } finally {
        isSyncingBackendLogs = false;
        if(syncBtn) syncBtn.classList.remove('syncing');
    }
}
window.syncBackendGenerationLogs = syncBackendGenerationLogs;

function smartLogPreviewNode(url, kind='image'){
    openSmartLogLightbox(url, kind);
}

function formatSmartLogTimestamp(raw){
    if(!raw) return { time: '--:--', short: '--:--', full: '' };
    let n = Number(raw);
    let d;
    if(!isNaN(n) && n > 0){
        if(n < 1e11) n = Math.round(n * 1000);
        d = new Date(n);
    } else {
        d = new Date(raw);
    }
    if(isNaN(d.getTime())) return { time: '--:--', short: String(raw || ''), full: String(raw || '') };

    const now = new Date();
    const pad = v => String(v).padStart(2, '0');
    const hours = pad(d.getHours());
    const mins = pad(d.getMinutes());
    const secs = pad(d.getSeconds());
    const year = d.getFullYear();
    const month = pad(d.getMonth() + 1);
    const day = pad(d.getDate());

    const isToday = year === now.getFullYear() && d.getMonth() === now.getMonth() && d.getDate() === now.getDate();
    const isThisYear = year === now.getFullYear();

    const timeOnly = `${hours}:${mins}:${secs}`;
    const shortDate = isToday ? timeOnly : (isThisYear ? `${month}-${day} ${hours}:${mins}` : `${year}-${month}-${day} ${hours}:${mins}`);
    const full = `${year}-${month}-${day} ${timeOnly}`;

    return {
        time: timeOnly,
        short: shortDate,
        full: full,
        isToday
    };
}

function renderSmartCanvasLog(){
    bindSmartLogControls();
    const allLogs = canvas?.logs || [];
    const badge = document.getElementById('smartLogBadge');
    if(badge) badge.textContent = String(allLogs.length);

    const filterTabs = document.querySelectorAll('#smartLogModal [data-log-filter]');
    filterTabs.forEach(tab => {
        tab.classList.toggle('active', tab.dataset.logFilter === smartLogFilter);
        tab.onclick = e => {
            e.stopPropagation();
            smartLogFilter = tab.dataset.logFilter || 'all';
            renderSmartCanvasLog();
        };
    });

    let filtered = allLogs;
    if(smartLogFilter === 'success'){
        filtered = filtered.filter(l => l.status === 'success' && !l.error);
    } else if(smartLogFilter === 'error'){
        filtered = filtered.filter(l => l.status === 'failed' || !!l.error);
    } else if(smartLogFilter === 'image'){
        filtered = filtered.filter(l => (l.outputs || []).some(o => {
            const k = o.kind || (outputUrlLooksVideo(o.url || '') ? 'video' : 'image');
            return k === 'image';
        }));
    } else if(smartLogFilter === 'video'){
        filtered = filtered.filter(l => (l.outputs || []).some(o => {
            const k = o.kind || (outputUrlLooksVideo(o.url || '') ? 'video' : 'image');
            return k === 'video';
        }));
    }

    if(smartLogSearchQuery){
        const q = smartLogSearchQuery.toLowerCase();
        filtered = filtered.filter(l => {
            const prompt = (l.prompt || '').toLowerCase();
            const model = (l.model || '').toLowerCase();
            const platform = (l.platform || '').toLowerCase();
            const taskId = (l.request?.taskId || l.request?.task_id || l.id || '').toLowerCase();
            return prompt.includes(q) || model.includes(q) || platform.includes(q) || taskId.includes(q);
        });
    }

    const statsEl = document.getElementById('smartLogStats');
    if(statsEl){
        statsEl.textContent = `${window.StudioI18n?.lang() === 'en' ? 'Total' : '共'} ${filtered.length} ${window.StudioI18n?.lang() === 'en' ? 'items' : '条'}`;
    }

    const emptyContainer = document.getElementById('smartLogEmpty');
    if(!smartLogList) return;

    if(!filtered.length){
        smartLogList.innerHTML = '';
        if(emptyContainer){
            emptyContainer.hidden = false;
            if(!allLogs.length){
                emptyContainer.innerHTML = `
                    <div class="log-empty-icon"><i data-lucide="history"></i></div>
                    <div class="log-empty-title">${escapeHtml(tr('canvas.noLogs') || '暂无生成日志')}</div>
                    <div class="log-empty-desc">在画布中点击运行后，生成历史与提示词将自动记录在此</div>
                `;
            } else {
                emptyContainer.innerHTML = `
                    <div class="log-empty-icon"><i data-lucide="search-x"></i></div>
                    <div class="log-empty-title">未找到匹配的生成日志</div>
                    <div class="log-empty-desc">请尝试更换提示词关键词、模型名称或任务 ID</div>
                    <button class="log-empty-reset-btn" type="button" onclick="resetSmartLogSearchAndFilter()">重置搜索与筛选</button>
                `;
            }
        }
        refreshIcons();
        return;
    }

    if(emptyContainer) emptyContainer.hidden = true;

    smartLogList.innerHTML = filtered.map(log => {
        const isFailed = log.status === 'failed' || !!log.error;
        const outputs = (log.outputs || []).map(smartLogOutputItem).filter(item => item?.url);
        const thumbs = outputs.slice(0, 8).map(item => {
            const safe = escapeAttr(item.url);
            const isVideo = item.kind === 'video' || outputUrlLooksVideo(item.url);
            const kind = isVideo ? 'video' : 'image';
            const label = imageResolutionLabel(item);
            const badgeText = label || (isVideo ? 'VIDEO' : 'IMG');
            return `<div class="log-thumb-card" data-url="${safe}" data-kind="${kind}" title="点击全屏预览 (可直接拖入画布)" draggable="true" data-drag-url="${safe}">
                ${isVideo ? `<video src="${escapeAttr(playbackVideoUrl(item.url))}" data-url="${safe}" muted preload="metadata"></video><div class="log-thumb-video-icon"><div class="log-thumb-video-pill"><svg viewBox="0 0 24 24"><polygon points="5 3 19 12 5 21 5 3"/></svg></div></div>` : `<img src="${safe}" alt="output" loading="lazy">`}
                <div class="log-thumb-overlay"><i data-lucide="maximize-2"></i></div>
                <span class="log-thumb-badge">${escapeHtml(badgeText)}</span>
            </div>`;
        }).join('');

        const timeMeta = formatSmartLogTimestamp(log.createdAt);
        const runMsNum = Number(log.runMs || 0);
        const durationStr = (runMsNum > 0 && runMsNum < 86400000) ? formatRunDuration(runMsNum) : '';
        const durationHtml = durationStr ? `<span class="log-chip run-duration" title="运行耗时 ${escapeAttr(durationStr)}"><i data-lucide="timer"></i><span>${escapeHtml(durationStr)}</span></span>` : '';

        const req = log.request || {};
        const taskId = req.task_id || req.taskId || req.prompt_id || req.promptId || '';
        const backend = req.workflow_json || req.workflow || req.provider_id || req.providerId || req.backend || '';
        const sizeSummary = smartLogSizeSummary(log, outputs);
        const nodeExists = log.nodeId && Array.isArray(nodes) && nodes.some(n => n.id === log.nodeId);

        const metaParts = [
            taskId ? `ID: ${taskId.slice(0, 14)}` : '',
            timeMeta.full ? timeMeta.full : '',
            sizeSummary,
            outputs.length ? `输出: ${outputs.length}` : '',
            backend
        ].filter(Boolean);

        return `<div class="log-card ${isFailed ? 'failed' : ''}">
            <div class="log-card-header">
                <div class="log-card-badges">
                    <span class="log-status-badge ${isFailed ? 'status-failed' : 'status-ok'}">
                        <span class="log-status-dot"></span>
                        <span>${escapeHtml(isFailed ? (tr('canvas.failed') || '失败') : (tr('canvas.success') || '成功'))}</span>
                    </span>
                    ${log.platform ? `<span class="log-chip">${escapeHtml(log.platform)}</span>` : ''}
                    ${log.model ? `<span class="log-chip model-name" title="${escapeAttr(log.model)}">${escapeHtml(log.model)}</span>` : ''}
                    ${durationHtml}
                </div>
                <div class="log-card-actions">
                    ${nodeExists ? `<button class="log-icon-btn" type="button" data-locate-node="${escapeAttr(log.nodeId)}" title="在画布中定位该节点"><i data-lucide="crosshair"></i></button>` : ''}
                    ${log.prompt ? `<button class="log-icon-btn" type="button" data-copy-prompt="${escapeAttr(log.prompt)}" title="复制提示词"><i data-lucide="copy"></i></button>` : ''}
                    <button class="log-icon-btn log-delete-btn danger" type="button" data-delete-log="${escapeAttr(log.id || '')}" data-task-id="${escapeAttr(taskId || '')}" data-timestamp="${escapeAttr(String(log.createdAt || ''))}" title="删除此条日志"><i data-lucide="trash-2"></i></button>
                    <span class="log-time-text" title="${escapeAttr(timeMeta.full)}">${escapeHtml(timeMeta.short)}</span>
                </div>
            </div>
            ${log.prompt ? `
            <div class="log-prompt-box" data-prompt-box="1" title="点击展开/折叠完整提示词">
                <div class="log-prompt-text">${escapeHtml(log.prompt)}</div>
            </div>` : ''}
            ${log.error ? `
            <div class="log-error-box">
                <i data-lucide="alert-circle" class="log-error-icon"></i>
                <div class="log-error-content">
                    <div class="log-error-title">生成异常</div>
                    <div class="log-error-message">${escapeHtml(log.error)}</div>
                </div>
                <button class="log-icon-btn" type="button" data-copy-error="${escapeAttr(log.error)}" title="复制报错信息"><i data-lucide="copy"></i></button>
            </div>` : ''}
            ${thumbs ? `<div class="log-outputs-strip">${thumbs}</div>` : ''}
            ${metaParts.length ? `
            <div class="log-meta-footer">
                <div class="log-meta-footer-left">${metaParts.map(p => `<span>${escapeHtml(p)}</span>`).join('<span>·</span>')}</div>
            </div>` : ''}
        </div>`;
    }).join('');

    bindSmartPreviewImageFallbacks(smartLogList);

    // 绑定缩略图点击打开 Lightbox 与拖拽到画布
    smartLogList.querySelectorAll('.log-thumb-card').forEach(el => {
        el.onclick = e => {
            if(document.body.classList.contains('in-video-crop') && window.__activeVideoCropNodeId === id){
                e.stopPropagation();
                return;
            }
            e.stopPropagation();
            smartLogPreviewNode(el.dataset.url, el.dataset.kind || 'image');
        };
        el.addEventListener('dragstart', e => {
            e.stopPropagation();
            e.dataTransfer.effectAllowed = 'copy';
            const asset = {
                url: el.dataset.url,
                kind: el.dataset.kind || 'image',
                name: 'log_output'
            };
            e.dataTransfer.setData('application/x-smart-asset', JSON.stringify(asset));
            e.dataTransfer.setData('text/plain', el.dataset.url || '');
        });
    });

    // 绑定提示词展开折叠
    smartLogList.querySelectorAll('[data-prompt-box]').forEach(box => {
        box.onclick = e => {
            e.stopPropagation();
            box.classList.toggle('expanded');
        };
    });

    // 绑定复制功能（带视觉提示）
    const bindCopy = (selector, key) => {
        smartLogList.querySelectorAll(selector).forEach(btn => {
            btn.onclick = async e => {
                e.stopPropagation();
                const text = btn.getAttribute(`data-${key}`) || '';
                const copied = await copyTextToClipboard(text);
                const origTitle = btn.title;
                btn.title = copied ? (tr('canvas.copied') || '已复制') : (tr('canvas.copyFailed') || '复制失败');
                const origHtml = btn.innerHTML;
                btn.innerHTML = `<i data-lucide="${copied ? 'check' : 'x'}"></i>`;
                refreshIcons();
                setTimeout(() => {
                    btn.innerHTML = origHtml;
                    btn.title = origTitle;
                    refreshIcons();
                }, 1200);
            };
        });
    };
    bindCopy('[data-copy-prompt]', 'copy-prompt');
    bindCopy('[data-copy-error]', 'copy-error');

    // 绑定节点定位
    smartLogList.querySelectorAll('[data-locate-node]').forEach(btn => {
        btn.onclick = e => {
            e.stopPropagation();
            const nodeId = btn.getAttribute('data-locate-node');
            if(nodeId){
                locateNodeOnCanvas(nodeId);
            }
        };
    });

    // 绑定单条日志删除
    smartLogList.querySelectorAll('[data-delete-log]').forEach(btn => {
        btn.onclick = e => {
            e.stopPropagation();
            const logId = btn.getAttribute('data-delete-log');
            const taskId = btn.getAttribute('data-task-id');
            const ts = Number(btn.getAttribute('data-timestamp') || 0);
            deleteSmartCanvasLog(logId, taskId, ts);
        };
    });

    refreshIcons();
}
function closeSmartCanvasLog(){
    SmartPanelManager.close('log');
}
function closeSmartCanvasShortcuts(){
    SmartPanelManager.close('shortcuts');
}
