    const x = viewport.x + (rect.x + rect.width) * scale + 16;
    const y = viewport.y + rect.y * scale;
    panel.style.left = `${Math.round(x)}px`;
    panel.style.top = `${Math.round(y)}px`;
    panel.style.right = 'auto';
    panel.style.bottom = 'auto';
