async function cancelSmartCanvasBatch(batchId){
    if(!batchId) return;
    const response = await fetch(`/api/canvas-image-batches/${encodeURIComponent(batchId)}/cancel`, {method:'POST'});
    if(!response.ok) throw new Error(await response.text());
    return response.json();
}
function smartCanvasTaskResult(task){
    const rawResult = task?.result || {};
    const isVideoTask = task?.type === 'canvas-video' || task?.kind === 'video';
    if(isVideoTask){
        if(Array.isArray(rawResult)) return {videos:rawResult};
        if(rawResult && typeof rawResult === 'object') return {...rawResult};
        return {videos:[rawResult]};
    }
    if(Array.isArray(rawResult)) return {images:rawResult};
    if(rawResult && typeof rawResult === 'object') return {...rawResult};
    return {images:[rawResult]};
}
async function pollSmartCanvasBatch(node){
    const batchId = String(node?.batchId || '');
    if(!node || !batchId) return {failures:[]};
    const pollKey = `batch:${batchId}`;
    if(activeSmartTaskPolls.has(pollKey)) return activeSmartTaskPolls.get(pollKey);
    const promise = (async () => {
        const failures = [];
        let consecutiveFetchErrors = 0;
        for(let i = 0; i < 900; i++){
            if(smartPendingTasks(node).some(task => task.cancelRequested)) await cancelSmartCanvasBatch(batchId);
            await new Promise(resolve => setTimeout(resolve, 2000));
            let batch;
            try {
                batch = await fetch(`/api/canvas-image-batches/${encodeURIComponent(batchId)}`).then(async response => {
                    if(!response.ok) throw new Error(await response.text());
                    return response.json();
                });
                consecutiveFetchErrors = 0;
            } catch(fetchErr){
                consecutiveFetchErrors++;
                if(consecutiveFetchErrors >= 6){
                    throw fetchErr;
                }
                continue;
            }
            for(const remoteTask of Array.isArray(batch.tasks) ? batch.tasks : []){
                const taskId = String(remoteTask?.task_id || '');
                const localTask = smartPendingTaskById(node, taskId);
                if(!localTask) continue;
                const status = String(remoteTask.status || '').toLowerCase();
                patchSmartPendingTask(node, taskId, {
                    status,
                    progressText:remoteTask.progress_text || smartTaskStatusLabel(status)
                });
                if(status === 'succeeded'){
                    finalizeSmartPendingTask(node, taskId, resultMediaUrls(smartCanvasTaskResult(remoteTask)), localTask.kind || 'image');
                } else if(status === 'cancelled'){
                    node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== taskId);
                    node.pending = Math.max(0, Number(node.pending || 0) - 1);
                } else if(status === 'failed'){
                    const recoverTaskId = remoteTask.upstream_task_id || extractUpstreamTaskId(remoteTask.error || '');
                    if(recoverTaskId){
                        Object.assign(localTask, {failed:true, querying:false, recoverTaskId, providerId:remoteTask.provider_id || localTask.providerId, error:remoteTask.error || tr('smart.errRunFailed')});
                    } else {
                        node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== taskId);
                        node.pending = Math.max(0, Number(node.pending || 0) - 1);
                        failures.push(new Error(remoteTask.error || tr('smart.errRunFailed')));
                    }
                }
            }
            const remaining = smartPendingTasks(node);
            node.pending = remaining.length;
            if(!remaining.length){
                delete node.pendingTasks;
                delete node.batchId;
                node.running = false;
                node.queued = false;
            }
            render();
            scheduleSave();
            const terminal = ['succeeded','failed','partial','cancelled'].includes(String(batch.status || '').toLowerCase());
            if(terminal){
                const recoverable = smartPendingTasks(node).filter(task => task.failed && task.recoverTaskId);
                node.pending = recoverable.length;
                node.running = false;
                node.queued = false;
                if(!recoverable.length){
                    delete node.pendingTasks;
                    delete node.batchId;
                }
                if((node.images || []).length){
                    delete node.runStartedAt;
                    delete node.runFinishedAt;
                    delete node.runElapsedMs;
                    node.runTimerHidden = true;
                    node.title = node.images.length > 1 ? 'Group' : 'Image';
                    if(node.images.length > 1 && (!Number.isFinite(Number(node.scale)) || Number(node.scale) === MEDIA_NODE_DEFAULT_SCALE || Number(node.scale) === MEDIA_GROUP_PREVIOUS_DEFAULT_SCALE)) node.scale = MEDIA_GROUP_DEFAULT_SCALE;
                    else node.scale = mediaNodeDefaultScale(node);
                    if(!node.gridSplitChild && !node.isCroppedVideo){ delete node.w; delete node.h; }
                }
                render();
                scheduleSave();
                return {failures};
            }
        }
        throw new Error(tr('smart.errRunTimeout'));
    })();
    activeSmartTaskPolls.set(pollKey, promise);
    try {
        return await promise;
    } finally {
        activeSmartTaskPolls.delete(pollKey);
    }
}
function smartBusyTaskStatusHtml(node, layout){
    const isVideo = isSmartVideoNode(node) || node?.outputKind === 'video' || (node?.pendingTasks && node.pendingTasks.some(t => t?.kind === 'video'));
    const firstTask = (node?.pendingTasks || [])[0];
    const statusText = firstTask?.progressText || (isVideo ? '视频生成中…' : '图片生成中…');
    return `<div class="pending-task-cell pending-task-orbit-host" style="width:${layout.width}px;height:${layout.height}px">
        <div class="pending-task-orbit" role="status" aria-label="${escapeAttr(statusText)}">
            <span></span><span></span><span></span><span></span>
        </div>
        <div class="pending-orbit-footer">
            <div class="pending-orbit-label">${escapeHtml(statusText)}</div>
            <button class="pending-orbit-cancel" type="button" data-node-busy-reset="${escapeAttr(node.id)}" title="取消并重置节点状态">取消</button>
        </div>
    </div>`;
}
async function querySmartImageTaskNow(nodeId, taskId){
    const node = nodes.find(n => n.id === nodeId);
    const task = smartPendingTaskById(node, taskId);
    if(!node || !task){ toast('找不到可查询的任务'); return; }
    if(task.querying) return;
    task.querying = true;
    render();
    try {
        const recoverId = task.recoverTaskId || task.taskId;
        const result = await pollSmartCanvasTask(recoverId, {nodeId:node.id, localTaskId:task.taskId});
        finalizeSmartPendingTask(node, task.taskId, resultMediaUrls(result), task.kind || 'image');
        toast('已取回生成结果');
        render();
        scheduleSave();
    } catch(e) {
        task.querying = false;
        if(e && e.imageTaskRecover && e.recoverTaskId){
            task.failed = true;
            task.recoverTaskId = e.recoverTaskId;
            task.error = e.message || tr('smart.errRunFailed');
            toast('仍可稍后查询，任务未丢失');
        } else {
            toast((e?.message || tr('smart.errRunFailed')).slice(0, 160));
        }
        render();
        scheduleSave();
    }
}
async function cancelSmartImageTaskNow(nodeId, taskId, kind='image'){
    const node = nodes.find(n => n.id === nodeId);
    const task = smartPendingTaskById(node, taskId);
    if(!node || !task){ toast('找不到可取消的任务'); return; }
    if(task.cancelling) return;
    task.cancelling = true;
    task.cancelRequested = true;
    task.progressText = '取消中…';
    task.status = task.status || 'running';
    render();
    try {
        if(node.batchId && (kind || task.kind || 'image') === 'image') await cancelSmartCanvasBatch(node.batchId);
        else await cancelSmartCanvasTask(taskId, kind || task.kind || 'image');
        // 让轮询侧感知取消；若已无轮询则本地收尾
        if(!activeSmartTaskPolls.has(taskId)){
            node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== taskId);
            node.pending = Math.max(0, Number(node.pending || 0) - 1);
            if(!node.pending && smartPendingTasks(node).length === 0){
                delete node.pendingTasks;
                delete node.batchId;
                node.running = false;
                node.queued = false;
            }
            toast('已取消任务');
        } else {
            toast('已请求取消');
        }
    } catch(e) {
        task.cancelling = false;
        task.cancelRequested = false;
        toast((e?.message || '取消失败，请重试').slice(0, 160));
    }
    render();
    scheduleSave();
}
async function resetSmartNodeBusyNow(nodeId){
    const node = nodes.find(n => n.id === nodeId);
    if(!node) return;
    if(activeSmartVideoControllers.has(nodeId)){
        try {
            activeSmartVideoControllers.get(nodeId).abort();
        } catch(_) {}
        activeSmartVideoControllers.delete(nodeId);
    }
    if(node.batchId){
        cancelSmartCanvasBatch(node.batchId).catch(() => {});
    }
    const tasks = smartPendingTasks(node);
    for(const task of tasks){
        task.cancelRequested = true;
        cancelSmartCanvasTask(task.taskId, task.kind || 'image').catch(() => {});
    }
    clearSmartNodeBusyState(node);
    clearNodeRunningState(node);
    syncRunButtonState();
    toast('已取消并重置节点状态');
    render();
    scheduleSave();
}
async function pollSmartCanvasTask(taskId, options={}){
    if(!taskId) throw new Error(tr('smart.errRunFailed'));
    if(activeSmartTaskPolls.has(taskId) && !options.forceNew) return activeSmartTaskPolls.get(taskId);
    const nodeId = options.nodeId || '';
    const localTaskId = options.localTaskId || taskId;
    const promise = (async () => {
        let consecutiveFetchErrors = 0;
        for(let i = 0; i < 900; i++){
            const liveNode = nodeId ? nodes.find(n => n.id === nodeId) : null;
            const liveTask = liveNode ? smartPendingTaskById(liveNode, localTaskId) : null;
            if(liveTask?.cancelRequested){
                if(liveNode?.batchId && (liveTask.kind || 'image') === 'image') await cancelSmartCanvasBatch(liveNode.batchId);
                else await cancelSmartCanvasTask(taskId, liveTask.kind || 'image');
                const cancelledErr = new Error('已取消');
                cancelledErr.cancelled = true;
                throw cancelledErr;
            }
            await new Promise(resolve => setTimeout(resolve, 2000));
            let task;
            try {
                task = await fetch(`/api/canvas-image-tasks/${encodeURIComponent(taskId)}`).then(async r => {
                    if(!r.ok) throw new Error(await r.text());
                    return r.json();
                });
                consecutiveFetchErrors = 0;
            } catch(fetchErr){
                consecutiveFetchErrors++;
                if(consecutiveFetchErrors >= 6){
                    throw fetchErr;
                }
                continue;
            }
            const status = String(task.status || '').toLowerCase();
            const progressText = task.progress_text || smartTaskStatusLabel(status);
            if(liveNode){
                patchSmartPendingTask(liveNode, localTaskId, {
                    status,
                    progressText,
                    progress: typeof task.progress === 'number' ? task.progress : liveTask?.progress
                });
                if(i === 0 || i % 2 === 0) render();
            }
            if(status === 'succeeded'){
                const rawResult = task.result || {};
                const startedAt = Number(task.started_at || 0);
                const finishedAt = Number(task.finished_at || task.completed_at || 0);
                const elapsedMs = Number(task.elapsed_ms || task.duration_ms || (startedAt && finishedAt ? (finishedAt - startedAt) * 1000 : 0));
                const meta = {
                    started_at:startedAt || undefined,
                    finished_at:finishedAt || undefined,
                    completed_at:Number(task.completed_at || finishedAt || 0) || undefined,
                    elapsed_ms:elapsedMs > 0 ? elapsedMs : undefined,
                    duration_ms:elapsedMs > 0 ? elapsedMs : undefined
                };
                if(Array.isArray(rawResult)) return {images:rawResult, __task_meta:meta};
                if(rawResult && typeof rawResult === 'object') return {...rawResult, __task_meta:{...(rawResult.__task_meta || {}), ...meta}};
                return {images:[rawResult], __task_meta:meta};
            }
            if(status === 'cancelled'){
                const cancelledErr = new Error('已取消');
                cancelledErr.cancelled = true;
                throw cancelledErr;
            }
            if(status === 'failed'){
                const recoverTaskId = task.upstream_task_id || extractUpstreamTaskId(task.error || '');
                if(recoverTaskId) throw new ImageTaskRecoverSignal({taskId, recoverTaskId, providerId:task.provider_id, kind:'image', message:task.error || tr('smart.errRunFailed')});
                throw new Error(task.error || tr('smart.errRunFailed'));
            }
        }
        throw new Error(tr('smart.errRunTimeout'));
    })();
    activeSmartTaskPolls.set(taskId, promise);
    try {
        return await promise;
    } finally {
        activeSmartTaskPolls.delete(taskId);
    }
}
function finalizeSmartPendingTask(node, taskId, images, kind='image'){
    if(!node || !taskId) return;
    node.pendingTasks = smartPendingTasks(node).filter(task => task.taskId !== taskId);
    node.pending = Math.max(0, Number(node.pending || 0) - 1);
    const ext = kind === 'video' ? 'mp4' : kind === 'audio' ? 'mp3' : kind === 'text' ? 'txt' : 'png';
    const mediaItems = resultMediaUrls(images);
    const existing = cleanHistoryImages(node.images || []);
    const seen = new Set(existing.map(img => `${img.kind || ''}|${img.url || ''}`));
    const additions = cleanHistoryImages((mediaItems || []).map((item, i) => {
        const url = typeof item === 'string' ? item : item?.url || '';
        const itemKind = (typeof item === 'object' && item.kind) || kind;
        return stripImageGenerationMeta(copyMediaSizeFields(item, {url, name:(typeof item === 'object' && item.name) || `output-${i + 1}.${ext}`, kind:itemKind, generatedResult:true}));
    }).filter(item => item.url)).filter(item => {
        const key = `${item.kind || ''}|${item.url || ''}`;
        if(seen.has(key)) return false;
        seen.add(key);
        return true;
    });
    node.images = [...existing, ...additions];
    if(additions.length) node.outputKind = kind;
    if(!node.pending && smartPendingTasks(node).length === 0){
        delete node.pendingTasks;
        delete node.batchId;
        delete node.runStartedAt;
        delete node.runFinishedAt;
        delete node.runElapsedMs;
        node.runTimerHidden = true;
        node.running = false;
        node.title = node.images.length > 1 ? (kind === 'video' ? 'Videos' : kind === 'audio' ? 'Audios' : kind === 'text' ? 'Texts' : 'Group') : (kind === 'video' ? 'Video' : kind === 'audio' ? 'Audio' : kind === 'text' ? 'Text' : 'Image');
        if(node.images.length > 1 && (!Number.isFinite(Number(node.scale)) || Number(node.scale) === MEDIA_NODE_DEFAULT_SCALE || Number(node.scale) === MEDIA_GROUP_PREVIOUS_DEFAULT_SCALE)) node.scale = MEDIA_GROUP_DEFAULT_SCALE;
        else node.scale = mediaNodeDefaultScale(node);
        if(!node.gridSplitChild && !node.isCroppedVideo){ delete node.w; delete node.h; }
    }
}
async function resumeSmartPendingNode(node, logContext={}){
    const tasks = smartPendingTasks(node);
    if(!node || !tasks.length) return;
    const logTaskFailure = (message, task) => {
        if(!logContext?.run || !message) return;
        const runMs = Math.max(0, nowMs() - Number(logContext.runLogStart || nowMs()));
        addSmartGenerationLog({
            run:logContext.run,
            outputs:[],
            runMs,
            error:message
        });
    };
    node.pending = Math.max(tasks.length, Number(node.pending || 0) || tasks.length);
    node.running = false;
    render();
    const failures = [];
    if(node.batchId){
        try {
            const batchResult = await pollSmartCanvasBatch(node);
            failures.push(...(batchResult?.failures || []));
            failures.forEach(error => logTaskFailure(error.message || tr('smart.errRunFailed')));
            if(failures.length) toast((failures[0].message || tr('smart.errRunFailed')).slice(0, 160));
            if(failures.length && !(node.images || []).length) throw failures[0];
            return;
        } catch(error) {
            if(error && typeof error === 'object') error.smartGenerationLogged = true;
            throw error;
        }
    }
    await Promise.all(tasks.map(async task => {
        if(task.failed && task.recoverTaskId) return;
        try {
            const result = await pollSmartCanvasTask(task.taskId, {nodeId:node.id, localTaskId:task.taskId});
            finalizeSmartPendingTask(node, task.taskId, resultMediaUrls(result), task.kind || 'image');
            render();
            scheduleSave();
        } catch(e) {
            if(e && e.cancelled){
                node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== task.taskId);
                node.pending = Math.max(0, Number(node.pending || 0) - 1);
                if(!node.pending && smartPendingTasks(node).length === 0){
                    delete node.pendingTasks;
                    node.running = false;
                    node.queued = false;
                }
                toast('已取消任务');
                render();
                scheduleSave();
                return;
            }
            if(e && e.imageTaskRecover && e.recoverTaskId){
                task.failed = true;
                task.querying = false;
                task.recoverTaskId = e.recoverTaskId;
                task.providerId = e.providerId || task.providerId || providerIdForSmartTask(node, task);
                task.error = e.message || tr('smart.errRunFailed');
                node.running = false;
                node.pending = Math.max(1, smartPendingTasks(node).length);
                logTaskFailure(task.error, task);
                toast('任务未丢失，可稍后手动查询结果');
                render();
                scheduleSave();
                return;
            }
            node.pendingTasks = smartPendingTasks(node).filter(item => item.taskId !== task.taskId);
            node.pending = Math.max(0, Number(node.pending || 0) - 1);
            if(!node.pending && smartPendingTasks(node).length === 0){
                delete node.pendingTasks;
                node.running = false;
                if(!(node.images || []).length){
                    if(!node.gridSplitChild && !node.isCroppedVideo){ delete node.w; delete node.h; }
                }
            }
            failures.push(e);
            logTaskFailure(e.message || tr('smart.errRunFailed'), task);
            if(e && typeof e === 'object') e.smartGenerationLogged = true;
            toast((e.message || tr('smart.errRunFailed')).slice(0, 160));
            render();
            scheduleSave();
        }
    }));
    if(failures.length && !(node.images || []).length){
        throw failures[0];
    }
}
function resumeSmartPendingTasks(){
    nodes.forEach(node => {
        const pendingList = smartPendingTasks(node);
        if(pendingList.length){
            resumeSmartPendingNode(node);
        } else if(node.pending || node.running || node.queued){
            clearSmartNodeBusyState(node);
        }
    });
}
function updateSelectionBox(event){
    if(!selectionState) return;
    const clientX = typeof event?.clientX === 'number' ? event.clientX : (event?.x ?? 0);
    const clientY = typeof event?.clientY === 'number' ? event.clientY : (event?.y ?? 0);
    const shellRect = shell ? shell.getBoundingClientRect() : {left: 0, top: 0};
    const startScreen = selectionState.startWorld ? worldToScreen(selectionState.startWorld) : selectionState.startScreen;
    const startX = startScreen.x - shellRect.left;
    const startY = startScreen.y - shellRect.top;
    const currentX = clientX - shellRect.left;
    const currentY = clientY - shellRect.top;
    const rect = window.SmartCanvasInteraction.selectionRect(
        {x:startX, y:startY}, {x:currentX, y:currentY}
    );
    selectionBox.style.display = 'block';
    selectionBox.style.left = `${rect.x}px`;
    selectionBox.style.top = `${rect.y}px`;
    selectionBox.style.width = `${rect.width}px`;
    selectionBox.style.height = `${rect.height}px`;
}
function finishSelection(event){
    if(!selectionState) return;
    const a = selectionState.startWorld;
    const b = screenToWorld(event);
    const bounds = window.SmartCanvasInteraction.selectionRect(a, b);
    const clientX = typeof event?.clientX === 'number' ? event.clientX : (event?.x ?? 0);
    const clientY = typeof event?.clientY === 'number' ? event.clientY : (event?.y ?? 0);
    const isTinyDrag = Math.hypot(clientX - selectionState.startScreen.x, clientY - selectionState.startScreen.y) < 4;

    if(isTinyDrag){
        if(!event?.shiftKey && !event?.ctrlKey && !event?.metaKey){
            selectedIds = [];
            selectedId = '';
            selectedImage = {nodeId:'', index:-1};
        }
    } else {
        const hitIds = window.SmartCanvasInteraction.nodeIdsInSelection(nodes, bounds, nodeRect);

        if(event?.shiftKey || event?.ctrlKey || event?.metaKey){
            selectedIds = Array.from(new Set([...selectedIds, ...hitIds]));
        } else {
            selectedIds = hitIds;
        }
        selectedId = selectedIds.length === 1 ? selectedIds[0] : '';
        selectedImage = {nodeId:'', index:-1};
    }

    if(canvasSelectionToolActive){
        canvasSelectionToolActive = false;
    }

    selectionState = null;
    selectionJustFinished = true;
    selectionBox.style.display = 'none';

    updateSelectionToolUi();
    syncSelectionUi();
    updateComposer();
    render();
    setTimeout(() => { selectionJustFinished = false; }, 0);
}
function updateSelectionToolUi(){
    const hasMultiple = selectedNodeIds().length > 1;
    if(selectionToolActions){
        selectionToolActions.hidden = !(canvasSelectionToolActive || hasMultiple);
    }
    canvasSelectionToolBtn?.classList.toggle('active', canvasSelectionToolActive);
    shell?.classList.toggle('selection-tool-active', canvasSelectionToolActive);
}
function toggleCanvasSelectionTool(event){
    event?.preventDefault(); event?.stopPropagation();
    canvasSelectionToolActive = !canvasSelectionToolActive;
    selectionState = null;
    selectionBox.style.display = 'none';
    if(!canvasSelectionToolActive && !selectedNodeIds().length){
        clearSelection();
        render();
    }
    updateSelectionToolUi();
}
function cancelCanvasSelection(){
    canvasSelectionToolActive = false;
    selectionState = null;
    selectionBox.style.display = 'none';
    clearSelection();
    updateSelectionToolUi();
    syncSelectionUi();
    render();
}
function createSelectionDownstreamNode(){
    const ids = selectedNodeIds();
    const selected = ids.map(id => nodes.find(n => n.id === id)).filter(Boolean);
    if(selected.length < 1){
        if(typeof showToast === 'function') showToast('请先框选至少一个节点');
        return;
    }
    const rects = selected.map(nodeRect);
    const maxX = Math.max(...rects.map(r => r.x + r.width));
    const centerY = (Math.min(...rects.map(r => r.y)) + Math.max(...rects.map(r => r.y + r.height))) / 2;
    pushUndo();
    const downstream = createImageGenNodeAt({x:maxX + 260, y:centerY}, [], {select:false, skipUndo:true});
    downstream.title = '组合下游';
    selected.forEach(node => connectInputNode(node.id, downstream.id));
    selectedIds = [downstream.id];
    selectedId = downstream.id;
    scheduleSave();
    render();
    if(typeof showToast === 'function') showToast('已生成组合下游节点');
}

let pendingSaveWorkflowPayload = null;

function closeSaveWorkflowModal(){
    const modal = document.getElementById('saveWorkflowModal');
    if(!modal) return;
    modal.classList.remove('open');
    modal.hidden = true;
    pendingSaveWorkflowPayload = null;
}
window.closeSaveWorkflowModal = closeSaveWorkflowModal;

function openSaveWorkflowModalForSelection(){
    if(!canvas) {
        toast('请先打开画布');
        return;
    }
    const ids = selectedNodeIds();
    const selNodes = ids.map(id => nodes.find(n => n.id === id)).filter(Boolean);
    if(selNodes.length < 1){
        toast('请先框选至少一个节点');
        return;
    }
    const payload = selectedSmartWorkflowPayload();
    if(!payload.nodes || !payload.nodes.length){
        toast('未找到可保存的节点');
        return;
    }
    pendingSaveWorkflowPayload = payload;

    const modal = document.getElementById('saveWorkflowModal');
    const input = document.getElementById('saveWorkflowNameInput');
    const subTitle = document.getElementById('saveWorkflowSubTitle');
    if(!modal || !input) return;

    const nodeCount = payload.nodes.length;
    const connCount = (payload.connections || []).length;
    if(subTitle){
        subTitle.textContent = `包含选中的 ${nodeCount} 个节点与 ${connCount} 条连接线`;
    }

    // 智能默认名称：优先使用首个带自定义标题节点的名称，否则使用日期时间
    const now = new Date();
    const pad = n => String(n).padStart(2, '0');
    const dateStr = `${pad(now.getMonth()+1)}-${pad(now.getDate())}_${pad(now.getHours())}:${pad(now.getMinutes())}`;
    const primaryTitle = selNodes.find(n => n.title && n.title !== 'Image' && n.title !== 'Video' && n.title !== 'Group')?.title || '';
    const defaultName = primaryTitle ? `${primaryTitle}-工作流` : `工作流-${dateStr}`;

    input.value = defaultName;
    modal.hidden = false;
    modal.classList.add('open');
    if(window.lucide && typeof lucide.createIcons === 'function'){
        lucide.createIcons({ root: modal });
    }

    if(!input.dataset.boundKeydown){
        input.dataset.boundKeydown = '1';
        input.addEventListener('keydown', e => {
            if(e.key === 'Enter'){
                e.preventDefault();
                e.stopPropagation();
                confirmSaveWorkflowFromSelection();
            } else if(e.key === 'Escape'){
                e.preventDefault();
                e.stopPropagation();
                closeSaveWorkflowModal();
            }
        });
    }

    setTimeout(() => {
        input.focus();
        input.select();
    }, 50);
}
window.openSaveWorkflowModalForSelection = openSaveWorkflowModalForSelection;

async function confirmSaveWorkflowFromSelection(){
    if(!pendingSaveWorkflowPayload){
        closeSaveWorkflowModal();
        return;
    }
    const input = document.getElementById('saveWorkflowNameInput');
    const name = (input?.value || '').trim() || '未命名工作流';
    const payload = pendingSaveWorkflowPayload;

    try {
        toast('正在保存工作流模板...');
        const res = await fetch('/api/canvas-workflows', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                name: name,
                nodes: payload.nodes,
                connections: payload.connections || [],
                resources: []
            })
        });
        if(!res.ok) throw new Error(await responseErrorMessage(res, '保存工作流失败'));

        closeSaveWorkflowModal();
        const connCount = (payload.connections || []).length;
        toast(`已保存工作流“${name}”（含 ${payload.nodes.length} 个节点，${connCount} 条连线）`);
        try {
            loadSavedSmartWorkflows?.();
        } catch(_) {}
    } catch(err) {
        toast(err.message || '保存工作流失败');
    }
}
window.confirmSaveWorkflowFromSelection = confirmSaveWorkflowFromSelection;

// 把一组节点按 direction 在给定左上角铺开。多选“排列”与分组“整理分组”共用这一套几何，
// 保证两种入口得到的排布结果完全一致。
function layoutNodesInBox(list, minX, minY, direction){
    const gap = 36;
    if(direction === 'horizontal'){
        let currentX = minX;
        list.forEach(n => {
            n.x = currentX;
            n.y = minY;
            currentX += nodeRect(n).width + gap;
        });
        return;
    }
    if(direction === 'vertical'){
        let currentY = minY;
        list.forEach(n => {
            n.x = minX;
            n.y = currentY;
            currentY += nodeRect(n).height + gap;
        });
        return;
    }
    const cols = Math.max(2, Math.ceil(Math.sqrt(list.length)));
    let currentX = minX;
    let currentY = minY;
    let rowMaxHeight = 0;
    list.forEach((n, i) => {
        const r = nodeRect(n);
        if(i > 0 && i % cols === 0){
            currentX = minX;
            currentY += rowMaxHeight + gap;
            rowMaxHeight = 0;
        }
        n.x = currentX;
        n.y = currentY;
        currentX += r.width + gap;
        rowMaxHeight = Math.max(rowMaxHeight, r.height);
    });
}
// 分组内按类型整理：'smart' 与无连线时的“排列”一致，回落到宫格。
function arrangeGroupMembersByType(group, type){
    if(!isSmartGroupNode(group)) return false;
    const memberIds = Array.isArray(group.items) ? group.items : [];
    const members = memberIds.map(mid => nodes.find(n => n.id === mid)).filter(Boolean);
    if(members.length < 2) return false;
    const direction = type === 'smart' ? 'grid' : type;
    members.sort((a, b) => {
        const ra = nodeRect(a), rb = nodeRect(b);
        if(Math.abs(ra.y - rb.y) > 30) return ra.y - rb.y;
        return ra.x - rb.x;
    });
    const rects = members.map(nodeRect);
    layoutNodesInBox(members, Math.min(...rects.map(r => r.x)), Math.min(...rects.map(r => r.y)), direction);
    fitSmartGroupBounds(group);
    return true;
}
function sortSelection(direction){
    const ids = selectedNodeIds();
    let selected = ids.map(id => nodes.find(n => n.id === id)).filter(Boolean);
    let parentGroup = null;
    if(selected.length === 1 && isSmartGroupNode(selected[0])){
        parentGroup = selected[0];
        const memberIds = Array.isArray(parentGroup.items) ? parentGroup.items : [];
        selected = memberIds.map(mid => nodes.find(n => n.id === mid)).filter(Boolean);
    }
    if(selected.length < 2) return;
    pushUndo();
    
    selected.sort((a, b) => {
        const ra = nodeRect(a), rb = nodeRect(b);
        if (Math.abs(ra.y - rb.y) > 30) return ra.y - rb.y;
        return ra.x - rb.x;
    });

    const rects = selected.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    layoutNodesInBox(selected, minX, minY, direction);
    if(parentGroup){
        fitSmartGroupBounds(parentGroup);
    }
    render(); scheduleSave();
    if(typeof updateMultiSelectionOverlay === "function") setTimeout(updateMultiSelectionOverlay, 30);
}

function arrangeSelectedSmartNodes() {
    const ids = selectedNodeIds();
    let selected = ids.map(id => nodes.find(n => n.id === id)).filter(Boolean);
    let parentGroup = null;
    if(selected.length === 1 && isSmartGroupNode(selected[0])){
        parentGroup = selected[0];
        const memberIds = Array.isArray(parentGroup.items) ? parentGroup.items : [];
        selected = memberIds.map(mid => nodes.find(n => n.id === mid)).filter(Boolean);
    }
    if(selected.length < 2) return;
    
    const selectedSet = new Set(selected.map(n => n.id));
    const edges = (canvas.connections || []).filter(c => selectedSet.has(c.from) && selectedSet.has(c.to));
    
    if (edges.length === 0) {
        return sortSelection("grid");
    }
    
    pushUndo();
    const adj = {};
    const inDegree = {};
    selected.forEach(n => { adj[n.id] = []; inDegree[n.id] = 0; });
    edges.forEach(e => {
        if(adj[e.from] && inDegree[e.to] !== undefined) {
            adj[e.from].push(e.to);
            inDegree[e.to]++;
        }
    });
    
    const columns = [];
    let queue = selected.filter(n => inDegree[n.id] === 0);
    const visited = new Set(queue.map(n => n.id));
    
    while(queue.length > 0) {
        columns.push(queue);
        const nextQueue = [];
        queue.forEach(n => {
            adj[n.id].forEach(childId => {
                inDegree[childId]--;
                if(inDegree[childId] === 0 && !visited.has(childId)) {
                    visited.add(childId);
                    const childNode = selected.find(sn => sn.id === childId);
                    if(childNode) nextQueue.push(childNode);
                }
            });
        });
        queue = nextQueue;
    }
    
    const leftOvers = selected.filter(n => !visited.has(n.id));
    if (leftOvers.length > 0) columns.push(leftOvers);
    
    const rects = selected.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const gapX = 80;
    const gapY = 40;
    
    let currentX = minX;
    columns.forEach(col => {
        let currentY = minY;
        let maxColWidth = 0;
        
        col.sort((a, b) => nodeRect(a).y - nodeRect(b).y);
        
        col.forEach(n => {
            const r = nodeRect(n);
            n.x = currentX;
            n.y = currentY;
            currentY += r.height + gapY;
            maxColWidth = Math.max(maxColWidth, r.width);
        });
        currentX += maxColWidth + gapX;
    });
    if(parentGroup){
        fitSmartGroupBounds(parentGroup);
    }
    render();
    scheduleSave();
    if(typeof updateMultiSelectionOverlay === "function") setTimeout(updateMultiSelectionOverlay, 30);
}

function computeSelectedNodesBoundingBox(){
    const ids = selectedNodeIds();
    const selNodes = ids.map(id => nodes.find(n => n.id === id)).filter(Boolean);
    if(selNodes.length <= 1) return null;
    const rects = selNodes.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const maxX = Math.max(...rects.map(r => r.x + r.width));
    const maxY = Math.max(...rects.map(r => r.y + r.height));
    return { minX, minY, maxX, maxY, width: maxX - minX, height: maxY - minY, count: selNodes.length, isSingleGroup: false, nodes: selNodes };
}

function updateMultiSelectionOverlay(){
    const box = document.getElementById("smartMultiSelectionBox");
    const ids = selectedNodeIds();
    if(box){
        if(ids.length <= 1){
            box.style.display = "none";
            closeMultiSelectArrangeMenu();
        } else {
            const bounds = computeSelectedNodesBoundingBox();
            if(!bounds || bounds.isSingleGroup){
                box.style.display = "none";
                closeMultiSelectArrangeMenu();
            } else {
                const pad = 16;
                box.style.display = "block";
                box.style.left = `${Math.round(bounds.minX - pad)}px`;
                box.style.top = `${Math.round(bounds.minY - pad)}px`;
                box.style.width = `${Math.round(bounds.width + pad * 2)}px`;
                box.style.height = `${Math.round(bounds.height + pad * 2)}px`;
            }
        }
    }
    // 工具栏不再单独渲染：统一由 updateFloatingToolbar 按单选/分组/多选三种状态输出。
    if(typeof updateFloatingToolbar === 'function') updateFloatingToolbar(selectedNode());
}

function positionMultiSelectionToolbar(existingBounds){
    const toolbar = smartNodeFloatingMenu;
    if(!toolbar) return;
    if(selectedNodeIds().length <= 1) return;
    const bounds = existingBounds || computeSelectedNodesBoundingBox();
    if(!bounds || bounds.isSingleGroup) return;
    const s = safeScale(viewport.scale);
    // 与单选工具栏保持同一呼吸间距：多选时锚定在虚线包围框上方。
    const pad = 16;
    const menuH = toolbar.offsetHeight || 52;
    const menuW = toolbar.offsetWidth || 320;
    const boxTopScreenY = viewport.y + (bounds.minY - pad) * s;
    const topPx = Math.round(boxTopScreenY - menuH - 8);
    let leftPx = Math.round(viewport.x + (bounds.minX - pad) * s);
    leftPx = Math.max(12, Math.min(window.innerWidth - menuW - 12, leftPx));
    toolbar.classList.remove('tooltip-bottom');
    toolbar.style.left = `${leftPx}px`;
    toolbar.style.top = `${topPx}px`;
    toolbar.style.transform = 'none';
    toolbar.style.setProperty('--anti-zoom', 1);
    if(isArrangeMenuOpen()) positionArrangeMenu();
}

function isArrangeMenuOpen(){
    const menu = document.getElementById('smartMultiSelectArrangeDropdown');
    return menu && menu.style.display !== 'none';
}

function closeMultiSelectArrangeMenu(){
    const menu = document.getElementById('smartMultiSelectArrangeDropdown');
    if(menu) menu.style.display = 'none';
}

// “排列”（多选）与“整理分组”共用这一份菜单和同一个开合入口。
function arrangeMenuButton(){
    return document.querySelector('#smartNodeFloatingMenu [data-smart-arrange-menu]');
}
function toggleMultiSelectArrangeMenu(event){
    event?.preventDefault();
    event?.stopPropagation();
    const menu = document.getElementById('smartMultiSelectArrangeDropdown');
    const btn = arrangeMenuButton();
    if(!menu || !btn) return;
    if(menu.style.display !== 'none'){
        closeMultiSelectArrangeMenu();
    } else {
        menu.style.display = 'flex';
        positionArrangeMenu();
    }
}

function positionArrangeMenu(){
    const menu = document.getElementById('smartMultiSelectArrangeDropdown');
    const btn = arrangeMenuButton();
    if(!menu || !btn || menu.style.display === 'none') return;
    const rect = btn.getBoundingClientRect();
    const menuW = menu.offsetWidth || 160;
    let leftPx = Math.round(rect.left);
    leftPx = Math.max(12, Math.min(window.innerWidth - menuW - 12, leftPx));
    menu.style.left = `${leftPx}px`;
    menu.style.top = `${Math.round(rect.bottom + 6)}px`;
}

async function downloadSelectedNodesImages(){
    const ids = selectedNodeIds();
    let selNodes = ids.map(id => nodes.find(n => n.id === id)).filter(Boolean);
    let singleGroup = null;
    if(selNodes.length === 1 && isSmartGroupNode(selNodes[0])){
        singleGroup = selNodes[0];
        const memberIds = Array.isArray(singleGroup.items) ? singleGroup.items : [];
        const memberNodes = memberIds.map(mid => nodes.find(n => n.id === mid)).filter(Boolean);
        if(memberNodes.length) selNodes = memberNodes;
    }
    const items = [];
    selNodes.forEach((node, nodeIdx) => {
        const title = node.title || `node-${nodeIdx + 1}`;
        const addImg = (img, idx) => {
            if(!img) return;
            const url = typeof img === 'string' ? img : (img.url || img.src || '');
            if(url){
                const defaultName = (node.images || []).length <= 1 ? `${title}.png` : `${title}-${idx + 1}.png`;
                const name = typeof downloadNameForMediaItem === 'function' ? downloadNameForMediaItem(img, defaultName.replace(/\.png$/i, '')) : defaultName;
                items.push({url, name});
            }
        };
        (node.images || []).forEach(addImg);
        (node.mediaItems || []).forEach(addImg);
        if(node.imageUrl) addImg(node.imageUrl, 0);
        if(node.outputUrl) addImg(node.outputUrl, 0);
    });
    if(!items.length){
        if(typeof showToast === 'function') showToast('选中节点中未找到可下载的图片');
        return;
    }
    const zipName = singleGroup?.title || '批量导出图片';
    if(typeof zipDownloadImageItems === 'function'){
        await zipDownloadImageItems(zipName, items);
    } else {
        items.forEach(it => {
            const a = document.createElement('a');
            a.href = it.url;
            a.download = it.name || 'image.png';
            a.click();
        });
    }
}

function deleteSelectedNodesOrGroup(){
    const bounds = computeSelectedNodesBoundingBox();
    const ids = selectedNodeIds();
    if(!ids.length && !bounds) return;

    let deleteIds = new Set();
    const isSingleGroup = Boolean(bounds && bounds.isSingleGroup && bounds.groupNode);

    if(isSingleGroup){
        const group = bounds.groupNode;
        deleteIds.add(group.id);
        const members = smartGroupMembers(group);
        members.forEach(m => deleteIds.add(m.id));
        if(Array.isArray(group.items)){
            group.items.forEach(mid => deleteIds.add(mid));
        }
        nodes.forEach(n => {
            if(n.groupId === group.id) deleteIds.add(n.id);
            if(isHistoryGroupNode(n) && n.historyFor === group.id) deleteIds.add(n.id);
        });
    } else {
        ids.forEach(id => {
            deleteIds.add(id);
            const n = nodes.find(x => x.id === id);
            if(n){
                if(isSmartGroupNode(n)){
                    const members = smartGroupMembers(n);
                    members.forEach(m => deleteIds.add(m.id));
                    if(Array.isArray(n.items)){
                        n.items.forEach(mid => deleteIds.add(mid));
                    }
                    nodes.forEach(sub => {
                        if(sub.groupId === n.id) deleteIds.add(sub.id);
                        if(isHistoryGroupNode(sub) && sub.historyFor === n.id) deleteIds.add(sub.id);
                    });
                }
                if(n.gridSplitGroup){
                    nodes.forEach(sub => {
                        if(sub.groupId === n.id) deleteIds.add(sub.id);
                    });
                }
                nodes.forEach(sub => {
                    if(isHistoryGroupNode(sub) && sub.historyFor === id) deleteIds.add(sub.id);
                });
            }
        });
    }

    if(!deleteIds.size) return;

    pushUndo();

    if(window.CanvasTrash){
        deleteIds.forEach(delId => {
            const target = nodes.find(n => n.id === delId);
            if(target) window.CanvasTrash.recordNode(target);
        });
    }

    if(canvas){
        canvas.connections = (canvas.connections || []).filter(c => !deleteIds.has(c.from) && !deleteIds.has(c.to));
    }

    const deletedNodes = nodes.filter(node => deleteIds.has(node.id));
    nodes = nodes.filter(node => !deleteIds.has(node.id));
    nodes.forEach(node => {
        if(node.groupId && deleteIds.has(node.groupId)) delete node.groupId;
        if(Array.isArray(node.inputNodeIds)){
            node.inputNodeIds = node.inputNodeIds.filter(inputId => !deleteIds.has(inputId));
        }
        if(isSmartGroupNode(node) && Array.isArray(node.items)){
            node.items = node.items.filter(itemId => !deleteIds.has(itemId));
        }
    });
    rememberTrustedCanvasAssets();

    selectedIds = [];
    selectedId = '';
    selectedImage = {nodeId:'', index:-1};

    if(smartNodeFloatingMenu) smartNodeFloatingMenu.classList.remove('open');
    closeMultiSelectArrangeMenu();
    updateMultiSelectionOverlay();
    render();
    submitLanDeleteOperations(deleteIds, deletedNodes);
    if(!isLanMode) scheduleSave();

    const toastMsg = isSingleGroup
        ? '已删除分组及内部素材 (Ctrl+Z 可快速撤销)'
        : `已删除选中的素材 (共 ${deleteIds.size} 项，Ctrl+Z 可快速撤销)`;
    if(typeof toast === 'function') toast(toastMsg);
    else if(typeof showToast === 'function') showToast(toastMsg);
}

function groupSelectedNodes(){
    const ids = selectedIds.length ? selectedIds.slice() : (selectedId ? [selectedId] : []);
    const selected = ids.map(id => nodes.find(n => n.id === id)).filter(n => n && !isSmartGroupNode(n));
    if(selected.length < 1){ toast('请选择要放入分组的节点'); return; }
    pushUndo();

    // 如果选中的节点原先属于其他分组，从原分组 items 中移除
    selected.forEach(node => {
        if(node.groupId){
            const oldG = nodes.find(g => g.id === node.groupId && isSmartGroupNode(g));
            if(oldG && Array.isArray(oldG.items)){
                oldG.items = oldG.items.filter(mid => mid !== node.id);
            }
        }
    });

    const rects = selected.map(nodeRect);
    const minX = Math.min(...rects.map(r => r.x));
    const minY = Math.min(...rects.map(r => r.y));
    const maxX = Math.max(...rects.map(r => r.x + r.width));
    const maxY = Math.max(...rects.map(r => r.y + r.height));

    const padX = 24;
    const padTop = 32;
    const padBottom = 24;

    const groupW = Math.max(260, Math.round((maxX - minX) + padX * 2));
    const groupH = Math.max(180, Math.round((maxY - minY) + padTop + padBottom));
    const groupX = Math.round(minX - padX);
    const groupY = Math.round(minY - padTop);

    // 计算自动递增编号：如“分组 1”、“分组 2”...
    const existingGroupNums = nodes
        .filter(isSmartGroupNode)
        .map(n => {
            const m = String(n.title || '').match(/^(?:分组|智能分组)\s*(\d+)$/);
            return m ? parseInt(m[1], 10) : 0;
        });
    const maxNum = existingGroupNums.length ? Math.max(0, ...existingGroupNums) : 0;
    const nextNum = maxNum + 1;

    const group = {
        id: uid('group'),
        type: 'smart-group',
        isFrameGroup: true,
        x: groupX,
        y: groupY,
        w: groupW,
        h: groupH,
        title: `分组 ${nextNum}`,
        items: selected.map(n => n.id),
        images: [],
        created_at: Date.now()
    };

    selected.forEach(node => {
        node.groupId = group.id;
    });

    // 插入 nodes 列表中排在首个成员之前，确保底层渲染
    const firstMemberIdx = nodes.findIndex(n => selected.some(s => s.id === n.id));
    if(firstMemberIdx >= 0){
        nodes.splice(firstMemberIdx, 0, group);
    } else {
        nodes.unshift(group);
    }

    selectedIds = [group.id];
    selectedId = group.id;
    selectedImage = {nodeId:'', index:-1};
    render();
    scheduleSave();
    if(typeof showToast === 'function') showToast(`已创建 ${group.title}（包含 ${selected.length} 个节点）`);
}
function ungroupNode(groupId){
    const group = nodes.find(n => n.id === groupId);
    if(!group) return false;
    if(isSmartGroupNode(group)){
        pushUndo();
        // 现代 Frame 容器式分组（或无吸附图片成员的容器组）：零损伤剥离外框，所有子节点与拓扑连线原地保留
        if(group.isFrameGroup || group.gridSplitGroup || (!group.images || !group.images.length)){
            const memberIds = Array.isArray(group.items) ? group.items.slice() : [];
            nodes = nodes.filter(n => n.id !== groupId);
            nodes.forEach(node => {
                if(node.groupId === groupId) delete node.groupId;
                if(isSmartGroupNode(node) && Array.isArray(node.items)){
                    node.items = node.items.filter(id => id !== groupId);
                }
            });
            if(canvas) canvas.connections = (canvas.connections || []).filter(c => c.from !== groupId && c.to !== groupId);
            selectedIds = memberIds.filter(id => nodes.some(n => n.id === id));
            selectedId = selectedIds.length === 1 ? selectedIds[0] : '';
            selectedImage = {nodeId:'', index:-1};
            render();
            scheduleSave();
            if(typeof showToast === 'function') showToast('已解散分组');
            return true;
        }
        const memberIds = smartGroupMembers(group).map(m => m.id);
        const groupImages = (group.images || []).filter(img => img?.url);
        let created = [];
        if(groupImages.length){
            const count = groupImages.length;
            const cols = Math.min(4, Math.max(1, Math.ceil(Math.sqrt(count))));
            const rows = Math.ceil(count / cols);
            const gap = 24;
            const layouts = groupImages.map(img => singleImageLayout(img, {}, MEDIA_NODE_DEFAULT_SCALE));
            const colW = new Array(cols).fill(0);
            const rowH = new Array(rows).fill(0);
            layouts.forEach((lay, i) => {
                const c = i % cols;
                const r = Math.floor(i / cols);
                colW[c] = Math.max(colW[c], lay.width);
                rowH[r] = Math.max(rowH[r], lay.height);
            });
            const colX = [];
            let accX = 0;
            for(let c = 0; c < cols; c++){
                colX[c] = accX;
                accX += colW[c] + gap;
            }
            const rowY = [];
            let accY = 0;
            for(let r = 0; r < rows; r++){
                rowY[r] = accY;
                accY += rowH[r] + gap;
            }
            created = groupImages.map((img, index) => {
                const col = index % cols;
                const row = Math.floor(index / cols);
                const lay = layouts[index];
                const x = Math.round(Number(group.x || 0) + colX[col] + Math.max(0, (colW[col] - lay.width) / 2));
                const y = Math.round(Number(group.y || 0) + rowY[row] + Math.max(0, (rowH[row] - lay.height) / 2));
                const node = {
                    id: uid('smart'),
                    type: 'smart-image',
                    x,
                    y,
                    title: '图片',
                    images: [stripImageGenerationMeta({...img})],
                    scale: MEDIA_NODE_DEFAULT_SCALE,
                    created_at: Date.now()
                };
                if(!node.gridSplitChild && !node.isCroppedVideo){ delete node.w; delete node.h; }
                inheritNodeMetaFromImage(node);
                clearDetachedRunInputRefs(node);
                return node;
            });
        }
        nodes = nodes.filter(n => n.id !== groupId);
        nodes.push(...created);
        if(canvas) canvas.connections = (canvas.connections || []).filter(c => c.from !== groupId && c.to !== groupId);
        nodes.forEach(node => {
            if(Array.isArray(node.inputNodeIds)) node.inputNodeIds = node.inputNodeIds.filter(id => id !== groupId);
            if(isSmartGroupNode(node) && Array.isArray(node.items)) node.items = node.items.filter(id => id !== groupId);
        });
        selectedIds = [...created.map(n => n.id), ...memberIds].filter(id => nodes.some(n => n.id === id));
        selectedId = selectedIds.length === 1 ? selectedIds[0] : '';
        selectedImage = {nodeId:'', index:-1};
        render();
        scheduleSave();
        return true;
    }
    if(!Array.isArray(group.images) || group.images.length < 2) return false;
    pushUndo();
    const groupImages = (group.images || []).filter(img => img?.url);
    const count = groupImages.length;
    const cols = Math.min(4, Math.max(1, Math.ceil(Math.sqrt(count))));
    const rows = Math.ceil(count / cols);
    const gap = 24;
    const layouts = groupImages.map(img => singleImageLayout(img, {}, MEDIA_NODE_DEFAULT_SCALE));
    const colW = new Array(cols).fill(0);
    const rowH = new Array(rows).fill(0);
    layouts.forEach((lay, i) => {
        const c = i % cols;
        const r = Math.floor(i / cols);
        colW[c] = Math.max(colW[c], lay.width);
        rowH[r] = Math.max(rowH[r], lay.height);
    });
    const colX = [];
    let accX = 0;
    for(let c = 0; c < cols; c++){
        colX[c] = accX;
        accX += colW[c] + gap;
    }
    const rowY = [];
    let accY = 0;
    for(let r = 0; r < rows; r++){
        rowY[r] = accY;
        accY += rowH[r] + gap;
    }
    const created = groupImages.map((img, index) => {
        const col = index % cols;
        const row = Math.floor(index / cols);
        const lay = layouts[index];
        const x = Math.round(Number(group.x || 0) + colX[col] + Math.max(0, (colW[col] - lay.width) / 2));
        const y = Math.round(Number(group.y || 0) + rowY[row] + Math.max(0, (rowH[row] - lay.height) / 2));
        const node = {
            id: uid('smart'),
            type: 'smart-image',
            x,
            y,
            title: '图片',
            images: [stripImageGenerationMeta({...img})],
            scale: MEDIA_NODE_DEFAULT_SCALE,
            created_at: Date.now()
        };
        if(!node.gridSplitChild && !node.isCroppedVideo){ delete node.w; delete node.h; }
        inheritNodeMetaFromImage(node);
        clearDetachedRunInputRefs(node);
        return node;
    });
    nodes = nodes.filter(n => n.id !== groupId);
    nodes.push(...created);
    if(canvas) canvas.connections = (canvas.connections || []).filter(c => c.from !== groupId && c.to !== groupId);
    nodes.forEach(node => {
        if(Array.isArray(node.inputNodeIds)){
            node.inputNodeIds = node.inputNodeIds.filter(inputId => inputId !== groupId);
        }
    });
    selectedIds = created.map(node => node.id);
    selectedId = selectedIds.length === 1 ? selectedIds[0] : '';
    selectedImage = {nodeId:'', index:-1};
    render();
    scheduleSave();
    return true;
}
function mergeImageNodesIntoGroup(sourceId, targetId){
    const source = nodes.find(n => n.id === sourceId);
    const target = nodes.find(n => n.id === targetId);
    if(!source || !target || source.id === target.id) return false;
    if(!(source.images || []).length || !(target.images || []).length) return false;
    const sourceImages = (source.images || []).map(img => stripImageGenerationMeta({...img}));
    target.images = [...(target.images || []).map(img => stripImageGenerationMeta(img)), ...sourceImages];
    target.title = '素材组';
    if(!Number.isFinite(Number(target.scale)) || Number(target.scale) === MEDIA_NODE_DEFAULT_SCALE) target.scale = MEDIA_GROUP_DEFAULT_SCALE;
    delete target.w;
    delete target.h;
    canvas.connections = (canvas.connections || []).map(c => {
        if(c.from === source.id) return {...c, from:target.id};
        if(c.to === source.id) return {...c, to:target.id};
        return c;
    }).filter((c, index, arr) => c.from !== c.to && arr.findIndex(x => x.from === c.from && x.to === c.to && (x.kind || 'flow') === (c.kind || 'flow')) === index);
    nodes.forEach(node => {
        if(Array.isArray(node.inputNodeIds)){
            node.inputNodeIds = Array.from(new Set(node.inputNodeIds.map(id => id === source.id ? target.id : id).filter(id => id !== node.id)));
        }
    });
    nodes = nodes.filter(n => n.id !== source.id);
    selectedIds = [];
    selectedId = target.id;
    selectedImage = {nodeId:'', index:-1};
    return true;
}
function smartGroupTargetForDraggedNode(draggedNode){
    // 允许把一个分组拖进另一个分组（拖来的分组的成员会作为输入并入目标分组）。自身/被拖分组及其成员已在 excluded 中排除。
    if(!draggedNode) return null;
    const r = nodeRect(draggedNode);
    const excluded = new Set([
        draggedNode.id,
        ...(dragState?.groupIds || []),
        ...(draggedNode.groupId ? [draggedNode.groupId] : [])
    ]);
    const cx = r.x + r.width / 2;
    const cy = r.y + r.height / 2;
    const groups = nodes
        .filter(node => isSmartGroupNode(node) && !excluded.has(node.id) && !(Array.isArray(node.items) && node.items.includes(draggedNode.id)))
        .map(group => ({group, rect:nodeRect(group)}))
        .filter(item => cx >= item.rect.x && cx <= item.rect.x + item.rect.width && cy >= item.rect.y && cy <= item.rect.y + item.rect.height);
    if(!groups.length) return null;
    groups.sort((a, b) => (nodes.indexOf(b.group) - nodes.indexOf(a.group)));
    return groups[0].group;
}
// 把一个或多个被拖动的节点批量加入目标分组（支持多选拖入）。入组后只整理一次并选中目标分组。
function addDraggedNodesToSmartGroup(draggedNodes, group){
    if(!group || !isSmartGroupNode(group)) return false;
    const list = (draggedNodes || []).filter(n => n && n.id !== group.id);
    if(!list.length) return false;
    let added = false;
    list.forEach(n => {
        if(addNodeToSmartGroup(group, n)) added = true;
    });
    if(!added) return false;
    // 提示词/循环成员入组后自动整理成网格（图片已收进卡片网格，自动平铺）。
    arrangeSmartGroupMembers(group, {skipUndo:true});
    selectedIds = [];
    // 图片被吸收进分组（原节点已删除），统一选中目标分组；仅当单个提示词/循环节点拖入时保持选中它。
    const survivingSingle = list.length === 1 && nodes.some(n => n.id === list[0].id) ? list[0].id : '';
    selectedId = survivingSingle || group.id;
    selectedImage = {nodeId:'', index:-1};
    return true;
}
function closeCreateMenu(){
    createMenu?.classList.remove('open');
    createMenuGroupId = '';
    // 素材右键菜单与它是同一套外观，一起收起，避免两个菜单同时残留。
    if(typeof closeSmartNodeContextMenu === 'function') closeSmartNodeContextMenu();
}
function openCreateMenu(event, options={}){
    if(!createMenu) return;
    closeLinkCreateMenu();
    createMenuPoint = screenToWorld(event);
    createMenuGroupId = options.groupId || '';
    const w = 240;
    const h = 210;
    const left = Math.max(14, Math.min(window.innerWidth - w - 14, event.clientX + 8));
    const top = Math.max(14, Math.min(window.innerHeight - h - 14, event.clientY + 8));
    createMenu.style.left = `${left}px`;
    createMenu.style.top = `${top}px`;
    createMenu.classList.add('open');
    refreshIcons(createMenu);
}
function addCreatedNodeToMenuGroup(node){
    const group = createMenuGroupId ? nodes.find(n => n.id === createMenuGroupId) : null;
    if(addNodeToSmartGroup(group, node)){
        // 通过分组小菜单新建的节点入组后自动整理（节点创建已压过 undo，这里不再重复）。
        arrangeSmartGroupMembers(group, {skipUndo:true});
        render();
        scheduleSave();
    }
}
function createNodeFromMenu(type){
    const p = createMenuPoint || viewportCenter();
    const groupId = createMenuGroupId;
    closeCreateMenu();
    if(type === 'upload'){
        pendingGroupUploadPoint = p;
        uploadTargetId = groupId || '';
        fileInput.click();
        createMenuGroupId = '';
        return null;
    }
    if(type === 'group') return createSmartGroupNode(p.x - 170, p.y - 110);
    let created = null;
    if(type === 'prompt') created = createPromptNode(p.x - 158, p.y - 97);
    else if(type === 'loop') created = createLoopNode(p.x - 135, p.y - 95);
    else if(type === 'video' || type === 'video-gen') created = createVideoGenNodeAt(p);
    else if(type === 'image-gen' || type === 'image') created = createImageGenNodeAt(p);
    else created = createImageGenNodeAt(p);
    createMenuGroupId = groupId;
    addCreatedNodeToMenuGroup(created);
    createMenuGroupId = '';
    return created;
}
