// Minimap 收纳与展开控制
const MINIMAP_COLLAPSED_KEY = 'smart_canvas_minimap_collapsed';
function initMinimapCollapse(){
    const shellEl = document.querySelector('.shell') || document.body;
    const minimapEl = document.getElementById('minimap');
    const toggleBtn = document.getElementById('minimapToggleBtn');
    const toggleText = document.getElementById('minimapToggleText');

    let isCollapsed = localStorage.getItem(MINIMAP_COLLAPSED_KEY) === '1';

    function setMinimapCollapsed(collapsed, save = true){
        isCollapsed = Boolean(collapsed);
        if(save) {
            try { localStorage.setItem(MINIMAP_COLLAPSED_KEY, isCollapsed ? '1' : '0'); } catch(e){}
        }
        if(minimapEl){
            minimapEl.classList.toggle('collapsed', isCollapsed);
            minimapEl.setAttribute('aria-hidden', isCollapsed ? 'true' : 'false');
        }
        shellEl?.classList.toggle('minimap-collapsed', isCollapsed);

        if(toggleBtn){
            const text = isCollapsed ? '展开地图' : '收纳地图';
            const icon = isCollapsed ? 'map-pin' : 'map';
            toggleBtn.title = text;
            toggleBtn.setAttribute('aria-label', text);
            toggleBtn.classList.toggle('is-collapsed', isCollapsed);
            toggleBtn.innerHTML = `<i data-lucide="${icon}"></i><span id="minimapToggleText">${text}</span>`;
        }
        if(window.lucide && typeof lucide.createIcons === 'function'){
            try {
                if(toggleBtn) lucide.createIcons({root: toggleBtn});
            } catch(e){}
        }
        if(!isCollapsed && typeof renderMinimap === 'function'){
            renderMinimap(true);
        }
    }

    toggleBtn?.addEventListener('mousedown', e => e.stopPropagation());
    toggleBtn?.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        setMinimapCollapsed(!isCollapsed);
    });

    setMinimapCollapsed(isCollapsed, false);
    window.toggleMinimapCollapse = () => setMinimapCollapsed(!isCollapsed);
    window.showMinimap = () => setMinimapCollapsed(false);
    window.hideMinimap = () => setMinimapCollapsed(true);
}
initMinimapCollapse();

// 连接线隐藏与显示控制（未选中素材时自动隐藏连接线，仅显示当前选中素材的连接线）
const CONNECTION_LINES_HIDE_UNSELECTED_KEY = 'smart_canvas_hide_unselected_conns';
function initConnectionLinesToggle(){
    const shellEl = document.querySelector('.shell') || document.body;
    const toggleBtn = document.getElementById('connectionLinesToggleBtn');

    let isHideUnselected = localStorage.getItem(CONNECTION_LINES_HIDE_UNSELECTED_KEY) === '1';

    function setHideUnselectedConns(hide, save = true){
        isHideUnselected = Boolean(hide);
        if(save){
            try { localStorage.setItem(CONNECTION_LINES_HIDE_UNSELECTED_KEY, isHideUnselected ? '1' : '0'); } catch(e){}
        }
        shellEl?.classList.toggle('hide-unselected-conns', isHideUnselected);

        if(toggleBtn){
            const text = isHideUnselected ? '显示连线' : '隐藏连线';
            const title = isHideUnselected ? '显示全部连线' : '隐藏未选连线（仅选中时显示）';
            toggleBtn.title = title;
            toggleBtn.setAttribute('aria-label', title);
            toggleBtn.classList.toggle('is-active', isHideUnselected);
            toggleBtn.innerHTML = `<i data-lucide="spline"></i><span id="connectionLinesToggleText">${text}</span>`;
        }
        if(window.lucide && typeof lucide.createIcons === 'function'){
            try {
                if(toggleBtn) lucide.createIcons({root: toggleBtn});
            } catch(e){}
        }
        if(typeof updateConnectionSelection === 'function'){
            updateConnectionSelection();
        }
    }

    toggleBtn?.addEventListener('mousedown', e => e.stopPropagation());
    toggleBtn?.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        setHideUnselectedConns(!isHideUnselected);
    });

    setHideUnselectedConns(isHideUnselected, false);
    window.toggleConnectionLinesHide = () => setHideUnselectedConns(!isHideUnselected);
    window.setConnectionLinesHide = (val) => setHideUnselectedConns(val);
}
initConnectionLinesToggle();

