// 统一工具栏的排列二级菜单点击代理（按钮本身由 updateFloatingToolbar 绑定）
const multiArrangeDropdown = document.getElementById('smartMultiSelectArrangeDropdown');
multiArrangeDropdown?.addEventListener('mousedown', e => e.stopPropagation());
multiArrangeDropdown?.addEventListener('pointerdown', e => e.stopPropagation());
multiArrangeDropdown?.addEventListener('click', e => {
    const item = e.target.closest('[data-arrange-type]');
    if(!item) return;
    const type = item.dataset.arrangeType;
    closeMultiSelectArrangeMenu();
    // 作用范围由当前选中决定：选中单个分组时整理组内成员，多选时排列所选节点。
    const subject = selectedNode();
    if(subject && isSmartGroupNode(subject)){
        const memberIds = Array.isArray(subject.items) ? subject.items : [];
        const members = memberIds.map(mid => nodes.find(n => n.id === mid)).filter(Boolean);
        if(members.length < 2){ toast('没有可整理的节点'); return; }
        pushUndo();
        arrangeGroupMembersByType(subject, type);
        render();
        scheduleSave();
        if(typeof updateMultiSelectionOverlay === 'function') setTimeout(updateMultiSelectionOverlay, 30);
        return;
    }
    if(type === 'smart'){
        arrangeSelectedSmartNodes();
    } else if(type === 'grid' || type === 'horizontal' || type === 'vertical'){
        sortSelection(type);
    }
    setTimeout(updateMultiSelectionOverlay, 50);
});

