canvasBottomToolbar?.addEventListener('mousedown', e => {
    e.preventDefault();
    e.stopPropagation();
});
function updateDragNodePositions(e){
    if(!dragState) return;
    const node = nodes.find(n => n.id === dragState.id);
    if(!node) return;
    const clientX = typeof e?.clientX === 'number' ? e.clientX : (e?.x ?? 0);
    const clientY = typeof e?.clientY === 'number' ? e.clientY : (e?.y ?? 0);
    const curWorld = screenToWorld({clientX, clientY});
    const s = safeScale(viewport.scale);
    const rect = shell ? shell.getBoundingClientRect() : {left:0, top:0};
    const startW = dragState.startWorld || {
        x: (dragState.startX - rect.left - (dragState.startVx ?? viewport.x)) / s,
        y: (dragState.startY - rect.top - (dragState.startVy ?? viewport.y)) / s
    };
    const rawMoveDx = curWorld.x - startW.x;
    const rawMoveDy = curWorld.y - startW.y;
    const rawX = (dragState.ox || 0) + rawMoveDx;
    const rawY = (dragState.oy || 0) + rawMoveDy;
    const snap = calculateSmartMagneticSnap(node, rawX, rawY, 10);
    const moveDx = snap.x - (dragState.ox || 0);
    const moveDy = snap.y - (dragState.oy || 0);
    (dragState.group || [{id:dragState.id, ox:dragState.ox, oy:dragState.oy}]).forEach(item => {
        const n = nodes.find(x => x.id === item.id);
        if(!n) return;
        n.x = item.ox + moveDx;
        n.y = item.oy + moveDy;
    });
    renderSmartGuideLines(snap.guides);
    if(assetLibraryOpen){
        // 命中检测会强制同步重排布局，只在素材抽屉打开时执行，避免拖动过程卡顿。
        const hit = document.elementFromPoint(e.clientX, e.clientY);
        const assetW = (assetPanel && assetPanel.getBoundingClientRect().width) || 458;
        const isOverAsset = Boolean(hit && assetPanel?.contains(hit)) || Boolean(e.clientX <= Math.min(assetW, window.innerWidth - 54));
        setAssetDragOver(isOverAsset);
        if(isOverAsset){
            // 拖向素材抽屉时节点松手会回到原位，用一个跟随光标的投影表示“正在拖这份素材”。
            // 画布内普通拖动不创建投影：节点本身实时移动就是过程，叠加投影会出现大小两个影像。
            const dragDx = (typeof dragState.startX === 'number') ? (e.clientX - dragState.startX) : 0;
            const dragDy = (typeof dragState.startY === 'number') ? (e.clientY - dragState.startY) : 0;
            if(Math.hypot(dragDx, dragDy) > 5 && !smartDragFloatingGhostEl){
                const ghostTarget = resolveSmartDragGhostTarget(node);
                if(ghostTarget?.url){
                    createSmartDragFloatingGhost(ghostTarget.url, e.clientX, e.clientY, { aspectRatio: ghostTarget.aspectRatio });
                }
            }
            clearDropHighlight();
            moveNodeElementsDuringDrag();
            return;
        }
    }
    removeSmartDragFloatingGhost();
    const draggedRect = nodeRect(node);
    const rawTarget = dragState.ctrlGroup
        ? (['smart-prompt','smart-loop'].includes(node.type)
            ? dragConnectTargetFor(node, curWorld)
            : rectOverlapNode(node.id, draggedRect.x, draggedRect.y, draggedRect.width, draggedRect.height, dragState.groupIds))
        : null;
    const target = isSmartGroupNode(rawTarget) ? null : rawTarget;
    setDropHighlight(target?.id || '');
    moveNodeElementsDuringDrag();
    updateLoopInsertPreview();
    if(target) setDropHighlight(target.id);
}
window.onmousemove = e => {
    lastMouseWorld = screenToWorld(e);
    lastPointerPos = {clientX: e.clientX, clientY: e.clientY};
    updateSmartDragFloatingGhostPosition(e.clientX, e.clientY);
    if(smartMinimapDrag){
        e.preventDefault();
        centerViewportOnWorldPoint(minimapEventToWorld(e));
        return;
    }
    if(connectionEraseState){
        e.preventDefault();
        updateConnectionEraseTrail(e);
        eraseConnectionsAlongPointer(e);
        return;
    }
    if(portDragState){
        e.preventDefault();
        updatePortDragStateForPointer(e);
        checkEdgeAutoPan(e.clientX, e.clientY);
        return;
    }
    if(selectionState){
        e.preventDefault();
        updateSelectionBox(e);
        checkEdgeAutoPan(e.clientX, e.clientY);
        return;
    }
    if(previewCompareDrag){
        e.preventDefault();
        setPreviewComparePos(e.clientX);
        return;
    }
    if(panoramaState.drag){
        e.preventDefault();
        const dx = e.clientX - panoramaState.drag.clientX;
        const dy = e.clientY - panoramaState.drag.clientY;
        panoramaState.yaw = panoramaState.drag.yaw - dx * 0.18;
        panoramaState.pitch = Math.max(-85, Math.min(85, panoramaState.drag.pitch + dy * 0.18));
        document.getElementById('previewStage')?.classList.add('panning');
        return;
    }
    if(previewPanDrag){
        const stage = document.getElementById('previewStage');
        previewPan = {
            x:previewPanDrag.startX + (e.clientX - previewPanDrag.clientX),
            y:previewPanDrag.startY + (e.clientY - previewPanDrag.clientY)
        };
        stage?.classList.add('panning');
        applyPreviewTransform();
        return;
    }
    if(imageEditPanDrag){
        const stage = document.getElementById('imageEditStage');
        if(stage){
            stage.scrollLeft = imageEditPanDrag.scrollLeft - (e.clientX - imageEditPanDrag.clientX);
            stage.scrollTop = imageEditPanDrag.scrollTop - (e.clientY - imageEditPanDrag.clientY);
        }
        return;
    }
    if(resizeState){
        const node = nodes.find(n => n.id === resizeState.id);
        if(!node) return;
        const isSingleMediaNode = (node.type === 'smart-image' || node.type === 'smart-upload' || !node.type) && (node.images || []).length <= 1 && !isSmartGroupNode(node);
        if(isSingleMediaNode) return;
        const dx = (e.clientX - resizeState.startX) / viewport.scale;
        const dy = (e.clientY - resizeState.startY) / viewport.scale;
        const minW = node.type === 'smart-prompt' ? 260 : node.type === 'smart-loop' ? 252 : node.type === 'smart-group' ? SMART_GROUP_MIN_WIDTH : MIN_NODE_WIDTH;
        const minH = node.type === 'smart-prompt' ? 170 : node.type === 'smart-loop' ? 132 : node.type === 'smart-group' ? SMART_GROUP_MIN_HEIGHT : 48;
        const maxW = MAX_NODE_WIDTH;
        if(node.type === 'smart-group' && smartGroupImageRefs(node).some(ref => ref.item?.url)){
            // 图片分组：和普通节点一样直接改 w/h，缩略图网格按新尺寸实时重排。不要走下面的“成员缩放”那套，
            // 否则拖动过程里会按成员包围盒/缩放比例收缩，松手才回到拖动宽度（用户反馈的“变宽时先缩小”）。
            node.w = Math.max(minW, Math.min(maxW, Math.round(resizeState.startW + dx)));
            node.h = Math.max(minH, Math.round(resizeState.startH + dy));
            if(smartGroupCompactMembers(node).length) arrangeSmartGroupMembers(node, {skipUndo:true, syncDom:true});
            updateNodeElementDuringResize(node);
            positionComposerForNode(node);
            positionFloatingToolbarForNode(node);
            return;
        }
        if(node.type === 'smart-group'){
            // 分组当“画布中的画布”：拖手柄按宽度方向算出统一缩放比例，组内所有成员（图片+提示词）按相对手势
            // 起点的快照整体缩放+重排，然后把分组框自动收紧到成员的包围盒——盒子始终贴合内容，右侧不会留空白。
            const startZoom = resizeState.startZoom || 1;
            // 目标框宽 = 手柄拖出的框宽；缩放映射以“贴合内容的框宽”为基准，保证两个阶段都线性跟随手柄、衔接连续。
            const targetW = resizeState.startW + dx;
            const fitBase = resizeState.contentFitW || resizeState.startW || 1;
            const desiredZoom = startZoom * (targetW / fitBase);
            // 成员缩放上限 SMART_GROUP_MAX_MEMBER_ZOOM（默认 1=原始尺寸）：到上限就不再放大成员，改为让分组框继续扩大。
            const effectiveZoom = Math.max(0.2, Math.min(SMART_GROUP_MAX_MEMBER_ZOOM, desiredZoom));
            const memberRatio = effectiveZoom / startZoom;
            const capped = desiredZoom > SMART_GROUP_MAX_MEMBER_ZOOM;
            node._memberZoom = effectiveZoom;
            const gx = Number(node.x) || 0, gy = Number(node.y) || 0;
            const SMART_GROUP_PAD = 16;
            let maxRight = gx, maxBottom = gy, hasMember = false;
            (resizeState.members || []).forEach(snap => {
                const member = nodes.find(n => n.id === snap.id);
                if(!member) return;
                hasMember = true;
                member.x = gx + (snap.sx - gx) * memberRatio;
                member.y = gy + (snap.sy - gy) * memberRatio;
                member.w = Math.max(40, Math.round(snap.sw * memberRatio));
                member.h = Math.max(40, Math.round(snap.sh * memberRatio));
                if(snap.isImage) member.scale = 1;
                maxRight = Math.max(maxRight, member.x + member.w);
                maxBottom = Math.max(maxBottom, member.y + member.h);
                const memberEl = world.querySelector(`.image-node[data-id="${CSS.escape(member.id)}"]`);
                if(memberEl){
                    memberEl.style.left = `${member.x}px`;
                    memberEl.style.top = `${member.y}px`;
                }
                updateNodeElementDuringResize(member);
            });
            if(capped || !hasMember){
                // 成员已到上限（或空分组）：分组框随手柄继续扩大，成员不再放大。
                node.w = Math.max(minW, Math.min(maxW, Math.round(resizeState.startW + dx)));
                node.h = Math.max(minH, Math.round(resizeState.startH + dy));
            } else {
                // 未到上限：分组框收紧到成员包围盒，贴合内容无空白。
                node.w = Math.max(minW, Math.min(maxW, Math.round(maxRight - gx + SMART_GROUP_PAD)));
                node.h = Math.max(minH, Math.round(maxBottom - gy + SMART_GROUP_PAD));
            }
            node.scale = 1;
            updateNodeElementDuringResize(node);
            positionComposerForNode(node);
            positionFloatingToolbarForNode(node);
            return;
        }
        if(resizeState.isMedia && resizeState.aspectRatio && !e.shiftKey){
            const ratio = resizeState.aspectRatio;
            const deltaW = Math.abs(dx) >= Math.abs(dy * ratio) ? dx : (dy * ratio);
            let nextW = Math.max(minW, Math.round(resizeState.startW + deltaW));
            nextW = Math.min(maxW, nextW);
            let nextH = Math.max(minH, Math.round(nextW / ratio));
            nextW = Math.round(nextH * ratio);
            node.w = nextW;
            node.h = nextH;
        } else {
            node.w = Math.max(minW, Math.min(maxW, Math.round(resizeState.startW + dx)));
            node.h = Math.max(minH, Math.round(resizeState.startH + dy));
        }
        node.scale = 1;
        updateNodeElementDuringResize(node);
        positionComposerForNode(node);
        positionFloatingToolbarForNode(node);
        return;
    }
    if(llmInstructionResizeState){
        const node = nodes.find(n => n.id === llmInstructionResizeState.id);
        if(!node) return;
        const dy = (e.clientY - llmInstructionResizeState.startY) / viewport.scale;
        const newInstrH = Math.max(PROMPT_LLM_INSTRUCTION_MIN_H, Math.min(PROMPT_LLM_INSTRUCTION_MAX_H, Math.round(llmInstructionResizeState.startH + dy)));
        node.llmInstructionHeight = newInstrH;
        // 只把“指令框的高度变化量”叠加到节点总高度上，保留用户手动拉大的上方区域，避免上方被重置变小。
        node.h = Math.max(promptNodeExpandedHeight(node), Math.round(llmInstructionResizeState.startNodeH + (newInstrH - llmInstructionResizeState.startH)));
        node.w = Math.max(Number(node.w) || 0, 316);
        node.scale = 1;
        updateNodeElementDuringResize(node);
        const ta = world.querySelector(`.image-node[data-id="${CSS.escape(node.id)}"] .prompt-llm-instruction`);
        if(ta) ta.style.height = `${promptLlmInstructionHeight(node)}px`;
        return;
    }
    if(promptSplitResizeState){
        const node = nodes.find(n => n.id === promptSplitResizeState.id);
        if(!node) return;
        const dy = (e.clientY - promptSplitResizeState.startY) / viewport.scale;
        const newPreviewH = Math.max(PROMPT_SPLIT_PREVIEW_MIN_H, Math.min(PROMPT_SPLIT_PREVIEW_MAX_H, Math.round(promptSplitResizeState.startH + dy)));
        node.promptSplitPreviewHeight = newPreviewH;
        node.h = Math.max(promptNodeMinHeight(node), Math.round(promptSplitResizeState.startNodeH + (newPreviewH - promptSplitResizeState.startH)));
        node.w = Math.max(Number(node.w) || 0, 316);
        node.scale = 1;
        updateNodeElementDuringResize(node);
        const list = world.querySelector(`.image-node[data-id="${CSS.escape(node.id)}"] .prompt-node-segments`);
        if(list) list.style.height = `${promptNodeSplitPreviewHeight(node)}px`;
        return;
    }
    if(pendingMediaNodeDrag && !dragState){
        const dx = e.clientX - pendingMediaNodeDrag.startX;
        const dy = e.clientY - pendingMediaNodeDrag.startY;
        if(Math.abs(dx) + Math.abs(dy) > 6){
            const origin = {
                startX: pendingMediaNodeDrag.startX,
                startY: pendingMediaNodeDrag.startY,
                startWorld: pendingMediaNodeDrag.startWorld
            };
            const nodeId = pendingMediaNodeDrag.nodeId;
            pendingMediaNodeDrag = null;
            if(startCanvasNodeDrag(e, nodeId, origin)){
                suppressNodeClickUntil = Date.now() + 180;
                updateDragNodePositions(e);
            }
        }
        return;
    }
    if(thumbDragState){
        const dx = e.clientX - thumbDragState.startX;
        const dy = e.clientY - thumbDragState.startY;
        const source = nodes.find(n => n.id === thumbDragState.nodeId);
        if(!thumbDragState.detached && Math.abs(dx) + Math.abs(dy) > 6){
            const canDetachThumb = source && (isSmartGroupNode(source) ? (source.images || []).length >= 1 : (source.images || []).length > 1);
            if(canDetachThumb){
                const img = source.images[thumbDragState.imgIndex];
                if(img){
                    commitPendingUndo();
                    undoSuppressed = true;
                    applyNodeMetaToImage(img, source);
                    source.images.splice(thumbDragState.imgIndex, 1);
                    if(isSmartGroupNode(source)){
                        arrangeSmartGroupMembers(source, {skipUndo:true, syncDom:true});
                    } else if(source.images.length <= 1){
                        source.title = '图片';
                        delete source.w;
                        delete source.h;
                        source.scale = MEDIA_NODE_DEFAULT_SCALE;
                        inheritNodeMetaFromImage(source);
                    }
                    const point = screenToWorld(e);
                    selectedId = '';
                    selectedImage = {nodeId:'', index:-1};
                    const newNode = createImageNodeAt(point, [img], {select:false, skipUndo:true});
                    undoSuppressed = false;
                    dragState = {id:newNode.id, startX:e.clientX, startY:e.clientY, ox:newNode.x, oy:newNode.y, startWorld:screenToWorld(e), startVx:viewport.x, startVy:viewport.y, thumbDetached:true};
                    document.body.classList.add('smart-node-drag');
                    shell?.classList?.add('smart-node-drag');
                    if(window.CanvasTrash?.closeMorePopover) window.CanvasTrash.closeMorePopover();
                    thumbDragState.detached = true;
                    render();
                }
            }
        }
        if(thumbDragState.detached) thumbDragState = null;
        else return;
    }
    if(panState){
        const dx = e.clientX - panState.startX;
        const dy = e.clientY - panState.startY;
        if(Math.abs(dx) + Math.abs(dy) > 3) didPan = true;
        viewport.x = panState.ox + dx;
        viewport.y = panState.oy + dy;
        applyViewport({ isPanning: true });
        return;
    }
    if(!dragState) return;
    updateDragNodePositions(e);
    checkEdgeAutoPan(e.clientX, e.clientY);
};
window.onmouseup = e => {
    pendingMediaNodeDrag = null;
    removeSmartDragFloatingGhost();
    stopEdgeAutoPan();
    renderSmartGuideLines([]);
    document.body.classList.remove('smart-node-drag');
    shell?.classList?.remove('smart-node-drag');
    document.body.classList.remove('smart-node-resize');
    if(connectionEraseState){
        const changed = finishConnectionErase();
        connectionEraseState = null;
        shell.classList.remove('connection-erasing');
        clearConnectionEraseTrail();
        if(changed) scheduleSave();
        return;
    }
    if(portDragState){
        const drag = portDragState;
        portDragState = null;
        shell.classList.remove('port-dragging');
        clearPortDragVisual();
        handlePortDrop(drag, e);
        return;
    }
    if(selectionState) finishSelection(e);
    if(previewCompareDrag) previewCompareDrag = false;
    if(panoramaState.drag){
        panoramaState.drag = null;
        document.getElementById('previewStage')?.classList.remove('panning');
    }
    if(previewPanDrag){
        previewPanDrag = null;
        document.getElementById('previewStage')?.classList.remove('panning');
    }
    if(imageEditPanDrag) imageEditPanDrag = null;
    if(resizeState){
        const node = nodes.find(n => n.id === resizeState.id);
        const rect = node ? nodeRect(node) : null;
        const changed = rect && (Math.abs(rect.width - resizeState.startW) > 1 || Math.abs(rect.height - resizeState.startH) > 1);
        if(changed){
            commitPendingUndo();
        } else { discardPendingUndo(); }
        resizeState = null;
        if(changed) render();
        scheduleSave();
    }
    if(llmInstructionResizeState){
        const node = nodes.find(n => n.id === llmInstructionResizeState.id);
        const changed = node && promptLlmInstructionHeight(node) !== llmInstructionResizeState.startH;
        document.body.classList.remove('smart-node-resize', 'smart-llm-instr-resize');
        if(changed) commitPendingUndo(); else discardPendingUndo();
        llmInstructionResizeState = null;
        render();
        scheduleSave();
    }
    if(promptSplitResizeState){
        const node = nodes.find(n => n.id === promptSplitResizeState.id);
        const changed = node && promptNodeSplitPreviewHeight(node) !== promptSplitResizeState.startH;
        document.body.classList.remove('smart-node-resize', 'smart-prompt-split-resize');
        if(changed) commitPendingUndo(); else discardPendingUndo();
        promptSplitResizeState = null;
        render();
        scheduleSave();
    }
    if(pendingMediaNodeDrag){
        pendingMediaNodeDrag = null;
    }
    if(thumbDragState){
        if(!thumbDragState.detached) discardPendingUndo();
        thumbDragState = null;
    }
    if(panState) {
        panState = null;
        shell.classList.remove('panning');
        syncAttachedMenusForActiveNode();
        checkViewportLostState();
        if(typeof saveViewportMemory === 'function') saveViewportMemory(true);
        scheduleSave();
        setTimeout(() => { didPan = false; }, 0);
    }
    if(smartMinimapDrag){
        smartMinimapDrag = false;
    }
    if(dragState){
        const draggedNode = nodes.find(n => n.id === dragState.id);
        try {
            let stateChanged = false;
            const hit = document.elementFromPoint(e.clientX, e.clientY);
            const assetW = (assetPanel && assetPanel.getBoundingClientRect().width) || 458;
            const droppedOnAssetPanel = assetLibraryOpen && hit && (assetPanel?.contains(hit) || assetDropZone?.contains(hit) || e.clientX <= Math.min(assetW, window.innerWidth - 60));
            if(droppedOnAssetPanel && draggedNode && (draggedNode.images || []).length){
                const imagesToSave = (draggedNode.images || []).filter(img => img?.url);
                (dragState.group || [{id:dragState.id, ox:dragState.ox, oy:dragState.oy}]).forEach(item => {
                    const n = nodes.find(x => x.id === item.id);
                    if(n){ n.x = item.ox; n.y = item.oy; }
                });
                setAssetDragOver(false);
                discardPendingUndo();
                clearDropHighlight();
                removeSmartDragFloatingGhost();
                dragState = null;
                document.body.classList.remove('smart-node-drag');
                shell?.classList?.remove('smart-node-drag');
                render();
                scheduleSave();
                (async () => {
                    for(const img of imagesToSave){
                        await addUrlToAssetLibrary(img.url, img.name || draggedNode.title || '归档素材');
                    }
                    assetSource = 'library';
                    await loadAssetLibrary();
                    toast(`已成功归档 ${imagesToSave.length} 个素材至资产库`);
                })();
                return;
            }
            const hasDragMoved = Boolean(
                dragState.thumbDetached ||
                Math.hypot(e.clientX - dragState.startX, e.clientY - dragState.startY) > 3 ||
                (dragState.group || []).some(item => {
                    const n = nodes.find(x => x.id === item.id);
                    return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
                }) ||
                (draggedNode && (Math.abs((Number(draggedNode.x) || 0) - dragState.ox) > 1 || Math.abs((Number(draggedNode.y) || 0) - dragState.oy) > 1))
            );
            const autoTarget = (hasDragMoved && draggedNode && dragState.ctrlGroup) ? dragConnectTargetFor(draggedNode, screenToWorld(e)) : null;
            const insertHit = (hasDragMoved && draggedNode?.type === 'smart-loop' && dragState.ctrlGroup && (dragState.group || []).length <= 1)
                ? insertionConnectionForNode(draggedNode)
                : null;
            const draggedRect = (hasDragMoved && draggedNode) ? nodeRect(draggedNode) : null;
            const groupTarget = (hasDragMoved && draggedNode && (draggedNode.images || []).length && (dragState.group || []).length <= 1 && draggedRect)
                ? rectOverlapNode(draggedNode.id, draggedRect.x, draggedRect.y, draggedRect.width, draggedRect.height, dragState.groupIds)
                : null;
            // 拖入分组：单个节点、多选（批量拖入）或整个分组（其成员会并入目标分组）都允许并入主分组下的目标分组。
            // 目标分组由主拖动节点的中心命中决定；smartGroupTargetForDraggedNode 已排除正在被拖动的节点/分组。
            const draggedNodes = (dragState.group || []).map(item => nodes.find(n => n.id === item.id)).filter(Boolean);
            const smartGroupTarget = (hasDragMoved && draggedNode) ? smartGroupTargetForDraggedNode(draggedNode) : null;
            if(
                insertHit &&
                insertLoopNodeIntoConnection(draggedNode, insertHit)
            ){
                stateChanged = true;
                render();
            } else if(
                smartGroupTarget &&
                addDraggedNodesToSmartGroup(draggedNodes.length ? draggedNodes : [draggedNode], smartGroupTarget)
            ){
                stateChanged = true;
                render();
            } else if(
                groupTarget &&
                dragState.ctrlGroup &&
                (groupTarget.images || []).length > 1 &&
                mergeImageNodesIntoGroup(draggedNode.id, groupTarget.id)
            ){
                stateChanged = true;
                render();
            } else if(
                draggedNode &&
                autoTarget &&
                dragState.ctrlGroup &&
                (dragState.group || []).length <= 1 &&
                canAutoConnectDraggedNode(draggedNode, autoTarget) &&
                connectInputNode(draggedNode.id, autoTarget.id)
            ){
                stateChanged = true;
                restoreDraggedNodePosition();
                if(selectedId === draggedNode.id) selectedId = '';
                render();
            } else if(draggedNode && (draggedNode.images || []).length && (dragState.group || []).length <= 1){
                const r = nodeRect(draggedNode);
                const target = rectOverlapNode(draggedNode.id, r.x, r.y, r.width, r.height, dragState.groupIds);
                if(target && isSmartGroupNode(target)){
                    if((dragState.group || []).some(item => {
                        const n = nodes.find(x => x.id === item.id);
                        return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
                    })) stateChanged = true;
                } else if(target && dragState.ctrlGroup && !isSmartGroupNode(target) && canAutoConnectDraggedNode(draggedNode, target)){
                    stateChanged = true;
                    connectInputNode(draggedNode.id, target.id);
                    if(!dragState.thumbDetached) restoreDraggedNodePosition();
                    if(selectedId === draggedNode.id) selectedId = '';
                    render();
                } else if((dragState.group || []).some(item => {
                    const n = nodes.find(x => x.id === item.id);
                    return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
                })){
                    stateChanged = true;
                }
            } else if((dragState.group || []).some(item => {
                const n = nodes.find(x => x.id === item.id);
                return n && (Math.abs((Number(n.x) || 0) - item.ox) > 1 || Math.abs((Number(n.y) || 0) - item.oy) > 1);
            }) || (draggedNode && (Math.abs((draggedNode.x || 0) - dragState.ox) > 1 || Math.abs((draggedNode.y || 0) - dragState.oy) > 1))){
                stateChanged = true;
            }
            if(dragState.thumbDetached) stateChanged = true;
            // 拖拽释放时的退组与贴合判定：
            // 只有当节点的中心点真正移出其所在分组的物理边界，或者拖入了其他目标分组时才脱组；
            // 若在组内微调/移动，则保留成员身份，并自动适应更新分组外框尺寸。
            if(hasDragMoved && draggedNode && draggedNode.groupId){
                const currentParentGroup = nodes.find(g => g.id === draggedNode.groupId && isSmartGroupNode(g));
                if(currentParentGroup){
                    const isOutside = isNodeOutsideGroupBounds(draggedNode, currentParentGroup);
                    if(isOutside && !smartGroupTarget){
                        if(pruneSmartGroupMembershipsForNode(draggedNode)){
                            stateChanged = true;
                            // 移出后若分组变为空组，自动清理空壳
                            cleanupEmptySmartGroups();
                            // 若旧分组仍有其他成员，贴合剩余成员尺寸
                            fitSmartGroupBounds(currentParentGroup);
                            render();
                        }
                    } else if(!isOutside){
                        // 在组内移动：保持成员关系，贴合组尺寸
                        fitSmartGroupBounds(currentParentGroup);
                        stateChanged = true;
                    }
                }
            } else if(hasDragMoved && draggedNode && !smartGroupTarget && pruneSmartGroupMembershipsForNode(draggedNode)){
                stateChanged = true;
                cleanupEmptySmartGroups();
                render();
            }
            if(stateChanged) {
                commitPendingUndo();
                suppressNodeClickUntil = Date.now() + 180;
            } else {
                discardPendingUndo();
                // User just clicked the node without dragging: select immediately
                if(draggedNode && (!selectedId || selectedId !== draggedNode.id)){
                    selectedId = draggedNode.id;
                    selectedIds = [];
                    selectedImage = {nodeId:'', index:-1};
                    syncSelectionUi();
                    updateComposer();
                }
            }
        } finally {
            if(dragState && dragState.thumbDetached) suppressNodeClickUntil = Date.now() + 180;
            try {
                if(draggedNode && draggedNode.groupId){
                    const parentG = nodes.find(g => g.id === draggedNode.groupId && isSmartGroupNode(g));
                    if(parentG?.isFrameGroup && !parentG.gridSplitGroup){
                        fitSmartGroupBounds(parentG);
                    }
                }
            } catch(_){}
            clearDropHighlight();
            loopInsertPreview = null;
            // 结束前抓取最终坐标：拖动过程的广播是节流发送的，缺了这次补发，
            // 队友会停在中间帧坐标，连线按偏掉的位置绘制（表现为漂移）。
            const finalDragNodes = (() => {
                if(!dragState) return [];
                const ids = [dragState.id, ...(dragState.group || []).map(item => item?.id)].filter(Boolean);
                return [...new Set(ids)].map(id => {
                    const n = nodes.find(item => item.id === id);
                    if(!n) return null;
                    const nx = Number(n.x);
                    const ny = Number(n.y);
                    if(!Number.isFinite(nx) || !Number.isFinite(ny)) return null;
                    return {id, x: nx, y: ny};
                }).filter(Boolean);
            })();
            dragCommitUntil = Date.now() + 800;
            dragState = null;
            document.body.classList.remove('smart-node-drag');
            shell?.classList?.remove('smart-node-drag');
            const _activeSelNode = selectedNode();
            if(_activeSelNode){
                positionComposerForNode(_activeSelNode);
                if(typeof positionFloatingToolbarForNode === 'function') positionFloatingToolbarForNode(_activeSelNode);
            }
            if(typeof positionMultiSelectionToolbar === 'function') positionMultiSelectionToolbar();
            window.LanSyncAdapter?.sendDragStateClear?.(finalDragNodes);
            scheduleSave();
            scheduleConnectionLayerRefresh();
        }
    }
};
shell.addEventListener('wheel', e => {
    cancelViewportAnimation();
    if(e.target.closest('.composer,.smart-back,.canvas-side-nav,.canvas-bottom-toolbar,.minimap-top-bar,#minimapTopBar,.smart-minimap,#minimap,.smart-top-actions,.smart-top-btn,.image-edit-modal,.asset-panel,.asset-toggle,.smart-log-toggle,.smart-shortcut-toggle,.smart-workflow-toggle,.workflow-transfer-panel,.log-modal,.shortcut-modal,.prompt-node-segments,.prompt-node-text,.prompt-node-llm,.smart-group-list,.minimax-library-list,.minimax-ref-track,[data-thumb-scroll]')) return;
    e.preventDefault();
    const rect = shell.getBoundingClientRect();
    const sx = e.clientX - rect.left;
    const sy = e.clientY - rect.top;
    const currentScale = safeScale(viewport.scale);
    const before = {x:(sx - viewport.x) / currentScale, y:(sy - viewport.y) / currentScale};
    const factor = Math.exp(-e.deltaY * 0.001);
    const nextScale = safeScale(currentScale * factor);
    viewport.scale = nextScale;
    if(Number.isFinite(before.x) && Number.isFinite(before.y)){
        viewport.x = sx - before.x * nextScale;
        viewport.y = sy - before.y * nextScale;
    }
    applyViewport({isZooming:true});
    scheduleSave();
}, {passive:false});
