shell.ondrop = async e => {
    stopEdgeAutoPan();
    e.preventDefault();
    if(e.target.closest('.image-node')) return;
    const dtFiles = [...(e.dataTransfer?.files || [])];
    const wfFile = dtFiles.find(item => /\.(json|zip)$/i.test(item.name || ''));
    if(wfFile){
        importSmartWorkflowFile(wfFile);
        return;
    }
    const p = screenToWorld(e);
    const assetRaw = e.dataTransfer.getData('application/x-smart-asset');
    if(assetRaw){
        try {
            const asset = JSON.parse(assetRaw);
            if(asset?.url) {
                if(asset.kind === 'workflow' || asset.type === 'workflow'){
                    loadWorkflowItemToCanvas(asset);
                    return;
                }
                pushUndo();
                const isVideo = asset.kind === 'video' || assetMediaKind(asset) === 'video';
                if(isVideo){
                    createVideoGenNodeAt(p, [assetNodeImageFromItem(asset)], {skipUndo:true, select:true});
                } else {
                    createImageNodeAt(p, [assetNodeImageFromItem(asset)], {skipUndo:true, select:true});
                }
                render();
                scheduleSave();
            }
            return;
        } catch {}
    }
    const payload = await resolveSmartImageDropPayload(e.dataTransfer);
    if(payload.type === 'none') return;
    await handleSmartImageDropPayload(payload, '', {point:p, forceNew:true});
};
