function handleCanvasDeleteKey(e){
    const isDeleteKey = e.key === 'Delete' || e.key === 'Backspace' || e.key === 'Del'
        || e.code === 'Delete' || e.code === 'Backspace'
        || e.keyCode === 46 || e.keyCode === 8;
    if(!isDeleteKey || e.ctrlKey || e.metaKey || e.altKey || e.isComposing) return;
    if(isEditableTarget(e.target) || e.target?.closest?.('button, [role="button"]')) return;
    if(isCanvasModalOpen()) return;

    // 1. 优先删除卡片内选中的单张素材 (selectedImage)
    if(selectedImage?.nodeId && Number(selectedImage.index) >= 0 && selectedIds.length <= 1){
        const targetNode = nodes.find(n => n.id === selectedImage.nodeId);
        if(targetNode){
            e.preventDefault();
            e.stopPropagation();
            const imgNodeId = selectedImage.nodeId;
            const imgIndex = Number(selectedImage.index);
            deleteImage(imgNodeId, imgIndex);
            return;
        }
    }

    // 2. 删除选中的节点 (单选或多选)
    const ids = selectedNodeIds();
    if(!ids.length) return;
    e.preventDefault();
    e.stopPropagation();
    pushUndo();
    ids.forEach(id => {
        undoSuppressed = true;
        deleteNode(id);
        undoSuppressed = false;
    });
    render();
    scheduleSave();
}
window.addEventListener('keydown', handleCanvasDeleteKey, true);
window.addEventListener('message', e => {
    if(e.data?.type === 'canvas_delete_key'){
        handleCanvasDeleteKey({
            key: 'Delete',
            code: 'Delete',
            keyCode: 46,
            preventDefault: () => {},
            stopPropagation: () => {},
            target: document.body
        });
    }
});
window.addEventListener('keydown', e => {
    const key = String(e.key || '').toLowerCase();
    if((e.code === 'Space' || e.key === ' ') && !e.ctrlKey && !e.metaKey && !e.altKey && !isEditableTarget(e.target)){
        const active = selectedNode();
        if(active?.type === 'smart-minimax'){
            const nodeEl = [...(world?.querySelectorAll?.('.image-node') || [])].find(item => item.dataset.id === active.id);
            const playBtn = nodeEl?.querySelector?.('[data-minimax-play-timeline]');
            if(playBtn){
                e.preventDefault();
                playBtn.click();
                return;
            }
        }
    }
    if(key === 'r' && !isEditableTarget(e.target)) isRKeyDown = true;
    if(imageEditModal.classList.contains('open') && imageEditMode === 'preview' && !isEditableTarget(e.target)){
        if(e.key === 'ArrowLeft' || e.key === 'ArrowRight'){
            e.preventDefault();
            if(!seekPreviewVideoFrames(e.key === 'ArrowLeft' ? -1 : 1)){
                navigatePreviewImage(e.key === 'ArrowLeft' ? -1 : 1);
            }
            return;
        }
    }
    if(!e.ctrlKey && !e.metaKey && !e.altKey && !isEditableTarget(e.target)){
        if(key === 'a'){
            if(e.repeat) return;
            e.preventDefault();
            toggleAssetLibrary();
            return;
        }
    }
    if((e.ctrlKey || e.metaKey) && key === 'c' && !isEditableTarget(e.target)){
        const selectionText = window.getSelection?.().toString() || '';
        if(selectionText) return;
        e.preventDefault();
        copySelectedNodes();
        return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'v' && !isEditableTarget(e.target) && nodeClipboard?.nodes?.length){
        const requestedAt = Date.now();
        setTimeout(() => {
            if(lastImagePasteAt >= requestedAt) return;
            if(lastNodePasteAt >= requestedAt) return;
            pasteNodes();
        }, 90);
    }
    if(e.key === 'Escape' && document.getElementById('saveWorkflowModal')?.classList.contains('open')){
        e.preventDefault();
        e.stopPropagation();
        closeSaveWorkflowModal();
        return;
    }
    if(e.key === 'Escape' && document.getElementById('cinemaPreviewModal')?.classList.contains('open')){
        closeCinemaPreview();
        return;
    }
    if(e.key === 'Escape' && imageEditModal.classList.contains('open')){
        closeImageEditor();
        return;
    }
    if(e.key === 'Escape'){
        if(smartNodeContextMenu?.classList.contains('open')){
            closeSmartNodeContextMenu();
            e.preventDefault();
            return;
        }
        if(typeof isArrangeMenuOpen === 'function' && isArrangeMenuOpen()){
            closeMultiSelectArrangeMenu();
            return;
        }
        if(canvasSelectionToolActive || selectedNodeIds().length > 1){
            cancelCanvasSelection();
            return;
        }
        SmartPanelManager.closeAll();
    }
    if((e.ctrlKey || e.metaKey) && (key === 'y' || (e.shiftKey && key === 'z')) && !isEditableTarget(e.target)){
        e.preventDefault();
        performRedo();
        return;
    }
    if((e.ctrlKey || e.metaKey) && !e.shiftKey && key === 'z' && !isEditableTarget(e.target)){
        e.preventDefault();
        performUndo();
        return;
    }
    if((e.ctrlKey || e.metaKey) && e.shiftKey && key === 'g' && !isEditableTarget(e.target)){
        e.preventDefault();
        const ids = selectedIds.length ? selectedIds.slice() : (selectedId ? [selectedId] : []);
        const ok = ids.map(id => ungroupNode(id)).some(Boolean);
        if(ok) return;
    }
    if((e.ctrlKey || e.metaKey) && key === 'g' && !e.shiftKey && !isEditableTarget(e.target)){
        e.preventDefault();
        groupSelectedNodes();
    }
});
