assetPanelUploadInput?.addEventListener('change', async event => {
    const files = Array.from(event.target.files || []);
    if(assetPanelUploading || !files.length) return;
    assetPanelUploading = true;
    if(assetUploadBtn) assetUploadBtn.disabled = true;
    try {
        const targetCatId = (assetPanelFolder && !['all', '*', 'canvas', 'upload'].includes(assetPanelFolder))
            ? assetPanelFolder
            : (activeAssetCategoryId || (assetTab === 'workflow' ? 'workflows' : 'characters'));

        let successCount = 0;
        for(const file of files){
            if(file.name.endsWith('.zip') || file.name.endsWith('.json')){
                const form = new FormData();
                form.append('files', file);
                form.append('library_id', activeAssetLibraryId || 'default');
                form.append('category_id', targetCatId);
                const res = await fetch('/api/asset-library/workflows/upload', { method: 'POST', body: form });
                if(res.ok){
                    const data = await res.json();
                    setAssetLibraryFromResponse(data);
                    successCount++;
                }
            } else {
                const uploaded = await uploadFiles([file]);
                for(const up of uploaded){
                    if(up?.url){
                        await addUrlToAssetLibrary(up.url, up.name || file.name, { category_id: targetCatId });
                        successCount++;
                    }
                }
            }
        }
        await loadAssetLibrary();
        toast(`成功上传 ${successCount} 个资产`);
    } catch(error){
        toast(error.message || '上传资产失败');
    } finally {
        assetPanelUploading = false;
        if(assetUploadBtn) assetUploadBtn.disabled = false;
        event.target.value = '';
        renderAssetLibrary();
    }
});
