// 浮动工具栏只有一个动作入口。按下阶段立即处理，click 仅作为键盘/无 pointer 事件环境的兜底。
const handledSmartToolbarButtons = new WeakMap();
function handleSmartToolbarActionEvent(event, directButton=null){
    const btn = directButton || event.target.closest?.('#smartNodeFloatingMenu [data-smart-node-action], #smartNodeFloatingMenu [data-smart-group-action], #smartNodeFloatingMenu [data-smart-multi-action]');
    if(!btn) return false;
    event.stopPropagation();
    event.stopImmediatePropagation?.();
    // 不要 preventDefault：它会吞掉后续 click，浏览器会把 click 打到按钮消失后的节点/画布上。
    if(event.type === 'pointerdown' || event.type === 'mousedown'){
        armCanvasToolClickGuard(event, 520);
    }
    const now = Date.now();
    const lastHandledAt = Number(handledSmartToolbarButtons.get(btn) || 0);
    // pointerdown 后紧接着的 mousedown/click 属于同一次用户操作，不得再次执行。
    if(lastHandledAt && now - lastHandledAt < 500){
        return true;
    }
    // 键盘 Enter/Space 只有 click(detail=0)，允许它正常触发；普通 click 在按下事件已处理时只兜底去重。
    handledSmartToolbarButtons.set(btn, now);
    clearImageClickTimer();
    if(btn.dataset.smartMultiAction){
        runSmartMultiToolbarAction(btn.dataset.smartMultiAction);
        return true;
    }
    const nodeId = btn.dataset.nodeId || '';
    const node = nodes.find(item => String(item.id) === String(nodeId));
    if(!node) return true;
    selectedId = node.id;
    selectedIds = [node.id];
    if(btn.dataset.smartGroupAction){
        selectedImage = {nodeId:'', index:-1};
        runSmartGroupToolbarAction(node.id, btn.dataset.smartGroupAction);
    } else {
        selectedImage = {nodeId:node.id, index: smartNodeToolbarImageIndex(node)};
        runSmartNodeToolbarAction(node.id, btn.dataset.smartNodeAction);
    }
    return true;
}
composer.addEventListener('pointerdown', event => event.stopPropagation());
composer.addEventListener('mousedown', event => event.stopPropagation());
