promptInput.addEventListener('keydown', event => {
    if(mentionPicker?.classList.contains('open')){
        const options = mentionPicker.querySelectorAll('.mention-option');
        if(event.key === 'ArrowDown'){
            if(options.length){
                event.preventDefault();
                event.stopPropagation();
                options[mentionFocusedIndex]?.classList.remove('focused');
                mentionFocusedIndex = (mentionFocusedIndex + 1) % options.length;
                options[mentionFocusedIndex]?.classList.add('focused');
                options[mentionFocusedIndex]?.scrollIntoView?.({block:'nearest'});
                return;
            }
        }
        if(event.key === 'ArrowUp'){
            if(options.length){
                event.preventDefault();
                event.stopPropagation();
                options[mentionFocusedIndex]?.classList.remove('focused');
                mentionFocusedIndex = (mentionFocusedIndex - 1 + options.length) % options.length;
                options[mentionFocusedIndex]?.classList.add('focused');
                options[mentionFocusedIndex]?.scrollIntoView?.({block:'nearest'});
                return;
            }
        }
        if(event.key === 'Enter' || event.key === 'Tab'){
            if(options.length){
                event.preventDefault();
                event.stopPropagation();
                const selectedBtn = options[mentionFocusedIndex] || options[0];
                const idx = Number(selectedBtn.dataset.mentionIndex);
                const item = mentionPicker._items?.[idx];
                if(item){
                    if(mentionInsertMode === 'manual-ref') addManualReferenceToSelectedNode(item);
                    else insertMentionToken(item, mentionQuery);
                }
                return;
            }
        }
        if(event.key === 'Escape'){
            event.preventDefault();
            event.stopPropagation();
            closeMentionPicker();
            return;
        }
    } else if(event.key === 'Escape'){
        closeMentionPicker();
    }
});
