function getStudioViewportMemoryKey(){
    const cid = (typeof canvas !== 'undefined' && canvas && canvas.id) ? String(canvas.id) : 'default';
    return 'studio_viewport_mem_' + cid;
}
let saveViewportMemoryTimer = null;
function saveViewportMemory(immediate = false){
    if(immediate){
        if(saveViewportMemoryTimer){
            clearTimeout(saveViewportMemoryTimer);
            saveViewportMemoryTimer = null;
        }
        saveViewportMemoryDirect();
        return;
    }
    if(saveViewportMemoryTimer) clearTimeout(saveViewportMemoryTimer);
    saveViewportMemoryTimer = setTimeout(() => {
        saveViewportMemoryTimer = null;
        saveViewportMemoryDirect();
    }, 300);
}
function saveViewportMemoryDirect(){
    try {
        const key = getStudioViewportMemoryKey();
        sessionStorage.setItem(key, JSON.stringify({
            x: viewport.x,
            y: viewport.y,
            scale: viewport.scale,
            selectedId: selectedId || ''
        }));
    } catch(e){
        console.warn('[ViewportMemory] Failed to save/restore viewport:', e);
    }
}
function restoreViewportMemory(){
    try {
        const key = getStudioViewportMemoryKey();
        const raw = sessionStorage.getItem(key);
        if(raw){
            const data = JSON.parse(raw);
            if(Number.isFinite(data.x) && Number.isFinite(data.y) && Number.isFinite(data.scale)){
                viewport.x = data.x;
                viewport.y = data.y;
                viewport.scale = safeScale(data.scale);
                applyViewport();
                if(data.selectedId && nodes.some(n => n.id === data.selectedId)){
                    selectedId = data.selectedId;
                    syncSelectionUi();
                }
                return true;
            }
        }
    } catch(e){
        console.warn('[ViewportMemory] Failed to save/restore viewport:', e);
    }
    return false;
}
document.addEventListener('keydown', event => {
    if(event.key === 'Escape') {
        // Level 1: Cinema lightbox
        if(document.getElementById('cinemaPreviewModal')?.classList.contains('open')){
            closeCinemaPreview(); event.preventDefault(); return;
        }
        // In-place grid cut, video crop or image crop
        if(activeGridCut){
            cancelCanvasGridCut(); event.preventDefault(); return;
        }
        if(typeof activeVideoCrop !== 'undefined' && activeVideoCrop){
            cancelVideoCrop(); event.preventDefault(); return;
        }
        if(typeof activeImageCrop !== 'undefined' && activeImageCrop){
            cancelImageCrop(); event.preventDefault(); return;
        }
        // Level 3: Fullscreen script modal
        if(document.getElementById('fullscreenScriptModal')?.classList.contains('open')){
            closeFullscreenScriptModal(); event.preventDefault(); return;
        }
        // Level 4: Image editor
        if(imageEditModal && imageEditModal.classList.contains('open')){
            closeImageEditor(); event.preventDefault(); return;
        }
        // Level 5: Top-right 4 panels
        if(typeof SmartPanelManager !== 'undefined' && SmartPanelManager.getActivePanel()){
            SmartPanelManager.closeAll(); event.preventDefault(); return;
        }
        // Level 6: Bottom popovers & dropdowns
        const openCtrl = document.querySelector('.smart-control.pinned, .smart-control.open, .smart-popover.open, .composite-popover.open, .model-dropdown-list.open, .canvas-bottom-more-popover.open');
        if(openCtrl){
            if(window.CanvasTrash && document.getElementById('canvasBottomMorePopover')?.classList.contains('open')){
                window.CanvasTrash.close();
            }
            closeAllSmartPopovers(); event.preventDefault(); return;
        }
        // Level 7: Create menu & link menu
        if(createMenu?.classList.contains('open') || document.getElementById('linkCreateMenu')?.classList.contains('open')){
            closeCreateMenu(); closeLinkCreateMenu(); event.preventDefault(); return;
        }
        // Level 8: Deselect node
        if(selectedId || (selectedIds && selectedIds.length > 0)){
            selectedId = ''; selectedIds = []; selectedImage = {nodeId:'', index:-1};
            syncSelectionUi(); scheduleComposerUpdate(10); event.preventDefault(); return;
        }
    }
});
