let typewriterTimer = null;
function typewriterWriteToPrompt(targetText){
    if(!promptInput) return;
    if(typewriterTimer) clearInterval(typewriterTimer);
    const chars = Array.from(targetText || '');
    let idx = 0;
    promptInput.textContent = '';
    autoFitPromptInputHeight();
    typewriterTimer = setInterval(() => {
        if(idx >= chars.length){
            clearInterval(typewriterTimer);
            typewriterTimer = null;
            autoFitPromptInputHeight();
            savePromptDraftForCurrent();
            persistActiveSmartSettings();
            scheduleSave();
            return;
        }
        promptInput.textContent += chars[idx++];
        autoFitPromptInputHeight();
    }, 15);
}

async function triggerPromptEnhance(){
    const currentText = getPromptText().trim();
    const node = activeComposerNode() || selectedNode();
    const isVideo = isSmartVideoNode(node) || settings.apiKind === 'video' || settings.engine === 'volcengine';
    
    if(!currentText){
        toast(isVideo ? '请先输入简要提示词，AI 将为您扩写专业运镜与画面细节' : '请先输入简要提示词，AI 将为您扩写光影、构图、材质与画质细节');
        return;
    }
    const enhanceBtns = [
        document.getElementById('btnPromptEnhance'),
        document.getElementById('fullscreenScriptEnhanceBtn')
    ].filter(Boolean);
    
    enhanceBtns.forEach(btn => {
        btn.classList.add('is-loading');
        btn.disabled = true;
    });
    
    toast(isVideo ? '✨ 正在调用真实 LLM 优化提示词与专业运镜...' : '✨ 正在调用真实 LLM 优化光影、构图与生图细节...');
    
    try {
        const res = await fetch('/api/generate/prompt-enhance', {
            method: 'POST',
            headers: {'Content-Type': 'application/json'},
            body: JSON.stringify({
                prompt: currentText,
                scope_id: smartApiScopeId(),
                target: isVideo ? 'video' : 'image',
                provider: isVideo ? (settings.videoProvider || settings.provider_id || '') : (settings.provider_id || ''),
                model: isVideo ? (settings.videoModel || settings.model || '') : (settings.model || '')
            })
        });
        if(!res.ok){
            const err = await res.json().catch(() => ({}));
            throw new Error(err.detail || '优化失败');
        }
        const data = await res.json();
        const enhanced = data.enhanced_prompt || currentText;
        typewriterWriteToPrompt(enhanced);
        const scriptTextarea = document.getElementById('fullscreenScriptTextarea');
        if(scriptTextarea){
            scriptTextarea.value = enhanced;
            updateFullscreenScriptWordCount();
        }
        toast('✨ 提示词优化完成！已自动写回输入框');
    } catch(e) {
        toast(`提示词优化失败: ${e.message}`);
    } finally {
        enhanceBtns.forEach(btn => {
            btn.classList.remove('is-loading');
            btn.disabled = false;
        });
    }
}

function togglePromptExpand(){
    const promptInputEl = document.getElementById('promptInput');
    const btn = document.getElementById('promptExpandToggleBtn') || document.getElementById('btnPromptExpand');
    if(!promptInputEl || !btn) return;

    const isExpanded = promptInputEl.classList.toggle('is-expanded');
    btn.classList.toggle('is-expanded', isExpanded);

    if(isExpanded){
        btn.title = '收起提示词';
        btn.setAttribute('aria-label', '收起提示词');
    } else {
        btn.title = '展开提示词';
        btn.setAttribute('aria-label', '展开提示词');
    }

    autoFitPromptInputHeight();
    const node = (typeof activeComposerNode === 'function' ? activeComposerNode() : null) || (typeof selectedNode === 'function' ? selectedNode() : null);
    if(node && typeof positionComposerForNode === 'function'){
        positionComposerForNode(node);
    }
}

function updateFullscreenScriptWordCount(){
    const textarea = document.getElementById('fullscreenScriptTextarea');
    const badge = document.getElementById('fullscreenScriptWordCount');
    if(textarea && badge){
        badge.textContent = `${textarea.value.length} 字`;
    }
}


function closeFullscreenScriptModal(){
    const modal = document.getElementById('fullscreenScriptModal');
    if(modal) modal.style.display = 'none';
}

function applyFullscreenScriptModal(){
    const textarea = document.getElementById('fullscreenScriptTextarea');
    if(textarea){
        setPromptText(sanitizePastedPromptText(textarea.value));
        savePromptDraftForCurrent();
        persistActiveSmartSettings();
        scheduleSave();
    }
    closeFullscreenScriptModal();
    toast('已应用长剧本内容');
}

function initPromptTools(){
    const btnEnhance = document.getElementById('btnPromptEnhance');
    if(btnEnhance){
        btnEnhance.addEventListener('click', (e) => {
            e.preventDefault();
            e.stopPropagation();
            triggerPromptEnhance();
        });
    }
    const btnExpand = document.getElementById('promptExpandToggleBtn') || document.getElementById('btnPromptExpand');
    if(btnExpand){
        btnExpand.onpointerdown = btnExpand.onmousedown = (e) => {
            e.stopPropagation();
        };
        btnExpand.onclick = (e) => {
            e.preventDefault();
            e.stopPropagation();
            togglePromptExpand();
        };
    }

    // Modal buttons
    const modalTextarea = document.getElementById('fullscreenScriptTextarea');
    if(modalTextarea){
        modalTextarea.addEventListener('input', updateFullscreenScriptWordCount);
        modalTextarea.addEventListener('keydown', (e) => {
            if((e.ctrlKey || e.metaKey) && e.key === 'Enter'){
                e.preventDefault();
                applyFullscreenScriptModal();
            } else if(e.key === 'Escape'){
                e.preventDefault();
                closeFullscreenScriptModal();
            }
        });
    }
    const modalApplyBtn = document.getElementById('fullscreenScriptApplyBtn');
    if(modalApplyBtn){
        modalApplyBtn.addEventListener('click', applyFullscreenScriptModal);
    }
    const modalCloseBtn = document.getElementById('fullscreenScriptCloseBtn');
    if(modalCloseBtn){
        modalCloseBtn.addEventListener('click', closeFullscreenScriptModal);
    }
    const modalCancelBtn = document.getElementById('fullscreenScriptCancelBtn');
    if(modalCancelBtn){
        modalCancelBtn.addEventListener('click', closeFullscreenScriptModal);
    }
    const modalBackdrop = document.querySelector('.fullscreen-script-backdrop');
    if(modalBackdrop){
        modalBackdrop.addEventListener('click', closeFullscreenScriptModal);
    }
    const modalEnhanceBtn = document.getElementById('fullscreenScriptEnhanceBtn');
    if(modalEnhanceBtn){
        modalEnhanceBtn.addEventListener('click', triggerPromptEnhance);
    }
    const modalCopyBtn = document.getElementById('fullscreenScriptCopyBtn');
    if(modalCopyBtn){
        modalCopyBtn.addEventListener('click', () => {
            if(modalTextarea && modalTextarea.value){
                navigator.clipboard.writeText(modalTextarea.value).then(() => {
                    toast('已复制到剪贴板');
                }).catch(() => {});
            }
        });
    }
    const modalClearBtn = document.getElementById('fullscreenScriptClearBtn');
    if(modalClearBtn){
        modalClearBtn.addEventListener('click', () => {
            if(modalTextarea){
                modalTextarea.value = '';
                updateFullscreenScriptWordCount();
            }
        });
    }
}

window.onload = async () => {
    try {
        if(canvasId){
            const currentRelUrl = `/static/smart-canvas.html${window.location.search || ('?id=' + encodeURIComponent(canvasId))}`;
            localStorage.setItem('studio_last_canvas_frame_url', currentRelUrl);
            window.parent?.postMessage({ type: 'canvas_route_changed', url: currentRelUrl }, '*');
        }
    } catch(e) {}
    try {
        let initialTheme = '';
        try {
            if (window.parent && window.parent !== window) {
                const pt = window.parent.__XXPD_APP__?.currentTheme || window.parent.app?.currentTheme;
                if (pt === 'dark' || pt === 'light') initialTheme = pt;
            }
        } catch(_) {}
        if (!initialTheme) {
            try {
                const lt = localStorage.getItem('studio_theme') || localStorage.getItem('canvas_theme') || localStorage.getItem('xxdp_theme');
                if (lt === 'dark' || lt === 'light') initialTheme = lt;
            } catch(_) {}
        }
        if (!initialTheme) {
            const urlTheme = new URLSearchParams(window.location.search).get('theme');
            if (urlTheme === 'dark' || urlTheme === 'light') initialTheme = urlTheme;
        }
        applyTheme(initialTheme || 'dark');
    } catch(e) {}
    try { if(window.StudioI18n) window.StudioI18n.apply(); } catch(e) {}
    try { if(window.lucide) lucide.createIcons(); } catch(e) {}
    try { await loadConfig(); } catch(e) {}
    try { await loadCanvas(); } catch(e) {}
    try { restoreViewportMemory(); } catch(e) {}
    try { initCinemaPreviewEvents(); } catch(e) {}
    try { initPromptTools(); } catch(e) {}
    try { render(); } catch(e) {}
};

