function cancelVideoCrop(){
    if(!activeVideoCrop) return;
    document.body.classList.remove('in-video-crop');
    
    if(activeVideoCrop.cleanupPointerListeners){
        try { activeVideoCrop.cleanupPointerListeners(); } catch(_) {}
    }
    if(activeVideoCrop.cleanupListeners){
        try { activeVideoCrop.cleanupListeners(); } catch(_) {}
    }
    
    // 移除注入的 UI
    const bars = document.querySelectorAll('.node-video-crop-bar, .video-crop-timeline');
    bars.forEach(el => el.remove());
    
    if(activeVideoCrop.raf) cancelAnimationFrame(activeVideoCrop.raf);
    if(activeVideoCrop.onKeyDown){
        window.removeEventListener('keydown', activeVideoCrop.onKeyDown, { capture: true });
        window.removeEventListener('keydown', activeVideoCrop.onKeyDown);
    }
    
    const nodeEl = document.querySelector(`.image-node[data-id="${CSS.escape(activeVideoCrop.nodeId)}"]`);
    if(nodeEl){
        const video = nodeEl.querySelector('.media-video-card video, .media-card video, .video-thumb video, .image-wrap video, video.node-video-element, video');
        if(video){
            try { video.pause(); } catch(_) {}
            video.setAttribute('controls', '');
        }
    }
    
    const oldNodeId = activeVideoCrop.nodeId;
    window.__activeVideoCropNodeId = null;
    activeVideoCrop = null;
    
    if(composer) composer.style.display = '';

    if(typeof restoreToolSessionViewport === 'function'){
        restoreToolSessionViewport();
    }
    
    if(oldNodeId){
        const node = nodes.find(n => n.id === oldNodeId);
        if(node && isNodeSelected(node.id)){
            positionFloatingToolbarForNode(node);
            updateFloatingToolbar(node);
        }
    }
}

function startVideoCrop(nodeId, imageIndex = 0){
    if(typeof cancelCanvasGridCut === 'function') cancelCanvasGridCut();
    cancelVideoCrop();
    
    const node = nodes.find(n => n.id === nodeId);
    if(!node) return;
    const nodeEl = document.querySelector(`.image-node[data-id="${CSS.escape(nodeId)}"]`);
    if(!nodeEl) return;

    if(typeof focusNodeForToolSession === 'function'){
        focusNodeForToolSession(nodeId, null, 220, 'video-crop');
    }
    
    window.__activeVideoCropNodeId = nodeId;
    document.body.classList.add('in-video-crop');
    panState = null;
    didPan = false;
    shell?.classList.remove('panning');
    if(composer) composer.style.display = 'none';
    if(smartNodeFloatingMenu) smartNodeFloatingMenu.classList.remove('open');
    
    const mediaCard = nodeEl.querySelector('.media-video-card, .media-card, .video-thumb, .image-wrap') || nodeEl;
    let video = mediaCard.querySelector('video.node-video-element, video') || nodeEl.querySelector('video');
    
    // 如果当前节点尚未激活成 video（例如刚刷新后仍是封面 img 状态），立即主动唤醒转换为真实的 video 播放器！
    if(!video){
        const img = mediaCard.querySelector('img[data-preview-kind="video"], img') || nodeEl.querySelector('img[data-preview-kind="video"], img');
        const playBtnEl = mediaCard.querySelector('.smart-video-play') || nodeEl.querySelector('.smart-video-play');
        if(img || playBtnEl){
            try {
                smartActivateVideoPreview(img || playBtnEl);
            } catch(e) {
                console.warn('Auto activate video preview error:', e);
            }
            video = mediaCard.querySelector('video.node-video-element, video') || nodeEl.querySelector('video');
        }
    }
    if(!video){
        const nodeImg = node.images?.[imageIndex] || node.images?.[0];
        const rawUrl = nodeImg?.url || nodeImg?.src || '';
        if(rawUrl){
            const tpl = document.createElement('template');
            tpl.innerHTML = smartVideoPlayerHtml(rawUrl);
            video = tpl.content.firstElementChild;
            if(video){
                const targetWrap = mediaCard.querySelector('.video-thumb, .image-wrap') || mediaCard;
                const existingImg = targetWrap.querySelector('img');
                if(existingImg) existingImg.replaceWith(video);
                else targetWrap.appendChild(video);
            }
        }
    }
    if(!video){
        document.body.classList.remove('in-video-crop');
        window.__activeVideoCropNodeId = null;
        if(composer) composer.style.display = '';
        toast('无法进入视频裁剪：素材尚未加载成可播放视频，请先点选该视频卡片');
        return;
    }
    
    // 安全调整视频时间（防止多媒体 readyState 未就绪或抛出 InvalidStateError 导致拖动中断，禁止调用破坏性的 video.load）
    function safeSeekVideo(targetVideo, time){
        if(!targetVideo || !Number.isFinite(time)) return;
        try {
            if(targetVideo.readyState >= 1){
                const maxT = Number.isFinite(targetVideo.duration) && targetVideo.duration > 0 ? targetVideo.duration : 9999;
                targetVideo.currentTime = Math.max(0, Math.min(maxT, time));
            } else {
                targetVideo._pendingSeekTime = time;
                if(!targetVideo._hasPendingSeekEvent){
                    targetVideo._hasPendingSeekEvent = true;
                    const onReady = () => {
                        targetVideo._hasPendingSeekEvent = false;
                        targetVideo.removeEventListener('loadedmetadata', onReady);
                        targetVideo.removeEventListener('canplay', onReady);
                        if(Number.isFinite(targetVideo._pendingSeekTime)){
                            try {
                                const maxT = Number.isFinite(targetVideo.duration) && targetVideo.duration > 0 ? targetVideo.duration : 9999;
                                targetVideo.currentTime = Math.max(0, Math.min(maxT, targetVideo._pendingSeekTime));
                            } catch(_) {}
                            targetVideo._pendingSeekTime = null;
                        }
                    };
                    targetVideo.addEventListener('loadedmetadata', onReady, { once: true });
                    targetVideo.addEventListener('canplay', onReady, { once: true });
                }
            }
        } catch(_) {}
    }

    // 拖动过程中采用 rAF 节流执行解码器 seek，保证高轮询鼠标下 UI 绝对 60fps 零卡顿
    let pendingSeekTime = null;
    let seekRaf = null;
    function requestSeek(targetTime){
        pendingSeekTime = targetTime;
        if(seekRaf) return;
        seekRaf = requestAnimationFrame(() => {
            seekRaf = null;
            if(pendingSeekTime !== null && activeVideoCrop && video){
                safeSeekVideo(video, pendingSeekTime);
                pendingSeekTime = null;
            }
        });
    }

    // 进入剪辑立即暂停视频，避免自动播放与循环 seek 抢占解码器导致卡死与闪烁
    try { 
        video.pause(); 
        video.removeAttribute('controls');
        video.removeAttribute('autoplay');
        video.autoplay = false;
    } catch(_) {}

    const nodeImg = node.images?.[imageIndex] || node.images?.[0];
    const knownDur = Number(nodeImg?.duration || nodeImg?.videoDuration || (Number.isFinite(video.duration) && video.duration > 0 ? video.duration : 0));
    const initialDur = knownDur > 0 ? knownDur : ((Number.isFinite(video.duration) && video.duration > 0) ? video.duration : 10);

    activeVideoCrop = {
        nodeId,
        imageIndex,
        trimIn: 0,
        trimOut: initialDur,
        duration: initialDur,
        video: video,
        raf: null,
        onKeyDown: null,
        cleanupListeners: null,
        cleanupPointerListeners: null
    };

    const syncVideoMetadata = () => {
        if(!activeVideoCrop || activeVideoCrop.nodeId !== nodeId) return;
        const duration = Number(video.duration);
        if(Number.isFinite(duration) && duration > 0 && activeVideoCrop.duration !== duration){
            const previous = activeVideoCrop.duration;
            activeVideoCrop.duration = duration;
            if(activeVideoCrop.trimOut === previous || activeVideoCrop.trimOut === 10 || activeVideoCrop.trimOut > duration){
                activeVideoCrop.trimOut = duration;
            }
            updateCropTimelineUI?.();
        }
    };
    const onVideoClick = (e) => {
        if(activeVideoCrop && activeVideoCrop.nodeId === nodeId){
            e.stopPropagation();
            togglePlay();
        }
    };
    video.addEventListener('loadedmetadata', syncVideoMetadata);
    video.addEventListener('durationchange', syncVideoMetadata);
    video.addEventListener('click', onVideoClick);
    activeVideoCrop.cleanupListeners = () => {
        video.removeEventListener('loadedmetadata', syncVideoMetadata);
        video.removeEventListener('durationchange', syncVideoMetadata);
        video.removeEventListener('click', onVideoClick);
    };

    // 一体式药丸胶囊结构：微型播放钮 + 胶卷框(居中时长) + 取消钮 + 确认微红钮
    const bar = document.createElement('div');
    bar.className = 'node-video-crop-bar';
    bar.innerHTML = `
        <button type="button" class="vct-btn vct-play-btn" title="播放 / 暂停 (空格)" aria-label="播放">
            <i data-lucide="play" class="vct-icon-play"></i>
            <i data-lucide="pause" class="vct-icon-pause"></i>
        </button>
        <div class="vct-track">
            <div class="vct-thumbs-strip"></div>
            <div class="vct-dim-left"></div>
            <div class="vct-dim-right"></div>
            <div class="vct-selection-border"></div>
            <div class="vct-handle vct-handle-left" data-handle="left" title="拖动调整起点">
                <div class="vct-handle-grip"></div>
            </div>
            <div class="vct-handle vct-handle-right" data-handle="right" title="拖动调整终点">
                <div class="vct-handle-grip"></div>
            </div>
            <div class="vct-duration-badge">
                <span class="vct-duration-text">${initialDur.toFixed(2)}s</span>
            </div>
            <div class="vct-playhead"></div>
        </div>
        <button type="button" class="vct-btn vct-current-frame-btn" title="截取当前帧" aria-label="当前帧">
            <i data-lucide="camera"></i>
        </button>
        <button type="button" class="vct-btn vct-cancel-btn" title="取消 (Esc)" aria-label="取消">
            <i data-lucide="x"></i>
        </button>
        <button type="button" class="vct-btn vct-confirm-btn" title="确认裁剪并生成视频" aria-label="确认">
            <i data-lucide="check"></i>
        </button>
    `;
    
    nodeEl.appendChild(bar);
    if(window.lucide) lucide.createIcons({root: bar});
    
    bar.addEventListener('mousedown', e => e.stopPropagation());
    bar.addEventListener('pointerdown', e => e.stopPropagation());
    
    const playBtn = bar.querySelector('.vct-play-btn');
    const track = bar.querySelector('.vct-track');
    const thumbsStrip = bar.querySelector('.vct-thumbs-strip');
    const currentFrameBtn = bar.querySelector('.vct-current-frame-btn');
    const cancelBtn = bar.querySelector('.vct-cancel-btn');
    const confirmBtn = bar.querySelector('.vct-confirm-btn');
    const playheadEl = bar.querySelector('.vct-playhead');
    const badgeTextEl = bar.querySelector('.vct-duration-text');
    const dimLEl = bar.querySelector('.vct-dim-left');
    const dimREl = bar.querySelector('.vct-dim-right');
    const selBorderEl = bar.querySelector('.vct-selection-border');
    const hLEl = bar.querySelector('.vct-handle-left');
    const hREl = bar.querySelector('.vct-handle-right');
    
    // 纯 CSS class 驱动播放图标显隐，杜绝任何 innerHTML 重建与页面闪烁
    function updatePlayBtnIcon(isPaused){
        playBtn.classList.toggle('is-playing', !isPaused);
        playBtn.title = isPaused ? '播放 / 暂停 (空格)' : '暂停 / 播放 (空格)';
        playBtn.setAttribute('aria-label', isPaused ? '播放' : '暂停');
    }
    
    function updateCropTimelineUI(){
        if(!activeVideoCrop) return;
        const dur = Math.max(0.1, activeVideoCrop.duration);
        const tIn = Math.max(0, Math.min(activeVideoCrop.trimIn, dur));
        const tOut = Math.max(tIn + 0.1, Math.min(activeVideoCrop.trimOut, dur));
        activeVideoCrop.trimIn = tIn;
        activeVideoCrop.trimOut = tOut;
        
        const pIn = (tIn / dur) * 100;
        const pOut = (tOut / dur) * 100;
        const diff = Math.max(0, tOut - tIn);
        
        if(badgeTextEl) badgeTextEl.textContent = diff.toFixed(2) + 's';
        if(dimLEl) dimLEl.style.width = pIn + '%';
        if(dimREl){
            dimREl.style.width = (100 - pOut) + '%';
            dimREl.style.left = pOut + '%';
        }
        if(selBorderEl){
            selBorderEl.style.left = pIn + '%';
            selBorderEl.style.width = (pOut - pIn) + '%';
        }
        if(hLEl) hLEl.style.left = pIn + '%';
        if(hREl) hREl.style.left = pOut + '%';
        if(playheadEl){
            const curr = Number.isFinite(video.currentTime) ? video.currentTime : tIn;
            const pHead = (Math.max(0, Math.min(curr, dur)) / dur) * 100;
            playheadEl.style.left = pHead + '%';
        }
    }
    
    let isLoopSeeking = false;
    function syncPlayhead(){
        if(!activeVideoCrop || !video) return;
        const dur = Math.max(0.1, activeVideoCrop.duration);
        const curr = video.currentTime;
        
        // 循环在选区内播放：增加 isLoopSeeking 锁，避免 16ms 连续发起重复 seek 导致解码器卡死与闪烁
        if(!video.paused && !isLoopSeeking && curr >= (activeVideoCrop.trimOut - 0.05)){
            isLoopSeeking = true;
            safeSeekVideo(video, activeVideoCrop.trimIn);
            const onSeekDone = () => {
                isLoopSeeking = false;
                video.removeEventListener('seeked', onSeekDone);
            };
            video.addEventListener('seeked', onSeekDone, { once: true });
            setTimeout(() => { isLoopSeeking = false; }, 250);
        }
        
        const p = (Math.max(0, Math.min(video.currentTime, dur)) / dur) * 100;
        if(playheadEl){
            playheadEl.style.left = p + '%';
        }
        
        updatePlayBtnIcon(video.paused);
        activeVideoCrop.raf = requestAnimationFrame(syncPlayhead);
    }
    
    function togglePlay(){
        if(video.paused){
            if(video.currentTime >= activeVideoCrop.trimOut - 0.1 || video.currentTime < activeVideoCrop.trimIn){
                safeSeekVideo(video, activeVideoCrop.trimIn);
            }
            video.play().catch(() => {});
        } else {
            video.pause();
        }
        updatePlayBtnIcon(video.paused);
    }
    
    // 键盘左右按键控制红线视频针逐帧前进 / 后退
    function stepPlayhead(direction, stepSec = 0.04){
        if(!activeVideoCrop || !video) return;
        try {
            if(!video.paused) video.pause();
        } catch(_) {}
        
        const dur = Math.max(0.1, activeVideoCrop.duration);
        const minT = Math.max(0, activeVideoCrop.trimIn);
        const maxT = Math.min(dur, activeVideoCrop.trimOut);
        
        const curr = Number.isFinite(video.currentTime) ? video.currentTime : minT;
        let targetTime = curr + direction * stepSec;
        targetTime = Math.max(minT, Math.min(maxT, targetTime));
        targetTime = Number(targetTime.toFixed(3));
        
        safeSeekVideo(video, targetTime);
        const p = (Math.max(0, Math.min(targetTime, dur)) / dur) * 100;
        if(playheadEl){
            playheadEl.style.left = p + '%';
        }
        updatePlayBtnIcon(video.paused);
    }
    
    playBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        togglePlay();
    });
    
    let cleanupDragListeners = null;
    
    track.addEventListener('pointerdown', (e) => {
        e.preventDefault();
        e.stopPropagation();
        try { video.pause(); } catch(_) {}
        
        const handle = e.target.closest('.vct-handle');
        if(handle){
            const handleType = handle.dataset.handle;
            
            const onPointerMove = (moveEvt) => {
                moveEvt.preventDefault();
                moveEvt.stopPropagation();
                if(!activeVideoCrop) return;
                const rect = track.getBoundingClientRect();
                if(!rect.width) return;
                const dur = Math.max(0.1, activeVideoCrop.duration);
                let ratio = (moveEvt.clientX - rect.left) / rect.width;
                ratio = Math.max(0, Math.min(1, ratio));
                const val = ratio * dur;
                
                if(handleType === 'left'){
                    activeVideoCrop.trimIn = Math.min(val, Math.max(0, activeVideoCrop.trimOut - 0.2));
                    requestSeek(activeVideoCrop.trimIn);
                } else {
                    activeVideoCrop.trimOut = Math.max(val, Math.min(dur, activeVideoCrop.trimIn + 0.2));
                    requestSeek(activeVideoCrop.trimOut);
                }
                updateCropTimelineUI();
            };
            
            const onPointerUp = (upEvt) => {
                upEvt?.preventDefault?.();
                upEvt?.stopPropagation?.();
                if(seekRaf){ cancelAnimationFrame(seekRaf); seekRaf = null; }
                if(pendingSeekTime !== null && activeVideoCrop && video){
                    safeSeekVideo(video, pendingSeekTime);
                    pendingSeekTime = null;
                }
                if(cleanupDragListeners){
                    cleanupDragListeners();
                    cleanupDragListeners = null;
                }
                if(activeVideoCrop) activeVideoCrop.cleanupPointerListeners = null;
            };
            
            window.addEventListener('pointermove', onPointerMove, { capture: true, passive: false });
            window.addEventListener('pointerup', onPointerUp, { capture: true });
            window.addEventListener('pointercancel', onPointerUp, { capture: true });
            
            cleanupDragListeners = () => {
                window.removeEventListener('pointermove', onPointerMove, { capture: true });
                window.removeEventListener('pointerup', onPointerUp, { capture: true });
                window.removeEventListener('pointercancel', onPointerUp, { capture: true });
            };
            activeVideoCrop.cleanupPointerListeners = cleanupDragListeners;
            return;
        }
        
        // 点击或拖拽红线视频针（指针游标）
        const seekFromPointer = (clientX) => {
            if(!activeVideoCrop || !video) return;
            const rect = track.getBoundingClientRect();
            if(!rect.width) return;
            const dur = Math.max(0.1, activeVideoCrop.duration);
            let ratio = (clientX - rect.left) / rect.width;
            ratio = Math.max(0, Math.min(1, ratio));
            const val = ratio * dur;
            const targetTime = Math.max(activeVideoCrop.trimIn, Math.min(activeVideoCrop.trimOut, val));
            requestSeek(targetTime);
            const p = (Math.max(0, Math.min(targetTime, dur)) / dur) * 100;
            if(playheadEl) playheadEl.style.left = p + '%';
            updatePlayBtnIcon(video.paused);
        };
        
        seekFromPointer(e.clientX);
        
        const onNeedleMove = (moveEvt) => {
            moveEvt.preventDefault();
            moveEvt.stopPropagation();
            seekFromPointer(moveEvt.clientX);
        };
        
        const onNeedleUp = (upEvt) => {
            upEvt?.preventDefault?.();
            upEvt?.stopPropagation?.();
            if(seekRaf){ cancelAnimationFrame(seekRaf); seekRaf = null; }
            if(pendingSeekTime !== null && activeVideoCrop && video){
                safeSeekVideo(video, pendingSeekTime);
                pendingSeekTime = null;
            }
            if(cleanupDragListeners){
                cleanupDragListeners();
                cleanupDragListeners = null;
            }
            if(activeVideoCrop) activeVideoCrop.cleanupPointerListeners = null;
        };
        
        window.addEventListener('pointermove', onNeedleMove, { capture: true, passive: false });
        window.addEventListener('pointerup', onNeedleUp, { capture: true });
        window.addEventListener('pointercancel', onNeedleUp, { capture: true });
        
        cleanupDragListeners = () => {
            window.removeEventListener('pointermove', onNeedleMove, { capture: true });
            window.removeEventListener('pointerup', onNeedleUp, { capture: true });
            window.removeEventListener('pointercancel', onNeedleUp, { capture: true });
        };
        activeVideoCrop.cleanupPointerListeners = cleanupDragListeners;
    });
    
    // 生成真实的视频胶卷缩略图
    (async function populateThumbs(){
        try {
            const rawSrc = video.currentSrc || video.src || '';
            if(!rawSrc) return;
            const thumbCount = 7;
            for(let i = 0; i < thumbCount; i++){
                const tEl = document.createElement('div');
                tEl.className = 'vct-thumb-item';
                thumbsStrip.appendChild(tEl);
            }
            const offVideo = document.createElement('video');
            offVideo.crossOrigin = 'anonymous';
            offVideo.muted = true;
            offVideo.playsInline = true;
            offVideo.preload = 'auto';
            offVideo.setAttribute('data-url', rawSrc);
            offVideo.src = playbackVideoUrl(rawSrc, true);
            await new Promise(res => {
                if(offVideo.readyState >= 1) return res();
                offVideo.onloadedmetadata = () => res();
                offVideo.onerror = () => res();
                setTimeout(res, 2500);
            });
            const cleanupVideo = () => {
                offVideo.removeAttribute('src');
                offVideo.load();
            };
            const d = offVideo.duration || activeVideoCrop?.duration || 10;
            if(activeVideoCrop && Number.isFinite(d) && d > 0 && Math.abs((activeVideoCrop.duration || 0) - d) > 0.05){
                const prev = activeVideoCrop.duration;
                activeVideoCrop.duration = d;
                if(activeVideoCrop.trimOut === initialDur || activeVideoCrop.trimOut === prev || activeVideoCrop.trimOut > d){
                    activeVideoCrop.trimOut = d;
                }
                updateCropTimelineUI();
            }
            const canvas = document.createElement('canvas');
            canvas.width = 64;
            canvas.height = 36;
            const ctx = canvas.getContext('2d');
            for(let i = 0; i < thumbCount; i++){
                if(!activeVideoCrop || activeVideoCrop.nodeId !== nodeId) break;
                const seekT = (i / Math.max(1, thumbCount - 1)) * Math.max(0.1, d - 0.05);
                offVideo.currentTime = seekT;
                await new Promise(r => {
                    const timer = setTimeout(r, 200);
                    offVideo.onseeked = () => { clearTimeout(timer); r(); };
                });
                try {
                    ctx.drawImage(offVideo, 0, 0, canvas.width, canvas.height);
                    const data = canvas.toDataURL('image/jpeg', 0.65);
                    const el = thumbsStrip.children[i];
                    if(el) el.style.backgroundImage = `url(${data})`;
                } catch(e){}
            }
        } catch(err){
            console.warn('Populate video thumbs error:', err);
        }
    })();
    
    updateCropTimelineUI();
    activeVideoCrop.raf = requestAnimationFrame(syncPlayhead);
    
    activeVideoCrop.onKeyDown = (e) => {
        if(e.key === 'Escape'){
            e.preventDefault();
            e.stopPropagation();
            cancelVideoCrop();
        } else if(e.key === ' ' && !e.target.closest('input,textarea')){
            e.preventDefault();
            e.stopPropagation();
            togglePlay();
        } else if((e.key === 'ArrowLeft' || e.key === 'ArrowRight') && !e.target.closest('input,textarea')){
            e.preventDefault();
            e.stopPropagation();
            const step = e.shiftKey ? 0.5 : (e.ctrlKey || e.altKey ? 0.2 : 0.04);
            stepPlayhead(e.key === 'ArrowLeft' ? -1 : 1, step);
        } else if((e.key === 'i' || e.key === 'I' || e.key === '[') && !e.target.closest('input,textarea')){
            e.preventDefault();
            e.stopPropagation();
            const curr = Number.isFinite(video.currentTime) ? video.currentTime : activeVideoCrop.trimIn;
            activeVideoCrop.trimIn = Math.min(curr, Math.max(0, activeVideoCrop.trimOut - 0.2));
            updateCropTimelineUI();
        } else if((e.key === 'o' || e.key === 'O' || e.key === ']') && !e.target.closest('input,textarea')){
            e.preventDefault();
            e.stopPropagation();
            const curr = Number.isFinite(video.currentTime) ? video.currentTime : activeVideoCrop.trimOut;
            activeVideoCrop.trimOut = Math.max(curr, Math.min(activeVideoCrop.duration, activeVideoCrop.trimIn + 0.2));
            updateCropTimelineUI();
        }
    };
    window.addEventListener('keydown', activeVideoCrop.onKeyDown, { capture: true });
    
    cancelBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        cancelVideoCrop();
    });

    currentFrameBtn.addEventListener('click', async (e) => {
        e.stopPropagation();
        if(!activeVideoCrop || !video) return;
        try { video.pause(); } catch(_) {}
        
        toast('📸 正在截取当前帧...');
        try {
            const canvas = document.createElement('canvas');
            canvas.width = video.videoWidth || 1280;
            canvas.height = video.videoHeight || 720;
            const ctx = canvas.getContext('2d');
            ctx.drawImage(video, 0, 0, canvas.width, canvas.height);
            
            const blob = await new Promise(resolve => canvas.toBlob(resolve, 'image/png'));
            if(!blob) throw new Error('提取帧图片失败');
            
            const item = node.images?.[imageIndex] || node.images?.[0] || {};
            const base = cleanMediaBaseName(node.title || item.name || '视频', '视频');
            const sec = Math.max(0, Number(video.currentTime || 0));
            const m = Math.floor(sec / 60);
            const s = (sec % 60).toFixed(1).padStart(4, '0');
            const timeTag = m > 0 ? `${m}m${s}s` : `${s}s`;
            const frameTitle = appendSemanticActionSuffix(base, timeTag);
            const filename = safeExportFileName(`${frameTitle}.png`, 'frame.png');
            
            let frameItem = null;
            try {
                const uploaded = await uploadFiles([new File([blob], filename, {type:'image/png'})]);
                frameItem = uploaded?.[0];
            } catch(uploadErr) {
                console.warn('Upload frame failed:', uploadErr);
            }
            
            if(!frameItem?.url){
                frameItem = {
                    url: canvas.toDataURL('image/png'),
                    name: filename,
                    kind: 'image',
                    natural_w: canvas.width,
                    natural_h: canvas.height
                };
            } else {
                frameItem.name = filename;
                frameItem.kind = 'image';
                frameItem.natural_w = canvas.width;
                frameItem.natural_h = canvas.height;
            }
            
            pushUndo();
            const rect = nodeRect(node);
            const nodeW = Math.round(rect.width || node.w || 480);
            const nodeH = Math.round(rect.height || node.h || 270);
            const placement = findGridSplitPlacement(node, nodeW, nodeH);
            const newNode = createImageGenNode(placement.x, placement.y, [frameItem], {select:true, skipUndo:true, w: nodeW, h: nodeH});
            newNode.title = frameTitle;
            addConnection(node.id, newNode.id, 'flow');
            selectedIds = [];
            selectedId = newNode.id;
            selectedImage = {nodeId:newNode.id, index:0};
            render();
            scheduleSave();
            toast('📸 当前帧已提取至画布');
        } catch(err) {
            console.error('extractVideoCurrentFrame error:', err);
            toast('提取当前帧失败');
        }
    });
    
    confirmBtn.addEventListener('click', (e) => {
        e.stopPropagation();
        confirmVideoCrop(nodeId);
    });
}

function confirmVideoCrop(nodeId){
    if(!activeVideoCrop || activeVideoCrop.nodeId !== nodeId) return;
    const node = nodes.find(n => n.id === nodeId);
    if(!node) return;
    
    const trimIn = Number(activeVideoCrop.trimIn.toFixed(2));
    const trimOut = Number(activeVideoCrop.trimOut.toFixed(2));
    const duration = Math.max(0.1, Number((trimOut - trimIn).toFixed(2)));
    const index = Number.isFinite(activeVideoCrop.imageIndex) ? activeVideoCrop.imageIndex : 0;
    
    cancelVideoCrop();
    
    const rawImages = node.images || [];
    const srcItem = imageForDisplay(rawImages[index] || rawImages[0]);
    if(!srcItem) return;
    
    const newItem = {
        ...srcItem,
        kind: 'video',
        trimIn,
        trimOut,
        duration
    };
    
    const base = cleanMediaBaseName(node.title || srcItem?.name || '视频', '视频');
    const newTitle = appendSemanticActionSuffix(base, '剪辑');
    newItem.name = `${newTitle}.mp4`;
    
    pushUndo();
    // 使用统一的尺寸计算函数 nodeRect，创建与刷新前后完全一致
    const nr = nodeRect(node);
    const nodeW = Math.round(nr.width || node.w || 480);
    const nodeH = Math.round(nr.height || node.h || 270);
    const placement = findGridSplitPlacement(node, nodeW, nodeH);
    
    let newNode = null;
    if(typeof createVideoGenNode === 'function'){
        newNode = createVideoGenNode(placement.x, placement.y, [newItem], {skipUndo:true, w: nodeW, h: nodeH});
    } else {
        newNode = createNode(placement.x, placement.y, [newItem], {skipUndo:true, w: nodeW, h: nodeH});
    }
    
    if(newNode){
        // 核心数据契约字段显式赋值，绝不依赖临时字段
        newNode.title = newTitle;
        newNode.type = 'smart-video';
        newNode.genKind = 'video';
        newNode.videoCropVersion = 1;
        newNode.isCroppedVideo = true;
        newNode.sourceVideoNodeId = node.id;
        newNode.trimIn = trimIn;
        newNode.trimOut = trimOut;
        newNode.duration = duration;
        newNode.w = nodeW;
        newNode.h = nodeH;
        
        if(typeof addConnection === 'function'){
            addConnection(node.id, newNode.id, 'flow');
        }
        selectedIds = [];
        selectedId = newNode.id;
        selectedImage = {nodeId: newNode.id, index: 0};
    }
    
    render();
    scheduleSave();
    toast(`✂️ 已生成视频剪裁片段 (${trimIn}s - ${trimOut}s)`);
}

// 全局监听带裁剪参数的视频元素播放循环
document.addEventListener('timeupdate', e => {
    const v = e.target;
    if(v && v.matches && v.matches('.node-video-element[data-trim-in]')){
        const tIn = parseFloat(v.dataset.trimIn);
        const tOut = parseFloat(v.dataset.trimOut);
        if(Number.isFinite(tIn) && Number.isFinite(tOut) && tOut > tIn){
            if(v.currentTime < tIn - 0.1){
                v.currentTime = tIn;
            } else if(v.currentTime >= tOut){
                v.currentTime = tIn;
                if(!v.paused) v.play().catch(() => {});
            }
        }
    }
}, true);

document.addEventListener('loadedmetadata', e => {
    const v = e.target;
    if(v && v.matches && v.matches('.node-video-element[data-trim-in]')){
        const tIn = parseFloat(v.dataset.trimIn);
        if(Number.isFinite(tIn) && tIn > 0){
            v.currentTime = tIn;
        }
    }
}, true);
